window.SD = {"headers":{"almanac":{"name":"almanac","summary":"MUME's seasons, moon and time-bound events in a pane, with a planner","api":1,"aliases":[{"name":"almanac","text":"Show or hide the Almanac pane (also: almanac now, plan, lore, add, edit, remove, remind, list, export, import)"}],"keys":[],"settings":[{"name":"remind","type":"number","default":2,"label":"Game hours before an event that a reminder comes (a game hour is a real minute)","min":0,"max":24,"unit":"h"}],"help":["The Almanac pane follows MUME's clock: the game date and hour,","the moon, day and night, the seasons, and the things in Arda","that only happen at certain times (the Dead Knight's slab at","moonrise, the Ingrove wargs at a winter full moon, the Spirit","Knight's door after midnight …). Times are MUME time: \"in 5h\"","is five game hours (five real minutes).","","## Three tabs","  NOW   the moon, the hour, the daylight band, the year band","        and COMING UP: each event with a countdown, or \"now\".","        Click an event to get a reminder (a line in the game","        window and a UI message) a few game hours before.","  PLAN  a calendar of real days: each day shows the seasons it","        passes through. Click a day for its full moons, Dead","        Knight windows and season start. The wheel or ◂ ▸","        change the month.","  LORE  every event with its condition and place; point at a","        name for the note and the source.","","## Your own events","[+ add] on LORE (or almanac add) opens the","event editor. Type a name, a place and a note, then click what","must hold: seasons, months, the time of day, hours, the moon's","phase, the moon up or down, or one moment such as moonrise.","Pick an icon and a colour. The editor says in words what you","chose and when it comes next; Save keeps it. \"edit\" on LORE","(or almanac edit <name>) changes one of yours.","","The clock must know the hour: type time in the game, or wait","for the next sunrise or sunset.","","## Commands","  almanac             show or hide the pane","  almanac now|plan|lore   show the pane on that tab","  almanac add         the event editor","  almanac edit <name>     change one of your events","  almanac remove <name>   remove one of your events","  almanac remind <name>   turn its reminder on or off","  almanac list        the events and when they come, as text","  almanac export      one line with your events, to share","  almanac import <line>   add the events of such a line","","For typing instead of clicking: almanac add <name> = <when>","[@ <place>] [// <note>] and almanac find <when> take a short","text such as \"winter full\", \"moonrise waxing gibbous|full\" or","\"hours 0-3 not winter\".","","The bundled list is a first draft. Your own events and","reminders are kept over a reload."],"problems":[]},"coinlooter":{"name":"coinlooter","summary":"Picks up the coins after your kills","api":1,"aliases":[{"name":"cl","text":"Turn auto-looting on or off (also: cl on, cl off, cl now)"}],"keys":[],"settings":[{"name":"auto","type":"boolean","default":true,"label":"Loot automatically after kills"},{"name":"delay","type":"number","default":0,"label":"Seconds to wait before looting","min":0,"max":10,"step":0.5,"unit":"s"},{"name":"others","type":"boolean","default":false,"label":"Also loot after kills that give you no experience"},{"name":"quiet","type":"boolean","default":true,"label":"Hide 'You can't find any coins' after an auto-loot"}],"help":["When you or your group kill a monster, this script picks up its coins:","- a corpse: it sends \"get coins all.corpse\";","- an undead that disappears into nothing drops its coins on the","floor: it sends \"get all.coins\".","","It only loots after kills that give you experience (\"You receive","your share of experience.\"), so it leaves alone what other players","kill in your room. Player corpses (*Name*) are never looted.","It sends at most one of each command per second.","","cl on and cl off are remembered (they change the setting auto).","Change the rest in the settings."],"problems":[]},"keymanager":{"name":"keymanager","summary":"Keeps your port keys from locate life in a pane, and casts with them","api":1,"aliases":[{"name":"keys","text":"Show or hide the Port keys pane (also: keys list, keys help)"},{"name":"locatel","text":"locatel <name>: store your room's key; locatel <target> <name>: a target's"},{"name":"kpick","text":"Open the last pick window again"},{"name":"nkey","text":"nkey <name> <key>: add a key by hand"},{"name":"teleport","text":"teleport <name>: cast teleport to a key (also portal, scry, watchr)"},{"name":"tsafe","text":"Teleport to the safe key (qtsafe: quickly, psafe: portal)"},{"name":"tv","text":"Show or hide the TVs; tv <name> opens one (also: kecho <name> [rows])"}],"keys":[{"key":"Ctrl+S","text":"Teleport to the safe key (tsafe)"},{"key":"Alt+S","text":"Teleport quickly to the safe key (qtsafe)"}],"settings":[{"name":"hours","type":"number","default":12,"label":"Hours a key works after it was located","min":0.5,"max":24,"unit":"h"},{"name":"tvgag","type":"boolean","default":true,"label":"Hide watch and scry lines from the game text while they go to a TV"},{"name":"tvclose","type":"number","default":0,"label":"Seconds a TV stays open after its watch ends (0: it closes at once)","min":0,"max":120,"step":5,"unit":"s"}],"help":["Locate life gives a key for a room: teleport, portal, scry and","watch room take it. This script stores the keys under short","names and casts with them. A key works only for the character","who located it and only for 12 hours, so each character has","its own keys, and old keys disappear by themselves.","","  locatel home           store the key of the room you stand in","  locatel troll cave     store the key of the troll's room","  teleport home          cast n 'teleport' <home's key>","  portal home            also scry home and watchr home","  cast 'teleport' $home  any command: $home becomes the key","","## The pick window","Every locate life is caught, however you cast it (locatel, your","own alias, or by hand), and opens the pick window: type the","key's name and press Enter. Up and Down choose the hit (or","click a row; a double click or OK stores it), Esc closes. The","name is filled in: the locatel name, else one made up from the","room type or the creature ($hill, $troll), selected so that","typing replaces it. A locatel with a name and a single hit is","stored at once. kpick opens the last window again.","","## The safe key","The first key you store is the safe key (the star in the pane):","Ctrl+S teleports there, Alt+S teleports quickly. Click another","key's star to change it. When the safe key expires, your","freshest key takes over.","","## TV","What watch room and scry show goes to a small pane per key,","a TV, instead of the game text (setting tvgag). Up to four TVs","open side by side from the top left of the game text, two per","row in the order they opened; drag one to move them all.","The title says how long the watch has left (the average of","your last 3 watches), or how long ago the scry was. Lines keep","the game's colours; for 10 seconds their plain text is white,","then grey. A TV closes when its watch ends (setting tvclose","gives it a delay), a scry's TV when its map blink ends (15 s);","one you open yourself (tv <name>, ◻) stays until you close it","or its watch ends. Its lines stay: ◻ or tv <name> shows them.","","A scry also shows the room on the Map pane: it blinks magenta","for 15 seconds (an arrow points to it when it is off the view)","and the map zooms out to show it and you, then back, unless you","moved the map meanwhile. The mark then stays, steady, for three","more minutes. Rooms are found by their name (several","with that name: the 20 nearest); the KEYS line says what it","found, or that the map is off.","","## The Port keys pane","A key with a watch running or a scry in","the last 12 hours has a ◻ before its x: it opens and closes the","TV; it blinks red while a watch runs, and the time column","counts the watch down.","","Click a key's name to rename it (Enter","saves, Esc cancels). The letters are casts: t teleport,","p portal, s scry, w watch room; x deletes (click it twice).","Point at one to see the command. Names are 1 to 10 letters,","digits or _. What changes in your keys is in the UI messages."],"problems":[]},"mapsearch":{"name":"mapsearch","summary":"Finds rooms on the map like MMapper's Find Rooms and marks them","api":1,"aliases":[{"name":"mapsearch","text":"Show or hide the Map search pane (mapsearch <text>: search for it)"}],"keys":[{"key":"Ctrl+F","text":"Show or hide the Map search pane, the cursor in Query"}],"settings":[],"help":["The Map search pane finds rooms on the map, as MMapper's Find","Rooms dialog does. Type in Query and press Enter (or Find).","Search says where to look:","","  Name         the room's name","  Description  the room's description","  Contents     what MMapper saw lying in the room","  Area         the area's name","  Exits        door names","  Notes        the map's notes (Herb: …, Quest: …)","  Flags        mob, load, exit and door flags (rent, shop, herb,","               aggmob, guild, door, climb …)","  All          any of them","","Case and accents do not count: \"o\" finds \"ó\". Choosing another","Search field searches again.","","The results come nearest first: the steps to walk, the room and","its area.","","Click a row to mark the room: it pulses on the map until you","clear it, and the map zooms out to show you and the marked","rooms. When you walk, the map follows you again; the marks","keep pulsing. Mark all marks the rooms in the list (up to 200),","Clear removes the marks, Close hides the pane and clears them.","A new search keeps the marks you made.","","The Map pane must be on with a map loaded.","","  mapsearch          show or hide the pane","  Ctrl+F             show or hide the pane (as mapsearch)","  mapsearch <text>   search for text (with the pane's options)"],"problems":[]},"mercenaries":{"name":"mercenaries","summary":"Keeps track of your hired citizen mercenaries, in a pane","api":1,"aliases":[{"name":"merc","text":"Show or hide the Mercenaries pane (also: merc autopay, merc cost, merc pay, merc list, merc label, merc forget)"}],"keys":[],"settings":[{"name":"autopay","type":"boolean","default":false,"label":"Pay a mercenary by itself when it asks for pay"},{"name":"cost","type":"choice","default":10,"label":"Per payment (20 is paid as 1 gold)","options":[10,20],"unit":"silver"},{"name":"group","type":"boolean","default":true,"label":"Group a new mercenary"},{"name":"minutes","type":"number","default":25,"label":"Minutes one payment buys","min":5,"max":60,"step":5,"unit":"min"},{"name":"warn","type":"number","default":5,"label":"Warn this many minutes before a contract ends (0: never)","min":0,"max":30,"unit":"min"}],"help":["Hire a citizen mercenary by paying it (give 10 silver mercenary,","or give 1 gold mercenary at a higher level). The script gives it","a short name with \"label\" and groups it, and the Mercenaries pane","shows how long its contract has left.","","The price is 10 or 20 silver (paid as 1 gold): click Cost in the","pane's top row to switch, change the setting cost, or let the","script learn it when a mercenary names its price.","","Near the end the mercenary taps you on the shoulder: pay it","within a minute or it leaves. Its row then says PAY DUE: click","that bar to pay, or turn autopay on.","","The letters in a mercenary's row are orders: l lead, r ride,","f flee (ask <name> lead, ride or flee). Point at one to see the","command.","","  merc                show or hide the pane","  merc autopay        turn autopay on or off (also: on, off)","  merc cost [10|20]   switch the price, or set it","  merc pay [name]     pay one mercenary, or all that ask for pay","  merc list           the mercenaries and their time, as text","  merc label <who>    label and track a mercenary by hand, for","                      example merc label 2.mercenary","  merc forget <name>  stop tracking a mercenary","","The contracts are kept over a reload or a new connection."],"problems":[]},"readability":{"name":"readability","summary":"Shorter, colour-coded mob, movement and exit lines","api":1,"aliases":[],"keys":[],"settings":[{"name":"directions","type":"boolean","default":true,"label":"Colour who leaves and arrives, and where"},{"name":"exits","type":"boolean","default":true,"label":"Colour the directions on the Exits line"},{"name":"mobs","type":"boolean","default":true,"label":"Shorten and colour the mobs in a room"},{"name":"flags","type":"boolean","default":true,"label":"Colour (glowing) and (hidden)"},{"name":"arrows","type":"boolean","default":true,"label":"An arrow with each direction (north ▲)"},{"name":"shortnames","type":"boolean","default":true,"label":"Short mob names (off: MUME's own text)"}],"help":["Makes the busy lines of MUME quicker to read. Colours adapt to","your background (Settings → Appearance), so they read on black,","on the dark themes and on paper.","","## Mobs","About 450 known mobs get a short name, and the rest of the","line is dimmed. Dangerous and named mobs are gold, roots","and snares pink, the others keep the normal text colour.","","  A huge, black bear is here, proud heir to the great and","    ancient mountain bears.","  becomes: The huge, black bear is here.   (name in gold)","  Some roots lie here waiting to ensnare weary travellers.","  becomes: A clump of roots is here.       (name in pink)","","Other mobs that are standing, sleeping, lying or fighting keep","their text; only \"is standing here ...\" is dimmed.","","## Movement","The mover keeps its colour, \"leaves\" is dimmed and the","direction is teal with an arrow.","","  A young troll leaves north.   becomes: A young troll leaves north ▲","  Frodo leaves west.            becomes: Frodo leaves ◄ west","  A guard has arrived from above.  (from above in teal)","","## Exits and flags","Each direction on the Exits line is teal; commas, doors and","marks are dim.","","  Exits: (north), =east=, south, /up\\.","","(glowing) is lilac and (hidden) dim, on any line.","","## Turning a part off","Each part has its setting. Turn one off on the Scripts page, or","with #script set, for example:","","  #script set readability shortnames off","  #script set readability arrows off","","With shortnames off a known mob keeps MUME's text, but its name","still has its colour and the rest is dimmed.","","Room descriptions and what players say are never changed.","","The mob list is Lamia's, from Cockpit's readability module.","Thanks, Lamia!"],"problems":[]},"rescue":{"name":"rescue","summary":"Rescues the tank when its hp drops low, and says so","api":1,"aliases":[{"name":"rs","text":"rs <name>: set the tank; rs alone says who it is"}],"keys":[{"key":"F2","text":"Rescue the tank now"}],"settings":[{"name":"below","type":"number","default":40,"label":"Rescue when the tank's hp drops under this","min":10,"max":90,"step":5,"unit":"%"},{"name":"shout","type":"boolean","default":false,"label":"Tell the group when you rescue"}],"help":["Watches your group (GMCP) and rescues the tank when its hp","drops under the setting below. Set the tank first.","","  rs <name>   set the tank (kept over a reload)","  rs          say who the tank is","  F2          rescue the tank now"],"problems":[]},"autoeat":{"name":"autoeat","summary":"Eats and drinks when you need it","api":1,"aliases":[{"name":"ae","text":"Turn it on or off"}],"keys":[{"key":"F9","text":"Eat now"}],"settings":[{"name":"food","type":"string","default":"bread","label":"What to eat"},{"name":"drink","type":"string","default":"water","label":"What to drink from"},{"name":"enabled","type":"boolean","default":true,"label":"Eat and drink by itself"},{"name":"wait","type":"number","default":2,"label":"Seconds before eating","min":0,"max":10,"step":0.5,"unit":"s"},{"name":"portion","type":"choice","default":"one","label":"How much to eat","options":["one","two","all"]}],"help":["Eats when you are hungry and drinks when you are thirsty.","","## Commands","  ae       turn it on or off","  F9       eat now","","Change the food on the Scripts page, or with","#script set autoeat food apple."],"problems":[]}},"code":{"coinlooter":"-- @name     coinlooter\n-- @summary  Picks up the coins after your kills\n-- @api      1\n-- @alias    cl  Turn auto-looting on or off (also: cl on, cl off, cl now)\n-- @setting  auto   boolean true  \"Loot automatically after kills\"\n-- @setting  delay  number  0  0..10 step 0.5 unit s  \"Seconds to wait before looting\"\n-- @setting  others boolean false \"Also loot after kills that give you no experience\"\n-- @setting  quiet  boolean true  \"Hide 'You can't find any coins' after an auto-loot\"\n-- @help     When you or your group kill a monster, this script picks up its coins:\n-- @help     - a corpse: it sends \"get coins all.corpse\";\n-- @help     - an undead that disappears into nothing drops its coins on the\n-- @help     floor: it sends \"get all.coins\".\n-- @help\n-- @help     It only loots after kills that give you experience (\"You receive\n-- @help     your share of experience.\"), so it leaves alone what other players\n-- @help     kill in your room. Player corpses (*Name*) are never looted.\n-- @help     It sends at most one of each command per second.\n-- @help\n-- @help     cl on and cl off are remembered (they change the setting auto).\n-- @help     Change the rest in the settings.\n\n--[[\nHow it works\n\nMUME prints these lines when you kill something:\n\n  You receive your share of experience.\n  Yes! You're beginning to get the idea.\n  You hear an orc's death cry as it collapses.\n  An orc is dead! R.I.P.\n\nThe experience line comes first, so we remember it for a moment\n(\"armed\"), and when the death line follows we loot. A kill by a player\noutside your group has no experience line and is left alone.\n\nThis is a good script to copy: press Duplicate on the Scripts page and\nchange what you like.\n]]\n\n-- ------------------------------------------------------------ state\n\n-- Is auto-looting on? Starts from the `auto` setting; `cl` changes both.\nlocal on = settings.auto\n-- The `auto` value we last saw, so `#script set coinlooter auto ...`\n-- also works while the script runs.\nlocal lastAuto = settings.auto\n\n-- True for a short while after an experience line.\nlocal armed = false\nlocal disarmTimer = nil\n\n-- Commands sent in the last second; we do not send them again until it\n-- has passed (several kills at once need only one \"get\").\nlocal recent = {}\n\n-- How many \"You can't find any coins\" replies we expect to hide.\nlocal expectEmpty = 0\nlocal expectTimer = nil\n\n-- ------------------------------------------------------------ helpers\n\nlocal function isOn()\n  if settings.auto ~= lastAuto then\n    lastAuto = settings.auto\n    on = settings.auto\n  end\n  return on\nend\n\n-- Sends `cmd` unless we sent it less than a second ago.\nlocal function lootWith(cmd)\n  if recent[cmd] then return end\n  recent[cmd] = true\n  tempTimer(1, function() recent[cmd] = nil end)\n\n  send(cmd)\n\n  -- Hide the \"no coins\" reply to this command (the `quiet` setting).\n  if settings.quiet then\n    expectEmpty = expectEmpty + 1\n    if expectTimer then killTimer(expectTimer) end\n    expectTimer = tempTimer(3, function() expectEmpty = 0 end)\n  end\nend\n\n-- Called on a death line. `cmd` is the command that gets the coins.\nlocal function onDeath(cmd)\n  if not isOn() then return end\n  if not (armed or settings.others) then return end\n\n  if settings.delay > 0 then\n    tempTimer(settings.delay, function() lootWith(cmd) end)\n  else\n    lootWith(cmd)\n  end\nend\n\n-- ------------------------------------------------------------ triggers\n\n-- Your kill, or your group's: arm for two seconds.\ntempRegexTrigger(\"^You receive your share of experience\\\\.$\", function()\n  armed = true\n  if disarmTimer then killTimer(disarmTimer) end\n  disarmTimer = tempTimer(2, function() armed = false end)\nend)\n\n-- A monster leaves a corpse. [^*] skips players, who show as *Name*.\ntempRegexTrigger(\"^[^*].* is dead! R\\\\.I\\\\.P\\\\.$\", function()\n  onDeath(\"get coins all.corpse\")\nend)\ntempRegexTrigger(\"^[^*].* has drawn (his|her) last breath! R\\\\.I\\\\.P\\\\.$\", function()\n  onDeath(\"get coins all.corpse\")\nend)\n\n-- An undead leaves no corpse; its coins fall to the floor.\ntempRegexTrigger(\"^[^*].* disappears into nothing\\\\.$\", function()\n  onDeath(\"get all.coins\")\nend)\n\n-- The game's answer when there was nothing to get.\ntempRegexTrigger(\"^You can't find any coins( in any corpse)?\\\\.$\", function()\n  if expectEmpty > 0 then\n    expectEmpty = expectEmpty - 1\n    deleteLine()\n  end\nend)\n\n-- ------------------------------------------------------------ alias\n\ntempAlias(\"^cl(?: (on|off|now))?$\", function()\n  local word = matches[2]\n\n  if word == \"now\" then\n    send(\"get all.coins\")\n    send(\"get coins all.corpse\")\n    return\n  end\n\n  isOn() -- pick up a changed `auto` setting first\n  if word == \"on\" then\n    on = true\n  elseif word == \"off\" then\n    on = false\n  else\n    on = not on\n  end\n\n  -- Remember it for next time (the same as #script set ... auto).\n  setSetting(\"auto\", on)\n\n  if on then\n    cecho(\"<green>Coin looter on.<reset>\")\n  else\n    cecho(\"<yellow>Coin looter off.<reset> Type cl to turn it on again.\")\n  end\nend)\n","rescue":"-- @name     rescue\n-- @summary  Rescues the tank when its hp drops low, and says so\n-- @api      1\n-- @alias    rs      rs <name>: set the tank; rs alone says who it is\n-- @key      F2      Rescue the tank now\n-- @setting  below   number  40  10..90 step 5 unit %  \"Rescue when the tank's hp drops under this\"\n-- @setting  shout   boolean false  \"Tell the group when you rescue\"\n-- @help     Watches your group (GMCP) and rescues the tank when its hp\n-- @help     drops under the setting below. Set the tank first.\n-- @help\n-- @help       rs <name>   set the tank (kept over a reload)\n-- @help       rs          say who the tank is\n-- @help       F2          rescue the tank now\n\nlocal tank = store.get(\"tank\")\nlocal busy = false\n\nlocal function rescue()\n  if busy then return end\n  busy = true\n  send(\"rescue \" .. tank)\n  if settings.shout then\n    send(\"gtell Rescuing \" .. tank .. \"!\")\n  end\n  tempTimer(3, function() busy = false end)\nend\n\nregisterAnonymousEventHandler(\"gmcp.Group\", function()\n  for _, m in ipairs(state.group) do\n    local hp = m.hp\n    if m.name == tank and hp.value and hp.max then\n      if hp.value < hp.max * settings.below / 100 then\n        rescue()\n      end\n    end\n  end\nend)\n\ntempAlias(\"^rs(?: (\\\\w+))?$\", function()\n  local who = matches[2]\n  if who then\n    tank = who\n    store.set(\"tank\", tank)\n  end\n  echo(\"The tank is \" .. tank .. \".\")\nend)\n\ntempKey(\"F2\", rescue)\n","autoeat":"-- @name     autoeat\n-- @summary  Eats and drinks when you need it\n-- @api      1\n-- @alias    ae      Turn it on or off\n-- @key      F9      Eat now\n-- @setting  food    string  bread  \"What to eat\"\n-- @setting  drink   string  water  \"What to drink from\"\n-- @setting  enabled boolean true   \"Eat and drink by itself\"\n-- @setting  wait    number  2  0..10 step 0.5 unit s  \"Seconds before eating\"\n-- @setting  portion choice  one  one|two|all  \"How much to eat\"\n-- @help     Eats when you are hungry and drinks when you are thirsty.\n-- @help\n-- @help     ## Commands\n-- @help       ae       turn it on or off\n-- @help       F9       eat now\n-- @help\n-- @help     Change the food on the Scripts page, or with\n-- @help     #script set autoeat food apple.\n\nlocal function eat()\n  send(\"eat \" .. settings.food)\n  if settings.portion ~= \"one\" then\n    send(\"eat \" .. settings.food)\n  end\nend\n\ntempTrigger(\"You are hungry.\", function()\n  if not settings.enabled then return end\n  tempTimer(settings.wait, eat)\nend)\n\ntempTrigger(\"You are thirsty.\", function()\n  if settings.enabled then send(\"drink \" .. settings.drink) end\nend)\n\ntempAlias(\"^ae$\", function()\n  setSetting(\"enabled\", not settings.enabled)\n  echo(\"Autoeat \" .. (settings.enabled and \"on.\" or \"off.\"))\nend)\n\ntempKey(\"F9\", eat)\n","mercenaries":"-- @name     mercenaries\n-- @summary  Keeps track of your hired citizen mercenaries, in a pane\n-- @api      1\n-- @alias    merc  Show or hide the Mercenaries pane (also: merc autopay, merc cost, merc pay, merc list, merc label, merc forget)\n-- @setting  autopay boolean false \"Pay a mercenary by itself when it asks for pay\"\n-- @setting  cost    choice  10  10|20 unit silver  \"Per payment (20 is paid as 1 gold)\"\n-- @setting  group   boolean true  \"Group a new mercenary\"\n-- @setting  minutes number  25  5..60 step 5 unit min  \"Minutes one payment buys\"\n-- @setting  warn    number  5   0..30 unit min  \"Warn this many minutes before a contract ends (0: never)\"\n-- @help     Hire a citizen mercenary by paying it (give 10 silver mercenary,\n-- @help     or give 1 gold mercenary at a higher level). The script gives it\n-- @help     a short name with \"label\" and groups it, and the Mercenaries pane\n-- @help     shows how long its contract has left.\n-- @help\n-- @help     The price is 10 or 20 silver (paid as 1 gold): click Cost in the\n-- @help     pane's top row to switch, change the setting cost, or let the\n-- @help     script learn it when a mercenary names its price.\n-- @help\n-- @help     Near the end the mercenary taps you on the shoulder: pay it\n-- @help     within a minute or it leaves. Its row then says PAY DUE: click\n-- @help     that bar to pay, or turn autopay on.\n-- @help\n-- @help     The letters in a mercenary's row are orders: l lead, r ride,\n-- @help     f flee (ask <name> lead, ride or flee). Point at one to see the\n-- @help     command.\n-- @help\n-- @help       merc                show or hide the pane\n-- @help       merc autopay        turn autopay on or off (also: on, off)\n-- @help       merc cost [10|20]   switch the price, or set it\n-- @help       merc pay [name]     pay one mercenary, or all that ask for pay\n-- @help       merc list           the mercenaries and their time, as text\n-- @help       merc label <who>    label and track a mercenary by hand, for\n-- @help                           example merc label 2.mercenary\n-- @help       merc forget <name>  stop tracking a mercenary\n-- @help\n-- @help     The contracts are kept over a reload or a new connection.\n\n--[[\nHow it works\n\nMUME's lines about a citizen mercenary you hired (the name in brackets is\nits label):\n\n  A citizen mercenary starts following you.             hired\n  A citizen mercenary (Bubba) taps you on the shoulder.  pay due\n  A citizen mercenary (Bubba) says 'Thank you. I am at your service.'\n                                                         paid, renewed\n  A citizen mercenary (Bubba) leaves and goes to seek another employer.\n  A citizen mercenary (Bubba) is dead! R.I.P.\n\nThe price of one payment is 10 silver, or 1 gold (20 silver) at a higher\nlevel. No log has a mercenary naming its price, so any line a citizen\nmercenary says, tells or asks that names 10 silver, or 1 gold / 20 silver,\nsets the cost setting.\n\nGMCP's Group messages only list the NPCs of your group that are in your\nroom, so a mercenary that is not in the room is \"away\", not gone. It is\ngone after the leave or death line, or a while after its contract ended.\n\nEach mercenary is a record keyed by its label, with the time its contract\nends as wall-clock seconds (getEpoch), so the records can be kept in the\nstore and survive a reload.\n]]\n\n-- ------------------------------------------------------------ constants\n\nlocal NAMES = {\n  \"Bubba\", \"Hank\", \"Cletus\", \"Leroy\", \"Earl\", \"Jeb\", \"Roscoe\", \"Boomer\",\n  \"Buford\", \"Cooter\", \"Dwayne\", \"Gomer\", \"Junior\", \"Merle\", \"Otis\", \"Rufus\",\n  \"Travis\", \"Waylon\", \"Zeke\", \"Clovis\", \"Festus\", \"Hoss\", \"Jethro\", \"Lonnie\",\n  \"Newt\", \"Vern\", \"Wade\", \"Darryl\", \"Skeeter\", \"Pruitt\",\n}\nlocal GRACE = 60           -- seconds to pay after the tap\nlocal GONE_AFTER = 90      -- seconds past the end before a silent mercenary is dropped\nlocal NAME_W = 8           -- the longest name in NAMES\n-- Buttons and links in light grey (the bundled scripts' colours, ADR 0054\n-- round 8); green, red, yellow and the gauges keep their meaning.\nlocal LINK_C = \"#b8b8b8\"\n\n-- ------------------------------------------------------------ state\n\n-- name (lower case) -> { name, ends, state (\"active\" | \"due\"), paid,\n--   present, warned, paying }\nlocal mercs = {}\n-- The label we just asked MUME to set, for the \"Replaced label\" check.\nlocal labelling = nil\n\n-- The cost of one payment in silver (10 or 20) while a change is being\n-- saved: settings.cost changes once setSetting is done.\nlocal costWanted = nil\n\nlocal pane = createPane{id = \"main\", title = \"Mercenaries\", dock = \"right\", rows = 9, cols = 36}\nlocal width = 36\n\nlocal function now() return getEpoch() end\n\nlocal function save()\n  local list = {}\n  for _, m in pairs(mercs) do\n    list[#list + 1] = { name = m.name, ends = m.ends, state = m.state, paid = m.paid, warned = m.warned }\n  end\n  store.set(\"mercs\", list)\nend\n\nlocal function sorted()\n  local list = {}\n  for _, m in pairs(mercs) do list[#list + 1] = m end\n  table.sort(list, function(a, b) return a.name < b.name end)\n  return list\nend\n\nlocal function count()\n  local n = 0\n  for _ in pairs(mercs) do n = n + 1 end\n  return n\nend\n\n-- \"m:ss\" for seconds (never below 0).\nlocal function clock(secs)\n  secs = math.max(0, math.floor(secs))\n  return string.format(\"%d:%02d\", secs // 60, secs % 60)\nend\n\nlocal function contractSecs()\n  return math.max(1, settings.minutes) * 60\nend\n\n-- One payment in silver: 10 or 20 (anything above 15 counts as 20).\nlocal function cost()\n  local c = costWanted or tonumber(settings.cost) or 10\n  return c > 15 and 20 or 10\nend\n\n-- What one payment is given as: \"10 silver\" or \"1 gold\".\nlocal function price()\n  return cost() == 20 and \"1 gold\" or \"10 silver\"\nend\n\nlocal function payCommand(who)\n  return \"give \" .. price() .. \" \" .. who"},"manual":[{"group":"guide","heading":"Getting started","text":["A script is a small Lua 5.4 program that reacts to the game: it can watch the lines MUME sends, add aliases and keys, run timers, read GMCP data and send commands. Scripts live in a library beside the profile, not in it. A script that is on runs whichever profile you use. Scripts run only once you have entered MUME: on the start page, a script that is on shows on · runs when you enter MUME.","Open the Scripts window with the menu bar's Scripts button or #scripts (on a phone, ESC → Options → Scripts), or Scripts on the start page. It lists every script on the left; the selected one opens into the frame on the right:","- [X] turns a script on or off (Space or Enter in the list). A dot after the name means it is running; ! means it is on but failed to load, with the problem in red under its row.","- The frame's top border has the script's name and its buttons: EDIT opens it in the editor, EXPORT, RENAME and DELETE. Inside: its summary and status, its settings, its commands (aliases and keys) and its help in a box of its own.","- Settings are changed right there and saved at once; a script that runs sees the change at once. A switch [ON|OFF] flips with Space, Enter, ← or → or a click. A number ◂ 25 ▸ steps with ← and → (or a click on ◂ ▸); type a digit, or click the value, to type one, Enter keeps it and ESC cancels. A choice ( ) 10 (•) 20 picks with ← and → or a click. A text [ … ] is edited with Enter or a click. A * after a name means the value is not the default. RESET ALL puts every setting of the script back to its default.","- Keys: Tab moves between the buttons, the list and the frame. In the list ↑↓ pick a script and → goes into the frame; there ↑↓ move over the buttons, RESET ALL, each setting and the Help fold, and ESC goes back to the list. PgUp and PgDn scroll the help from anywhere; the wheel scrolls it too.","- Scripts with a lock are bundled with WebCockpit. They are read-only and are updated with each release. DUPLICATE in the editor makes your own copy, named <name>-copy, which you can change. The copy starts off, with the same settings and an empty store.","- EXPORT saves the selected script as a .lua file, or all scripts as one backup file: your own scripts and every script's settings and saved data. Scripts live only in this browser, so keep a backup. IMPORT reads a .lua file (it shows the code first) or a backup (it adds what is missing, turned off).","Your first script, step by step:","- Press NEW and give it a name: a letter, then letters, digits, _ or -, at most 32 characters.","- The editor opens with a template: a header (the comment lines at the top) and one trigger. Change it, or write your own below the header.","- Press Ctrl+S to save. A new script starts off: turn it on with its toggle on the Scripts page, or type #script enable {name}.","- From then on every save applies at once: the script stops, everything it made (triggers, aliases, keys, timers, handlers) is removed, and its code runs again from the top.","The editor helps while you type:","- Errors are marked in red: a dot in the margin, a red band on the line and the message on hover. The code is only compiled for this, never run. The status row above the footer shows the first error. An error elsewhere shows at once; one in the line you are typing (or code you have not finished, such as a function without its end) waits until you leave the line, pause for a moment, or save.","- Tab indents and Shift+Tab dedents (a selection: its lines). Enter after a line that opens a block (function …(), if … then, for … do, while … do, repeat) adds the end (or until) below, unless the block has one already.","- A known name typed in the wrong case is corrected when you finish the word: temptrigger( becomes tempTrigger(. Ctrl+Z undoes the correction, and that spelling is then left alone.","- An error the saved script hit while running is marked on its line too, dashed, until you edit that line or save.","- Ctrl+Space completes API and Lua names and keywords; for, if, while and function expand to a whole block, and Tab moves between its fields. The mouse over a name shows its help. Inside a call's parentheses a pop-up shows its parameters, the current one marked (ESC closes it). F1 opens this manual at the name under the cursor.","- Ctrl+F finds and Ctrl+H replaces. ESC goes back; with unsaved changes it asks first whether to save them. In this manual Ctrl+F finds too; Enter goes to the next match, ESC closes the find row."],"examples":[{"note":"The template NEW starts from:","lang":"lua","code":"-- @name     myscript\n-- @summary  What this script does\n-- @api      1\n-- @help     How to use it: one line per @help tag.\n\ntempTrigger(\"You are hungry.\", function()\n  echo(\"Time to eat!\")\nend)"},{"note":"A first change: eat instead of just saying so.","lang":"lua","code":"tempTrigger(\"You are hungry.\", function()\n  send(\"eat bread\")\nend)"}]},{"group":"guide","heading":"Lua basics","text":["A short primer on the Lua you need for scripts. Every Lua function a script can use is in the Lua reference at the end of this manual, and the editor shows the same help on hover and while you type.","Values. A value is nil (nothing), a boolean (true or false), a number (42, 3.5), a string (\"text\"), a table or a function. type(v) tells which.","Variables. local name = value makes a variable that lives until the end of its block: the function, loop or file it is in. Without local the name is global to your script (other scripts never see it). Use local nearly always. A variable that was never set is nil, not an error.","Strings. Write them in double or single quotes, or as [[long strings]] that keep backslashes and line breaks. Join them with .. (two dots), and #s is the length. Strings have methods: line:upper(), line:find(\"orc\"), line:match(\"%d+\"). They never change in place; the methods return new strings.","Tables. One structure for lists and records. A list: local mobs = { \"orc\", \"troll\" }. mobs[1] is \"orc\" (counting starts at 1), #mobs is 2, and table.insert(mobs, \"wolf\") adds one at the end. A record: local me = { name = \"Gandalf\", hp = 100 }. me.name and me[\"name\"] are the same field. gmcp, state and settings are tables too.","Conditions. if … then … elseif … then … else … end. Compare with == and ~= (not equal), <, <=, > and >=; combine with and, or and not. Only false and nil count as false: 0 and \"\" are true.","Loops. for i = 1, 10 do … end counts. for i, v in ipairs(list) do … end walks a list in order; for k, v in pairs(t) do … end walks every key of a table. while cond do … end and repeat … until cond loop on a condition. break leaves a loop.","Functions. local function name(a, b) … return a + b end. A function is a value: tempTrigger takes one, usually written in place as function() … end. A function may return several values: local ok, err = pcall(f).","Comments. -- starts a comment to the end of the line; --[[ … ]] spans several lines.","Common mistakes:","- Not equal is ~=, not !=.","- Lists start at 1, not 0, and #t counts up to the first nil.","- Join strings with .., not +: \"HP: \" + 5 is an error.","- = sets a variable, == compares: if hp = 0 then is a syntax error.","- A missing field is nil, and indexing nil is an error: gmcp.Char.Vitals.hp fails while gmcp.Char is nil. Test step by step: local v = gmcp.Char and gmcp.Char.Vitals.","- Every if, for, while, do and function needs its own end.","- A local made inside a block is gone after its end; declare it before the block to keep it."],"examples":[{"note":"Values, strings and a condition:","lang":"lua","code":"local name = \"Gandalf\"\nlocal hp, maxhp = 80, 120\nlocal pct = math.floor(hp * 100 / maxhp)\nif pct < 50 and name ~= \"\" then\n  echo(name .. \" is hurt: \" .. pct .. \"%\")\nend"},{"note":"A list and a record:","lang":"lua","code":"local mobs = { \"orc\", \"troll\" }\ntable.insert(mobs, \"wolf\")\nfor i, mob in ipairs(mobs) do\n  echo(i .. \": \" .. mob)\nend\n\nlocal me = { name = \"Frodo\", hp = 40 }\nme.hp = me.hp + 10\nfor key, value in pairs(me) do\n  print(key, value)\nend"},{"note":"A function with a default, and several return values:","lang":"lua","code":"local function split(text, sep)\n  sep = sep or \",\"\n  local a, b = text:match(\"^(.-)\" .. sep .. \"(.*)$\")\n  return a, b\nend\nlocal first, rest = split(\"orc,troll\")"}]},{"group":"guide","heading":"Lua patterns","syntax":[".     any character       %a     letter                %d    digit","%s    space               %w     letter or digit       %p    punctuation","%l    lower case          %u     upper case            %x    hex digit","[abc] a, b or c           [^,]   not a comma           [%w_] word character","*     0 or more, longest  -      0 or more, shortest","+     1 or more           ?      0 or 1","^     start of the text   $      end of the text","( )   capture             %1     the first capture","%b()  a balanced (…)      %f[%w] frontier: a word start","%A %D %S %W …  the opposite: not a letter, not a digit …","%.    a literal dot; % escapes any symbol: %% %( %[ %- %+"],"text":["string.match, find, gmatch and gsub take Lua patterns. They look like regular expressions but are smaller, and % takes the place of the backslash: %d is a digit, %s a space, %. a real dot. tempRegexTrigger and tempAlias take JavaScript regular expressions instead, and tempTrigger plain text.","Patterns have no alternation (a|b), no counted repeats ({2,3}) and no repeats of a group ((ab)+). Use two patterns or a loop instead.","The repeat - takes the shortest run and * the longest: in \"a (b) (c)\", %((.-)%) captures b, but %((.*)%) captures b) (c.","Each ( ) capture gives the text it matched: match returns all captures, or the whole match when there are none. With ^ and $ the pattern must match the whole line.","To find plain text, pass true as find's fourth argument: line:find(\"a.b\", 1, true) looks for a, a dot and b.","A pattern with two or more .- .* or .+ can take very long to fail on a long line, so scripts refuse it with pattern too complex. Anchor it and prefer narrow classes such as %a+, %S+ or [^']+."],"examples":[{"note":"Captures from a game line:","lang":"lua","code":"local who, msg = line:match(\"^(%a+) tells you '(.*)'$\")\nif who then\n  uiMessage(\"tell\", who .. \": \" .. msg)\nend"},{"note":"Every number in a line, and a trimmed, squeezed copy:","lang":"lua","code":"for n in line:gmatch(\"%d+\") do\n  print(tonumber(n))\nend\nlocal trimmed = line:match(\"^%s*(.-)%s*$\")\nlocal squeezed = line:gsub(\"%s+\", \" \")"}]},{"group":"guide","heading":"The header","syntax":["-- @name     <name>","-- @summary  <one line>","-- @api      1","-- @alias    <alias>  <what it does>","-- @key      <key>  <what it does>","-- @setting  <name> <type> <default> [options] \"<label>\"","-- @help     <a line of help>"],"text":["The header is the run of -- comment lines (blank lines may come between them) at the top of the script, before the first line of code. A --[[ block comment also ends it. Each tag is a comment line -- @tag value. Other comment lines in the header are fine; unknown tags are ignored.","- @name is the script's name: a letter, then letters, digits, _ or -, at most 32 characters, unique among all scripts. When you save with a new free name, the script is renamed; a name that is taken or not valid is not used and you get a warning.","- @summary is one line, shown in #script list and at the top of the help.","- @api says which version of the script API the script is written for. It must be 1. A script without it, or with another number, does not load.","- @alias and @key document an alias or a key for the help: the first word is the alias or key, the rest says what it does. They do not make the alias or bind the key; tempAlias and tempKey do. Both may repeat. The profile editor warns about a macro on a key that an enabled script declares with @key.","- @setting declares a setting the player can change: its name (letters, digits and _), its type (number, string, boolean or choice), its default, options, and a label in quotes. A boolean default is true or false (on, off, yes, no, 1 and 0 work too); a string default may be quoted. The script reads it as settings.<name>. A bad @setting line is skipped and shown as a problem in the editor.","- Options come after the default, in any order, before the label. A number takes a range <min>..<max> (the Scripts page and #script set keep the value inside it), step <n> (what ← and → add on the Scripts page, default 1) and unit <word> (shown after the value). A choice lists its options with | between them, such as 10|20 or low|mid|high; the default must be one of them, and when every option is a number the value is a number. A choice takes unit too. A string or a boolean takes no options.","- @help adds one line to the help text. It may repeat; an empty @help gives a blank line.","The help is typeset, not printed line by line, so it reads well at any width:","- Lines that start at the left margin are joined into a paragraph and wrapped to the width. An empty @help line ends the paragraph.","- A line that starts with - (a dash and a space) is a list item; the lines after it continue it until an empty @help line.","- ## Text is a heading.","- Indented lines are kept as they are (examples, game text). When each of them is a term, two or more spaces and a description (a command and what it does), they become a table: the descriptions line up and wrap in their column, and in a narrow window each goes under its term. A line indented further continues the description above it. A term that ends with a full stop is not a table.","Indented means further in than the least indented @help line, so write the tag in one column and indent after it.","The Scripts page and #script help build the script's help from these tags: summary, aliases, keys, the help text and the settings."],"examples":[{"note":"A full header:","lang":"lua","code":"-- @name     autoeat\n-- @summary  Eats and drinks when you need it\n-- @api      1\n-- @alias    ae      Turn it on or off\n-- @key      F9      Eat now\n-- @setting  food    string  bread  \"What to eat\"\n-- @setting  drink   string  water  \"What to drink from\"\n-- @setting  enabled boolean true   \"Eat and drink by itself\"\n-- @setting  wait    number  2  0..10 step 0.5 unit s  \"Seconds before eating\"\n-- @setting  portion choice  one  one|two|all  \"How much to eat\"\n-- @help     Eats when you are hungry and drinks when you are thirsty.\n-- @help\n-- @help     ## Commands\n-- @help       ae       turn it on or off\n-- @help       F9       eat now\n-- @help\n-- @help     Change the food on the Scripts page, or with\n-- @help     #script set autoeat food apple."}]},{"group":"guide","heading":"Triggers","syntax":["tempTrigger(substring, fn) → id","tempRegexTrigger(regex, fn) → id","killTrigger(id)"],"text":["A trigger calls a function for every game line that matches. It is the script's #action.","- tempTrigger(substring, fn) matches a line that contains substring anywhere, as plain text. It is case-sensitive.","- tempRegexTrigger(regex, fn) matches a regular expression. The syntax is JavaScript's, not the PCRE Mudlet uses; the common parts (\\d, \\w, \\s, classes, groups, (?: ), ^ and $) are the same. It is case-sensitive. Use ^ and $ to match a whole line.","In a Lua string a backslash must be doubled: \"^You receive (\\\\d+) coins\\\\.$\". A long string keeps backslashes as they are: [[^You receive (\\d+) coins\\.$]].","Inside the function:","- line is the whole line, as text without colours.","- matches[1] is the matched text, matches[2], matches[3] … the groups of a regex. A group that did not take part is an empty string.","- deleteLine() hides the line (a gag). replaceLine(text) shows text instead; cecho colour tags work in it. highlight(color) colours the whole line, highlight(color, text) each occurrence of text. copy2cecho() returns the line with its colours as cecho tags, to show it in a pane as the game coloured it. isPrompt() tells whether the line is a prompt. lineTags() lists the MUME XML elements the line is in (room, description, exits, say, tell …), so a trigger can skip room descriptions and what players say.","Only the shown copy changes. Other triggers still see the line as the game sent it, and the profile's substitutes, gags and highlights apply to the replaced text. Script highlights are applied last.","Every trigger that matches a line runs: the profile's actions and the script triggers of every script. Rules of the same priority run in this order: the client's own and the profile's first, then script triggers in the order they were made. Script triggers have priority 5, the default for profile actions too.","Text written by echo, cecho and print is not a game line: triggers never see it. Lines the profile prints with #showme are different: triggers see them, as the profile's actions do. On such a line lineTags() is empty and isPrompt() is false.","A trigger lasts until killTrigger(id) or until the script stops. You never need to remove triggers when the script is saved or turned off; WebCockpit does it."],"examples":[{"note":"Pick up the coins after a kill:","lang":"lua","code":"tempTrigger(\"is dead! R.I.P.\", function()\n  send(\"get coins all.corpse\")\nend)"},{"note":"Groups in a regex, and a long string for the backslashes:","lang":"lua","code":"tempRegexTrigger([[^(\\w+) tells you '(.*)'$]], function()\n  uiMessage(\"tell\", matches[2] .. \": \" .. matches[3])\n  highlight(\"light yellow\")\nend)"},{"note":"A trigger that removes itself after the first match:","lang":"lua","code":"local id\nid = tempTrigger(\"You are hungry.\", function()\n  send(\"eat bread\")\n  killTrigger(id)\nend)"}]},{"group":"guide","heading":"Aliases","syntax":["tempAlias(regex, fn) → id","killAlias(id)"],"text":["An alias calls a function for a command you type. tempAlias(regex, fn) matches the command with a JavaScript regular expression.","The regex is not anchored for you, as in Mudlet: \"^cl$\" matches only cl, while \"cl\" matches every command that contains cl. Start almost every alias with ^ and end it with $ or a space.","Inside the function, command (and line) is the typed command, and matches holds the match and its groups, as in a trigger.","Only one alias takes a command. The command is used up: it is not sent to the game, unless the function returns false. Then the next alias that matches may take it, and if none does, it is sent to the game as typed.","A profile alias of the same priority wins over a script alias. Aliases also match commands that expandAlias runs.","killAlias(id) removes an alias. Like triggers, aliases are removed when the script stops."],"examples":[{"note":"An alias with an optional word: cl, cl on, cl off.","lang":"lua","code":"local on = true\n\ntempAlias(\"^cl(?: (on|off))?$\", function()\n  if matches[2] == \"on\" then\n    on = true\n  elseif matches[2] == \"off\" then\n    on = false\n  else\n    on = not on\n  end\n  echo(\"Coin looter \" .. (on and \"on.\" or \"off.\"))\nend)"},{"note":"Watch a command but let it through:","lang":"lua","code":"tempAlias(\"^flee$\", function()\n  cecho(\"<yellow>Fleeing!<reset>\")\n  return false\nend)"}]},{"group":"guide","heading":"Keys","syntax":["tempKey(name, fn) → id","killKey(id)"],"text":["tempKey(name, fn) calls fn when you press the key. Key names are the same as in the profile's #macro:","- Function keys F1 to F24, numpad keys Numpad0 to Numpad9 (Numpad 0 works too), NumpadAdd, NumpadSubtract, NumpadMultiply, NumpadDivide, NumpadDecimal, NumpadEnter.","- Arrow keys ArrowUp (or Up), ArrowDown, ArrowLeft, ArrowRight; Home, End, PageUp, PageDown, Insert, Delete, Tab, Backspace.","- Modifiers before the key, joined with +: Ctrl+F1, Alt+a, Ctrl+Shift+F5, Alt+1. Case does not matter.","- The tt++ escape forms work too: \\eOp is Numpad0, \\e[15~ is F5, ^G is Ctrl+G.","Names are physical keys: Alt+a is the key labelled A on a US keyboard, whatever your layout prints there.","Some keys cannot be bound, and tempKey raises an error for them:","- keys that type text: a letter, digit, space or punctuation key alone or with Shift (with Ctrl or Alt they are fine);","- ESC (it closes what is open, and opens the menu on a phone) and Enter without Ctrl, Alt or Meta (it sends the input line);","- keys the browser keeps: Ctrl+W, Ctrl+T, Ctrl+N, Ctrl+Shift+W, Ctrl+Shift+T, Ctrl+Shift+N, Ctrl+Tab and Ctrl+Shift+Tab.","A profile macro on the same key wins over the script. When two scripts bind the same key, the one bound last wins. The profile editor warns about a macro on a key a running script has bound.","killKey(id) removes a binding. Keys are released when the script stops."],"examples":[{"note":"Numpad keys for fighting:","lang":"lua","code":"tempKey(\"Numpad5\", function()\n  send(\"flee\")\nend)\n\ntempKey(\"Ctrl+F1\", function()\n  send(\"rescue \" .. (getVariable(\"tank\") or \"\"))\nend)"}]},{"group":"guide","heading":"Timers","syntax":["tempTimer(seconds, fn) → id","tempTimer(seconds, fn, true) → id","killTimer(id)","getEpoch() → seconds"],"text":["tempTimer(seconds, fn) calls fn once, after seconds. Fractions work: 0.5 is half a second. 0 calls it as soon as the current work is done.","tempTimer(seconds, fn, true) repeats: fn is called every seconds until you stop it. A repeating timer runs at most every 50 milliseconds (0.05 seconds).","killTimer(id) stops a timer. It returns false when the timer is already gone; a one-shot timer is gone once it has fired.","Timers stop when the script stops. To wait inside a function, start a timer; there is no sleep, and a loop that waits would hit the instruction budget.","Lua's os library is not there. getEpoch() gives the time now in seconds since 1970, with milliseconds as the fraction. Timers stop with the script, so for something that must last past a reload, keep its end time (getEpoch() plus the seconds) in the store and start a new timer for what is left when the script runs again."],"examples":[{"note":"Stand up two seconds after you fall:","lang":"lua","code":"tempTrigger(\"You are knocked to the ground\", function()\n  tempTimer(2, function()\n    send(\"stand\")\n  end)\nend)"},{"note":"Restart a timer instead of stacking several:","lang":"lua","code":"local warn = nil\n\ntempTrigger(\"You feel less protected.\", function()\n  if warn then killTimer(warn) end\n  warn = tempTimer(5, function()\n    cecho(\"<red>Armour is still down!<reset>\")\n    warn = nil\n  end)\nend)"}]},{"group":"guide","heading":"Game time","syntax":["gameTime([epoch]) → table","gameTimeFind(cond[, from[, horizon]]) → start, end","localTime([epoch]) → table","registerAnonymousEventHandler(\"sysGameTimeEvent\", fn)"],"text":["WebCockpit keeps MUME's clock from what the game tells: the time command, sunrise and sunset, room clocks and MSSP. One game minute is one real second, a game hour a real minute, a day 24 real minutes, a month 12 real hours and a year 6 real days.","gameTime() gives the game time now: year, month (1–12), monthName, sindarin, day, hour, minute, weekday, season, period (dawn, day, dusk or night: the sun is up from the dawn hour through the dusk hour, so dawn, day and dusk are sunlit and only night is dark; the night begins at dusk + 1), the month's dawn and dusk hours, precision and moon. gameTime(epoch) gives it at any real time, past or future, such as Saturday 20:00. Both are nil until the clock knows the day.","moon has phase (new, waxing crescent, first quarter, waxing gibbous, full, waning gibbous, third quarter, waning crescent), level (0 new to 12 full), waxing, position (east, southeast, south, southwest, west or below), visible and bright. A dim moon cannot be seen by day.","gameTimeFind(cond) gives the next window of real time where every key of cond holds: season, notSeason, month, hours = {from = h, to = h}, period, moon, moonVisible, or a moment with at (dawn, dusk, midnight, moonrise, moonset, seasonStart). It returns start and end in seconds since 1970, or nil when nothing starts within the horizon (one game year unless you give one). A condition is plain data, so a list of events can live in a table.","localTime(epoch) turns a real time into the browser's local year, month, day, hour, min, sec and wday, for showing real dates.","The event sysGameTimeEvent comes with a kind: hour every game hour, dawn and dusk, moonrise and moonset, phase when the moon's phase changes, season on the first day of a season, and sync when the clock was set from the game. Redraw from it instead of polling. It waits while the clock does not know the hour."],"examples":[{"note":"Count down to the next full moon at night:","lang":"lua","code":"local s = gameTimeFind({moon = \"full\", period = \"night\"})\nif s then\n  echo(\"Full moon night in \" .. math.floor((s - getEpoch()) / 60) .. \" real minutes\")\nend"},{"note":"A line at dusk, and when the season turns:","lang":"lua","code":"registerAnonymousEventHandler(\"sysGameTimeEvent\", function(event, kind)\n  if kind == \"dusk\" then\n    cecho(\"<cyan>Night falls.<reset>\")\n  elseif kind == \"season\" then\n    echo(\"It is \" .. gameTime().season .. \" now.\")\n  end\nend)"},{"note":"Events as data, with real dates:","lang":"lua","code":"local EVENTS = {\n  {name = \"Ingrove wargs\", when = {moon = \"full\", season = \"winter\"}},\n  {name = \"Spirit Knight\", when = {at = \"midnight\", notSeason = \"winter\"}},\n}\n\nfor _, ev in ipairs(EVENTS) do\n  local s = gameTimeFind(ev.when)\n  if s then\n    local t = localTime(s)\n    echo(string.format(\"%s: %02d-%02d %02d:%02d\", ev.name, t.month, t.day, t.hour, t.min))\n  end\nend"}]},{"group":"guide","heading":"Events and GMCP","syntax":["registerAnonymousEventHandler(event, fn) → id","killAnonymousEventHandler(id)"],"text":["registerAnonymousEventHandler(event, fn) calls fn when the event happens. fn gets the event name first, then the event's arguments. Event names are matched without regard to case.","The events:","- gmcp.<Package>.<Message>, such as gmcp.Char.Vitals or gmcp.Room.Info: MUME sent that GMCP message; the data is in the gmcp table. As in Mudlet, every level above the message fires too, the outer one first: Char.Vitals raises gmcp.Char and then gmcp.Char.Vitals, so a handler for gmcp.Char runs for every Char message. fn gets the name of its own level, then the full name: a gmcp.Char handler is called with gmcp.Char and gmcp.Char.Vitals.","- sysLoadEvent: once, for this script only, right after its code has run.","- sysSettingChanged: one of this script's own settings changed (the Scripts page, RESET ALL, #script set, setSetting). The arguments are the setting's name and its new value; settings.<name> already has it. For this script only.","- sysPanesChanged: what getPanes() returns changed: a pane was switched on or off, got or lost its room, moved to another dock or was renamed, or a script pane came or went. No arguments; read getPanes(). It fires at most once per change (none while the player is still dragging) and is slowed down if a handler keeps changing the panes.","- sysGameTimeEvent: the game time moved on (see Game time). The second argument is the kind: sync, hour, dawn, dusk, moonrise, moonset, phase or season.","- sysConnectionEvent: the connection to MUME is made and the login starts.","- sysDisconnectionEvent: the connection was lost or closed. The second argument is the reason.","- The profile's #event names: SESSION CONNECTED (argument mume), SESSION DISCONNECTED (mume and the reason), IAC SB GMCP <Package> (the package and its JSON text) and IAC SB GMCP for every GMCP message. For these fn gets the name in capitals, with single spaces: IAC SB GMCP CHAR.VITALS.","Any other name is accepted but never fires: API 1 has no events of your own.","The gmcp table holds the last data of each GMCP message, as in Mudlet: gmcp.Char.Vitals.hp, gmcp.Room.Info.name. It is read-only.","- Char.Vitals and Char.StatusVars merge: MUME often sends only what changed (a Char.Vitals with just hp), so each message is merged key by key into the last one, and gmcp.Char.Vitals always has every field seen so far. A JSON null removes a field.","- Every other message replaces the last one. They are whole snapshots (Char.Name, Room.Info, Room.Chars.Set, Group.Set, Comm.Channel.List) or one member or event per message (Group.Add, Group.Update, Group.Remove, Room.Chars.Add, Room.Chars.Update, Room.Chars.Remove, Comm.Channel.Text, Event.*), so gmcp.Group.Update is only the latest update of one member.","- Field names with a dash need brackets: gmcp.Char.Vitals[\"hp-string\"].","- A message that has not arrived is nil. Outside a GMCP handler, test the package first: if gmcp.Char and gmcp.Char.Vitals then … end.","- A JSON null field is left out of every gmcp table, so it reads as nil. A false field is kept. A message whose body is null, or that has no body, is nil. Only the JSON text of the IAC SB GMCP events keeps the nulls.","- The table is cleared when a new connection starts. What MUME sent earlier in the session is there even when the first script is turned on later.","The state table is a read-only view of what WebCockpit's own panes know:","- state.char: name, fullname, vitals (the Char.Vitals fields, such as state.char.vitals.hp and state.char.vitals.mood) and status (the Char.StatusVars fields, such as state.char.status.race).","- state.group: a list of your group members, without you: players wherever they are, NPCs only while they are in your room. Each has id, type (ally, enemy or neutral for a player, or npc for a mercenary or key NPC with a label), name, label and hp, mana and mp, each a table { value, max, word }; position (standing, fighting, resting, sleeping …), ride (true while mounted), room (the room's name) and mapid; away (true for a player who is not in your room); and flags, a table of true or false for sanctuary, poison, slept, blind, bashed, snared, wound, hungry, thirsty and waiting. A field MUME has not told is nil; word is the band word such as wounded.","- state.room: the last Room.Info (see below).","Common MUME GMCP messages and their fields:","- Char.Name: name, fullname.","- Char.StatusVars: name, fullname, race, subrace, subclass, level, next-level-xp, next-level-tp.","- Char.Vitals: hp, maxhp, hp-string, mana, maxmana, mana-string, mp, maxmp, mp-string, xp, tp, mood, alertness, position, spell-effort, opponent, buffer, opponent-hits, buffer-hits, sneak, climb, swim, ride, ridden, hidden, carrying, light, fog, weather, mount-moves. Each message carries only some of them.","- Group.Set (a list of members), Group.Add (one member), Group.Update (the id and the fields that changed), Group.Remove (the id of a member, a bare number: gmcp.Group.Remove is a number, not a table). A member has id, name, label (a text or a number), type (you, npc, or for a player ally, enemy or neutral by race), position, room (the room's name), mapid (a number), hp, maxhp, hp-string, mana, maxmana, mana-string, mp, maxmp, mp-string, and the true or false fields ride, blind, bashed, waiting, poison, slept, wound, snared, hungry, thirsty and sanctuary. A player member stays in the group messages wherever it is (mapid says where); an NPC member is only in them while it is in your room, and MUME sends Group.Remove when it is not. Players get hp, mana and mp numbers, NPCs only the -string words. Add, Update and Remove are about one member each, so read the whole group from state.group, which applies them all. state.group and state.char are already updated with a message when your gmcp handler for it runs.","- Room.Info: id, area, name, desc, environment and exits. Each exit (exits.n, exits.e … exits.u, exits.d) may have id (the room it leads to), name (the door's name, when there is a door) and flags (a list such as closed, hidden, road).","- Room.Chars.Set (the characters in the room, a list that replaces the last one), Room.Chars.Add (one character who came), Room.Chars.Update (the changed fields of one character), Room.Chars.Remove (the id of one who left).","- A Room.Chars character has id, name, type (such as npc or player), desc, flags (a list such as hidden, glowing, shrouded, linkless), labels (a list of texts), position (such as standing or resting), weapon (the weapon's text) and fighting, riding and driving (a text or an id). Set and Add carry whole characters; Update carries the id and only the fields that changed, and weapon false there means the weapon was put away. MUME sends null for fighting, riding or driving when there is none, so the field is absent (nil). Room.Chars.Remove is a bare number.","- Room.UpdateExits: the exits of your room that changed, keyed by direction, each with id, name and flags as in Room.Info. A closed door has flags closed and no id: {u = {flags = {\"closed\"}, name = \"blackgate\"}}. Only the changed exits are in it, and gmcp.Room.UpdateExits is the last message only.","- Event.Moved: dir. Event.Achieved: what. Event.Sun: what is light, rise, set or dark. Event.Moon: what is rise or set. Event.Darkness: what is start, grow, shrink, end-soon or end.","- Comm.Channel.Text: channel, talker, talker-type, destination, text. Comm.Channel.List: a list of channels, each with name, caption and command.","- Core.Ping: no body. WebCockpit pings MUME every 10 seconds to keep the link up, so a gmcp.Core handler runs that often. Core.Goodbye: MUME closes the link, sometimes with a text.","- Client.GUI (version, url) and Client.Map (url): MUME sends them before the login without being asked. Scripts can ignore them."],"examples":[{"note":"React to a GMCP message:","lang":"lua","code":"registerAnonymousEventHandler(\"gmcp.Room.Info\", function()\n  local room = gmcp.Room.Info\n  if room.area == \"Bree\" then\n    echo(\"Back in Bree: \" .. room.name)\n  end\nend)"},{"note":"Say hello once connected, and note a lost connection:","lang":"lua","code":"registerAnonymousEventHandler(\"sysConnectionEvent\", function()\n  uiMessage(\"script\", \"Connected.\")\nend)\n\nregisterAnonymousEventHandler(\"sysDisconnectionEvent\", function(event, reason)\n  uiMessage(\"script\", \"Disconnected: \" .. tostring(reason))\nend)"},{"note":"Read the group from state:","lang":"lua","code":"tempAlias(\"^hurt$\", function()\n  for _, m in ipairs(state.group) do\n    local hp = m.hp\n    if hp.value and hp.max and hp.value < hp.max / 2 then\n      echo((m.label or m.name) .. \" is hurt: \" .. hp.value .. \"/\" .. hp.max)\n    end\n  end\nend)"}]},{"group":"guide","heading":"Output","syntax":["send(cmd)","expandAlias(cmd)","echo(text)","cecho(text)","print(...)","uiMessage(source, text)"],"text":["- send(cmd) sends one command to the game as it is. No aliases run, and ; and # are not special.","- expandAlias(cmd) runs cmd as if you had typed it: profile and script aliases match, ; separates commands and # commands work.","- echo(text) writes plain text to the game window. A line break starts a new line.","- cecho(text) writes text with colour tags (below).","- print(...) writes its arguments separated by tabs: strings and numbers as they are, booleans as true or false, nil and tables by their type name.","- uiMessage(source, text) writes a line to the UI messages pane: ▶ SOURCE: text. The source is shown in capitals, at most 20 characters.","What echo, cecho and print write is not a game line: triggers do not see it and runs do not record it. Inside a trigger it shows after the game line; elsewhere at once.","Colour tags for cecho, replaceLine and the text of a script pane, in angle brackets:","- Colour names: <red>, <green>, <orange>, <gold>, <light_blue>, <dark_green>, <hot_pink> and many more (Mudlet's names; case, spaces and _ do not matter).","- The theme's palette: <ansi_red>, <ansi_light_red> … and <ansi_0> to <ansi_255>.","- A background after a colon: <white:red>, or <:blue> for the background alone.","- RGB: <255,128,0>, and <255,128,0:0,0,64> with a background.","- tt++ codes as in #showme: <F88ff00> and <Fa0f> (24-bit), <B204060> (background), <118> (attribute, foreground, background digits; 1 is bold), <aaa> to <fff> (256 colours) and <AAA> to <FFF> (their background), <g00> to <g23> (greys) and <G00> to <G23> (grey background).","- Hex, as in Mudlet's hecho: <#ff8000>, and <#ffffff:#000080> with a background.","- Adaptive colours: a ~ before a colour name, hex or RGB colour (<~gold>, <~#f0c850>, <~240,200,80>, <:~navy> as a background). The colour keeps its hue, and WebCockpit makes it lighter or darker as far as needed to read well on the current background (4.5:1 contrast). On a background where it already reads well it stays as written. When you change the background in Settings → Appearance, text already on screen follows. Use them when a script picks its own colours: they work on black and on paper alike.","- Styles: <b> bold, <i> italic, <u> underline; </b>, </i> and </u> turn them off again.","- <reset> or <r> goes back to the default colours and style.","Anything else in angle brackets is shown as text, also Mudlet's <s> (strikethrough) and <o> (overline), which WebCockpit cannot show.","highlight(color) takes a profile colour name (red, light red, bold yellow, bg blue, or a tt++ code such as <F88ff00>), any of the tags above (<b><orange>, <#ff8000>), or a colour without brackets (orange, white:red, 255,128,0, #ff8000, ~gold for an adaptive colour)."],"examples":[{"lang":"lua","code":"send(\"kill orc\")\nexpandAlias(\"stand;flee\")\necho(\"Plain text.\")\ncecho(\"<green>Ready<reset> to loot. <white:red> DANGER <reset>\")\ncecho(\"<F88ff00>tt++ colours<reset> and <b><#ff8000>hex<reset> work too.\")\ncecho(\"<~gold>Gold<reset> that reads on every background.\")\nprint(\"hp\", 120, true, nil)\nuiMessage(\"loot\", \"Picked up 12 coins.\")"}]},{"group":"guide","heading":"Panes","syntax":["createPane{id, title, short, dock, lane, rows, cols, border, anchor, temporary, at, group, grid}","pane:clear()  pane:echo(text)  pane:cecho(text)","pane:setLine(row, text)  pane:gauge(row, {value, max, color, label, col, width, align, track})","pane:cechoLink(text, fn, hint, opts)  pane:setLink(row, col, len, fn, hint, opts)  pane:setHover(style)  pane:setText(row, col, text)","pane:size()  pane:onResize(fn)  wrapText(text, width, indent)  pane:onWheel(fn)  pane:setTitle(text)","pane:theme()  pane:fillColor(color)  pane:onTheme(fn)","pane:show()  pane:hide()  pane:visible()","pane:close()  pane:onClose(fn)  pane:dock()  pane:wantSize(rows, cols)  pane:setGrip(row, col, len)","getPanes()  setPaneOn(id, on)","pane:setInput(row, col, len, {value, placeholder, maxLength, keys, onSubmit, onCancel, onChange, onBlur, onKey})","field:focus()  field:select()  field:value()  field:setValue(text)  field:remove()","pane:setCheckbox(row, col, {label, checked, hint, onChange})  pane:setRadio(row, col, {group, value, label, checked, hint, onChange})","toggle:checked()  toggle:set(on)  toggle:remove()"],"text":["A script can draw its own pane: text, colours, bars and clickable spans. It docks, floats, toggles and takes a colour like the Character or Group pane.","createPane{id = \"main\", title = \"Status\", dock = \"right\", rows = 6} makes the pane and returns it. Call its methods with a colon: pane:echo(\"hi\"). dock is \"right\", \"left\", \"top\", \"bottom\" or \"float\"; rows (a side dock) and cols (the top or bottom dock) are the size you would like. They only place a new pane: from then on it stays where the player puts it, also after a reload or a restart.","The pane is there while the script runs. Turning the script off, or saving it, takes the pane away; when the script creates it again, it comes back in the same place, with the colour and border the player chose. The Panes box lists it under the built-in panes, by its title and script. createPane with an id the script already has returns the same pane.","Writing text:","- pane:echo(text) and pane:cecho(text) append to the last line, as Mudlet's echo: a \\n starts a new line. cecho takes the colour tags of Output.","- pane:setLine(row, text) replaces one row (from 1), with colour tags. Rows past the end are added. This is the way to draw a status pane: one row per thing, redrawn when it changes.","- pane:gauge(row, {value = 30, max = 60, color = \"orange\", label = \"30 min\"}) draws a full-width bar on a row, like the Group pane's bars. With col and width it draws a bar on part of a row (see Bars).","- pane:clear() empties the pane.","Shades. In pane text, a colour can also be one of the pane's own shades, which follow the pane's colour and the theme (dark or paper): <@track>, <@dim>, <@mid>, <@bg>, <@text>, <@label> and <@glow>, from the faintest to the strongest. A background after a colon works as with colour names: <@text:@dim> is strong text on a soft band, <:@track> only a band. Outside panes these tags are plain text.","A pane keeps at most 500 lines. Text wider than the pane is cut at its edge; wrapText (under Size) breaks it into lines that fit. When there are more lines than rows, the pane scrolls with the wheel, the touchpad or a finger, and one row says how many lines are hidden. anchor says where the view sticks: \"bottom\" (the default) is a console that shows the newest lines and follows new ones while it is scrolled to the end, with ↑ N more rows on top; \"top\" is a list that stays at its first line, with ↓ N more rows at the bottom. Scrolled away, the row reads ↑ N rows above or ↓ N rows below; a click on it goes back.","Bars. pane:gauge fills value of max in whole cells, in color (default green), over the pane's track shade, with label centred over it. align = \"left\" or \"right\" puts the label at one end instead; track = \"grey\" gives the unfilled part a colour of its own, track = false none (the pane shows through, as under the Group pane's bars). On a light (paper) pane the fill is washed to a pastel, as the Group pane's bars.","Without col and width the bar is the whole row and replaces it, as setLine. col (from 1) and width (cells) put a bar on part of a row instead; without width it runs to the pane's right edge, so it follows the pane's size. Bars on a row go under its text: the row keeps its text, links and fields, and a new bar replaces only the bars it overlaps. So one row can hold the three bars of a Group pane row with the name written over them, or a short timer bar after a label. Text over a bar keeps the bar's colour behind it; a space without a background of its own lets the bar and its label show through, so pane:setText further along the row does not blank them. pane:setText keeps the bars; setLine and clear remove them.","Theme. pane:theme() returns the pane's colours now, each as #rrggbb: light (true on a light, paper pane), bg (the pane's background), fg (the colour of text without a tag) and shades, a table with track, dim, mid, bg, text, label and glow, the shades of the <@track> … <@glow> tags. pane:fillColor(color) is the colour pane:gauge would fill with: as is on a dark pane, washed on a light one; with a background tag, <:#rrggbb>, it draws a bar of your own. The player can change these in the settings at any time (the pane's colour, the terminal colours, paper or dark): pane:onTheme(fn) calls fn(theme) once per change, also while the pane is hidden, so redraw there. Text with shade tags and pane:gauge follow by themselves.","Links. Any span, down to one cell, can be clickable and have a tooltip:","- pane:cechoLink(text, fn, hint) appends text (colour tags allowed) that calls fn when clicked.","- pane:setLink(row, col, len, fn, hint) makes len cells of a row, from column col, a link. Draw the text first: setLine, gauge and clear remove the links on their rows.","pane:setText(row, col, text) writes over a few cells of a row and keeps the rest of it, its links included: the way to update a counter. setLink with nil instead of fn is a tooltip only, for cells that explain but do nothing. Hovering stays steady through redraws: a link at the same place keeps its band and open tooltip, and the tooltip shows the new hint.","Hover. pane:setHover(style) chooses how the pane's links look under the pointer: \"band\" (the default) draws a link in the pane's glow band, \"lighten\" makes its own text and background a step lighter (for buttons with their own background, such as <@bg:@glow>), \"none\" leaves it as it is. A link can choose its own with a last table: pane:setLink(row, col, len, fn, hint, {hover = \"none\"}), pane:cechoLink(text, fn, hint, {hover = \"lighten\"}).","The pointer turns into a hand over a link, the link lights up and the hint shows under it. fn runs like any handler, with the instruction budget and the error rules of Sandbox and limits. In the log player and the HTML replay, links do nothing but keep their tooltips.","Size. pane:size() returns rows, cols: the cells the pane has now (0, 0 while it is not shown). pane:onResize(fn) calls fn(rows, cols) when that changes, also when the pane is first shown; draw to fit there.","wrapText(text, width, indent) word-wraps text to width cells and returns the lines as a list, each ready for pane:setLine. Colour tags work and take no cells. Lines break at spaces (a longer word is cut), a \\n always breaks, and a line that starts in a colour opens it again. indent puts that many spaces before every line after the first, and counts toward width. A width under 1 (a pane not shown) only splits at \\n. The examples below include a paragraph redrawn to fit.","Wheel. pane:onWheel(fn) calls fn(dx, dy) when the wheel or the touchpad scrolls over the pane, in whole cells: dx sideways (positive = right), dy up and down (positive = down). Small touchpad moves add up until they make a cell; Shift with a mouse wheel is sideways; Ctrl with the wheel (zoom) never comes. Return true to take the scroll: the pane's own lines and the browser then do nothing with it. Return false or nothing to leave it to them. pane:onWheel(nil) removes the handler. Use it for a pane that scrolls sideways or pages through its own list.","pane:hide() and pane:show() switch the pane off and on, as its close cross and the Panes popup do; the choice is kept. pane:visible() tells whether it is on. pane:setTitle(text) changes the title.","pane:close() takes a pane away; its methods then do nothing, and createPane with the same id makes a new one. An ordinary pane keeps its place for then.","Place and size. border = false makes a pane without a frame the first time (the player can add one with the pane's Border button); in the top or bottom dock such a pane can be a single row. Drag it by its top row (the pointer is a hand there, except over a link): a press there stays a click on the pane until the pointer moves a few pixels. While the pointer is over the pane, framed or not, its close cross covers the last three cells of the top row (on a framed pane it sits on the frame instead), as on a built-in pane, and left of it the pane's Colour, Border and Background buttons (two cells each: the last nine cells in all, fewer on a very narrow pane), drawn over the row's text with no background, so keep links out of them: one under a button cannot be clicked while it shows. A framed pane shows its title on a small hood in the frame's top edge: centred, or moved left on a narrow pane to keep clear of the buttons; where they still reach it, they lie over the hood's right part while the pointer is over the pane. A title too long for its hood is shortened with an ellipsis. cross = false makes a pane without a close cross (and without those buttons), for a bar whose top row ends in buttons; the player turns it off in the Panes box, or your script with pane:hide(), so give it a command for that. tooltip = true is accepted and does nothing (it once showed the title in a small tag on hover). Hovering a pane without a frame outlines it; outline = false leaves it flat (on by default). pane:setGrip(row, col, len) makes len cells of a row a grip, framed or not, docked or floating: the pointer is a grabbing hand there, and a press drags the pane at once (it is never a click). Draw something there that says so, such as <@mid>∷. There is one grip per pane; it stays through setLine and clear, and pane:setGrip(nil) removes it. In the log player and the HTML replay it does nothing. lane = \"own\" gives a new pane a lane of its own at the screen edge of its dock, as high (or wide) as rows (or cols). pane:dock() tells where the pane is now: \"left\", \"right\", \"top\", \"bottom\" or \"float\". pane:wantSize(rows, cols) asks for a size where it is: rows in a side dock; in the top or bottom dock rows sets the lane's height when the pane is alone in it, and cols its width. Asking again for the same size changes nothing, so a size the player dragged stays until you ask for another.","Other panes. getPanes() lists every pane in the Panes box's order, the built-in panes first: {id, title, short, on, shown, dock, script, own} each, own being true for this script's panes. short is a name of up to 8 characters (CHAR, TIME, GRP, COMM, UI, MAP, STAT; createPane{short = \"KEYS\"} sets a script pane's, else the first four letters of its title). setPaneOn(id, on) shows or hides any of them, as the close cross does. The event sysPanesChanged tells when the list changes (a pane switched on or off, moved to another dock, or a script pane came or went).","Temporary panes. createPane{id = \"pick\", temporary = true, rows = 3, cols = 30} makes a short-lived pane, for a choice or a notice: it floats over the game text at rows × cols, above the other panes, and is never listed in the Panes box. at = \"center\" (the default), \"top\", \"bottom\" (just above the input line), \"left\", \"right\" or a corner (\"top-left\", \"top-right\", \"bottom-left\", \"bottom-right\") says where it opens; corners keep several panes apart. The player can move and resize it, and that place is kept on this device: the next pane of the same script and id opens there (Reset layout in the Panes box forgets it). It never docks, since it comes and goes. Several short-lived panes that belong together (one per room watched, say) take group = \"tv\" and grid = {cols = 2}: they tile from at's corner, row by row in the order they opened, the first at the corner, the second beside it, the third below the first; when one closes the ones after it move up to close the gap. Dragging one moves them all and resizing one sets the size of all, kept on this device. Its close cross closes it, and pane:onClose(fn) is called then. show, hide and visible work while it is open. It is in runs like any pane.","Text fields. pane:setInput(row, col, len, opts) puts an editable one-line field on len cells of a row and returns it. opts.value is its text to start with, opts.placeholder the grey text while it is empty, opts.maxLength the most characters. opts.onSubmit(text) runs on Enter, opts.onCancel() on Esc, opts.onChange(text) on every edit, opts.onBlur(text) when the player clicks elsewhere (not on Enter or Esc; the field stays until you remove it), and opts.onKey(key) for Up, Down, PgUp, PgDn, Tab and Shift+Tab (\"ArrowUp\", \"ArrowDown\", \"PageUp\", \"PageDown\", \"Tab\", \"Shift+Tab\"), so the arrows can move a selection while the player types. While a field has the keyboard, macros and tempKey keys do not run; opts.keys lists more keys for onKey, such as {\"Ctrl+F\"} for the key that also shows the pane, so it can close it from the field (Enter and Esc stay the field's own).","A click on the field, or field:focus(), gives it the keyboard; field:select() does too and selects its text, so typing replaces it. Enter, Esc, a click elsewhere or the pane closing give the keyboard back to the input line (onSubmit can call field:focus() again to keep it). While the field has the keyboard, nothing typed reaches the game, your macros or the keys of tempKey. field:value() and field:setValue(text) read and write the text; field:remove() takes the field away. setLine, gauge and clear on its row remove it too, so write the row's text first and add the field after it. The log player and the HTML replay show its text, not editable.","Checkboxes and radio buttons. pane:setCheckbox(row, col, {label = \"Case sensitive\", checked = false, onChange = fn}) draws [ ] Case sensitive from column col and returns it; a click (or a tap) anywhere on it flips it to [x] and calls onChange(checked). pane:setRadio(row, col, {group = \"field\", value = \"name\", label = \"Name\", checked = true, onChange = fn}) draws ( ) Name, or (•) Name when chosen: of the radio buttons of one group in the pane, one is chosen at a time; a click chooses it, unchooses the others and calls its onChange(value) (value defaults to the label). label takes colour tags; hint is a tooltip. toggle:checked() reads it, toggle:set(on) sets it without calling onChange (a radio set on unchooses the rest of its group), toggle:remove() blanks it. They are text and a link: setLine, gauge and clear on the row remove them (toggle:checked() is then nil), and the log player and the HTML replay show them as text.","Pane methods are cheap: they change the pane's content, and the pane is drawn once per screen frame. Updating a pane from a trigger on every line is fine."],"examples":[{"note":"A status pane with a bar and a clickable order:","lang":"lua","code":"local pane = createPane{id = \"status\", title = \"Status\", dock = \"right\", rows = 3}\n\nlocal function draw()\n  local v = gmcp.Char and gmcp.Char.Vitals\n  local hp, max = v and v.hp or 0, v and v.maxhp or 1\n  pane:gauge(1, {value = hp, max = max, color = \"green\", label = \"HP \" .. hp .. \"/\" .. max})\n  pane:setLine(2, \"<yellow>[rest]<reset>  <yellow>[stand]\")\n  pane:setLink(2, 1, 6, function() send(\"rest\") end, \"Rest to heal\")\n  pane:setLink(2, 9, 7, function() send(\"stand\") end, \"Stand up\")\nend\n\nregisterAnonymousEventHandler(\"gmcp.Char.Vitals\", draw)\ndraw()"},{"note":"Group rows with three bars each, the name over them (the bars of the Group pane):","lang":"lua","code":"local pane = createPane{id = \"group\", title = \"Group\", dock = \"right\", rows = 6, anchor = \"top\"}\nlocal COLORS = {hp = \"#005a18\", mana = \"#0000aa\", mp = \"#5a3c1e\"}\n\nlocal function bar(row, col, width, v, kind)\n  local value, max = v and v.value or 0, v and v.max or 1\n  local color = value <= max / 4 and \"red\" or COLORS[kind]\n  pane:gauge(row, {col = col, width = width, value = value, max = max, color = color, track = false})\nend\n\nlocal function draw()\n  local _, cols = pane:size()\n  if cols < 3 then return end\n  local w = cols // 3\n  pane:clear()\n  for i, m in ipairs(state.group) do\n    pane:setLine(i, \"<@text>\" .. (m.label or m.name))\n    bar(i, 1, cols - 2 * w, m.hp, \"hp\")\n    bar(i, cols - 2 * w + 1, w, m.mana, \"mana\")\n    bar(i, cols - w + 1, nil, m.mp, \"mp\")\n  end\nend\n\nregisterAnonymousEventHandler(\"gmcp.Group\", draw)\npane:onResize(draw)"},{"note":"A log pane and an alias that toggles it:","lang":"lua","code":"local log = createPane{id = \"tells\", title = \"Tells\", dock = \"float\", rows = 6, cols = 40}\n\ntempRegexTrigger(\"^(\\\\w+) tells you '(.*)'$\", function()\n  log:cecho(\"<cyan>\" .. matches[2] .. \"<reset>: \" .. matches[3] .. \"\\n\")\nend)\n\ntempAlias(\"^tells$\", function()\n  if log:visible() then log:hide() else log:show() end\nend)"},{"note":"A paragraph that wraps to the pane's width, with a hanging indent:","lang":"lua","code":"local pane = createPane{id = \"note\", title = \"Note\", dock = \"right\", rows = 6}\nlocal msg = \"<yellow>Note:<reset> the ferry leaves at <ansi_light_cyan>dawn<reset>, so be at the dock early.\"\n\npane:onResize(function(rows, cols)\n  pane:clear()\n  for i, l in ipairs(wrapText(msg, cols, 2)) do pane:setLine(i, l) end\nend)"},{"note":"A popup that asks for a name:","lang":"lua","code":"local function askName(fn)\n  local box = createPane{id = \"name\", title = \"Name\", temporary = true, rows = 2, cols = 24}\n  box:setLine(1, \" Name: \")\n  box:setLine(2, \" <ansi_light_black>Enter: ok, Esc: cancel\")\n  local field = box:setInput(1, 8, 14, {\n    placeholder = \"type a name\",\n    maxLength = 10,\n    onSubmit = function(text)\n      box:close()\n      fn(text)\n    end,\n    onCancel = function() box:close() end,\n  })\n  field:focus()\nend\n\ntempAlias(\"^greet$\", function()\n  askName(function(name) send(\"say Hello, \" .. name .. \"!\") end)\nend)"},{"note":"A choice popup that closes itself after ten seconds:","lang":"lua","code":"local function ask(question, choices)\n  local pick = createPane{id = \"pick\", title = question, temporary = true, rows = 1, cols = 30}\n  pick:clear()\n  local col = 2\n  for _, c in ipairs(choices) do\n    pick:cecho(\" <yellow>[\" .. c .. \"]<reset>\")\n    pick:setLink(1, col, #c + 2, function()\n      send(c)\n      pick:close()\n    end, \"Send \" .. c)\n    col = col + #c + 3\n  end\n  pick:onClose(function() echo(\"No choice made.\") end)\n  tempTimer(10, function() pick:close() end)\nend\n\ntempAlias(\"^go$\", function() ask(\"Which way?\", {\"north\", \"south\", \"flee\"}) end)"}]},{"group":"guide","heading":"Map marks","syntax":["mapMark(target, opts, fn)  mapUnmark(handle)  mapFind(query, fn)","mapSearch({text, field, case, regex, max}, fn)  mapPath(id, fn)  mapRoom(id, fn)"],"text":["A script can show rooms on the Map pane: they blink in a colour for a while, and an arrow at the edge points to a room off the view.","mapMark({name = \"A Tunnel\", lines = {…}, exits = \"Exits: north, south.\"}, {color = \"magenta\", duration = 15, focus = true}, fn) finds the rooms with that name (the lines after the name narrow by the description, the Exits: line by the exits; the nearest 20 to you first) and marks them. focus = true zooms out so you and the rooms are in view; when the duration is over the zoom comes back, unless you moved the map yourself meanwhile. linger = 180 then keeps the mark three more minutes, steady and a little dimmer, with its arrows and label. fn(count, total, ids) says what was found.","mapFind(query, fn) only finds: fn(ids, total). mapMark({ids…}) marks rooms by id; mapUnmark(handle) ends a mark early.","duration = 0 keeps a mark, blinking, until mapUnmark or the script stops. focus = \"move\" zooms out to show you and the rooms once, and at your first move to another room the zoom comes back and the map follows you again; the mark stays. Panning or zooming the map yourself first ends it too, and the view stays where you put it. A mark takes up to 200 room ids.","Search. mapSearch({text = \"herb\", field = \"note\"}, fn) searches the map like MMapper's Find Rooms and calls fn(results, total, here). field is \"name\" (the default), \"desc\", \"contents\", \"note\", \"area\", \"exits\" (door names), \"flags\" (mob, load, exit and door flags, as MMapper names them, such as aggmob, herb, door, climb, or in words, aggressive mob) or \"all\". The text matches anywhere in the field, whatever the case; case = true makes case count; regex = true takes it as a regular expression (JavaScript syntax). results is a list of at most max (default 200, at most 500) rooms {id, name, area, note, steps, dirs}, nearest first by the shortest path from your room; dirs is the way as text, such as 3e n 2u (empty in your own room). Rooms without a path come last, nearest first, with steps and dirs nil; so do all when your room is unknown (here is then nil). total counts every match. A bad regular expression gives nil and \"bad regex: …\" at once.","mapPath(id, fn) calls fn(dirs, steps) with the way from your room to room id, or fn(nil) when there is none. mapRoom(id, fn) calls fn(room): {id, name, area, desc, contents, note, terrain, x, y, z, exits, flags}; exits is a list of {dir, to, door, flags} (door is the door's name, \"\" for a door without one, nil for no door), flags the room's mob and load flags in words. Paths cost as in MMapper: by terrain, with doors, climbs, random, damage and fall exits, rooms you cannot ride in and death traps costing more.","With the Map pane off (or no map loaded) mapMark, mapFind, mapSearch, mapPath and mapRoom return nil, \"map off\" at once. Marks are live only: runs and replays do not show them."],"examples":[{"note":"Mark a room by name for 15 seconds:","lang":"lua","code":"tempAlias(\"^where (.+)$\", function()\n  local h, why = mapMark({name = matches[2]}, {duration = 15, focus = true}, function(count, total)\n    echo(count == 0 and \"Not on the map.\" or (count .. \" of \" .. total .. \" rooms marked.\"))\n  end)\n  if not h then echo(\"No mark: \" .. why) end\nend)"},{"note":"Find the nearest herbs from the map's notes and mark them until the next search:","lang":"lua","code":"local mark\ntempAlias(\"^herbs$\", function()\n  local ok, why = mapSearch({text = \"herb\", field = \"note\", max = 5}, function(results, total)\n    if mark then mapUnmark(mark) end\n    local ids = {}\n    for i, r in ipairs(results) do\n      echo(r.name .. \": \" .. (r.dirs or \"no path\") .. \"\\n\")\n      ids[i] = r.id\n    end\n    if #ids > 0 then mark = mapMark(ids, {duration = 0, focus = \"move\"}) end\n  end)\n  if not ok then echo(\"No search: \" .. why) end\nend)"}]},{"group":"guide","heading":"Settings and store","syntax":["settings.<name>","setSetting(name, value)","scriptName","store.get(key) → value","store.set(key, value)"],"text":["Settings are what the player may change without editing the code. Declare each one in the header with @setting; the script reads it as settings.<name>. An unset setting has its default. The settings table is read-only.","The player changes a setting on the Scripts page, or with #script set {name} {setting} {value}. The value is converted to the setting's type (a boolean takes true, false, on, off, yes, no, 1 or 0) and saved; a number outside its range or a choice that is not one of the options is refused. RESET ALL on the Scripts page puts every setting back to its default. The running script sees the new value at once, without a reload, so read settings.<name> when you need it rather than copying it into a local once.","setSetting(name, value) lets the script save one of its own settings, as #script set does. The name must be declared with @setting. The save takes a moment: settings.<name> has the new value afterwards, not on the next line.","scriptName is the script's own name. A Duplicate has another name than the original, so use scriptName when you tell the player a #script command.","store is a small database for the script's own data, kept between sessions:","- store.set(key, value) saves a string, number, boolean or a table of them under key. nil removes the key. Functions are not kept.","- store.get(key) returns a copy of the value, or nil. Changing the table you got does not change the store until you store.set it again.","- Values are in memory at once and written to the browser's storage about a second later, and when the page is hidden.","- Each script has its own store. It survives reloads and new releases. Deleting a script deletes its store; a Duplicate starts with an empty one. In a browser without storage (some private windows) it lasts only for the page."],"examples":[{"note":"A setting the player can change, and one the script saves:","lang":"lua","code":"-- @name     autoeat\n-- @api      1\n-- @setting  food    string  bread \"What to eat\"\n-- @setting  enabled boolean true  \"Eat by itself\"\n\ntempTrigger(\"You are hungry.\", function()\n  if settings.enabled then send(\"eat \" .. settings.food) end\nend)\n\ntempAlias(\"^ae$\", function()\n  setSetting(\"enabled\", not settings.enabled)\n  echo(\"Change the food with #script set \" .. scriptName .. \" food <food>\")\nend)"},{"note":"Typed on the input line:","lang":"tt","code":"#script set autoeat food apple"},{"note":"Data kept between sessions:","lang":"lua","code":"local seen = store.get(\"seen\") or {}\n\ntempRegexTrigger(\"^(\\\\w+) has arrived\", function()\n  seen[matches[2]] = (seen[matches[2]] or 0) + 1\n  store.set(\"seen\", seen)\nend)"}]},{"group":"guide","heading":"Profile bridge","syntax":["getVariable(name) → value","setVariable(name, value)","export(name, fn)","#lua {script} {function} {args}"],"text":["A script and the profile can work together.","- getVariable(name) reads a profile variable ($name without the $). The value is always a string; use tonumber for a number. It is nil when the variable is not set.","- setVariable(name, value) sets one, as #variable in an action does. The value may be a string, number or boolean and is stored as text. The profile text is updated only for a variable the profile declares with #variable; any other lasts for the session.","- export(name, fn) makes fn callable from the profile with #lua {script} {name} {args}. The arguments come as one string, joined by spaces; without arguments fn gets nothing (nil). Exporting a name again replaces it.","#lua works on the input line and in aliases, actions and macros, but is not run while a profile loads. When the script is not running, or has not exported the name, #lua says so in the game window."],"examples":[{"note":"A script that keeps the target:","lang":"lua","code":"-- @name     target\n-- @api      1\n\nexport(\"set\", function(name)\n  setVariable(\"target\", name or \"\")\n  cecho(\"<orange>Target:<reset> \" .. (name or \"none\"))\nend)\n\ntempKey(\"F5\", function()\n  local t = getVariable(\"target\")\n  if t and t ~= \"\" then send(\"kill \" .. t) end\nend)"},{"note":"The profile calls it:","lang":"tt","code":"#alias {t %1} {#lua {target} {set} {%1}}"}]},{"group":"guide","heading":"In-game commands","syntax":["#script list","#script help {name}","#script set {name} {setting} {value}","#script enable {name}","#script disable {name}","#script reload {name}","#lua {script} {function} {args}"],"text":["These commands work on the input line and in the profile's aliases, actions and macros. They are not run while a profile loads.","- #script list shows every script, whether it is on and its summary.","- #script help {name} shows a script's help in the game window, typeset as on the Scripts page, with each setting, its value and what it takes.","- #script set {name} {setting} {value} changes a setting and saves it, as the Scripts page does. The rest of the line is the value. A number must be inside its range and a choice one of its options. The script sees the new value at once.","- #script enable {name} and #script disable {name} turn a script on and off, as its toggle does. On and off are the same for every profile.","- #script reload {name} stops a script that is on and runs it again from its saved code. A script that failed to load is tried again. A script that is off needs #script enable instead.","- #lua {script} {function} {args} calls a function the script exported (see Profile bridge).","A script that errors too often is turned off; #script enable turns it on again.","Other forms, such as a tt++ #script {variable} {shell command} pasted from another client, do nothing. #help script and #help lua show these commands in the game window."]},{"group":"guide","heading":"Sandbox and limits","text":["Scripts are shared as files, so a script runs in a sandbox. It reaches the outside only through the API in this manual: no files, network, web page, passwords, profile text or other scripts' data.","The Lua you have: the base functions (assert, error, ipairs, pairs, next, pcall, xpcall, select, tonumber, tostring, type, getmetatable, setmetatable, rawequal, rawget, rawlen, rawset) and the string, table, math, utf8 and coroutine libraries.","What is not there:","- io, os, package, require, debug, load, loadstring, dofile, loadfile, collectgarbage, warn, unpack (use table.unpack) and string.dump. There is no os.time or os.clock: use timers for time.","- The library tables are read-only: you cannot add string.trim, but you can write local function trim(s). getmetatable(\"\") gives false.","- setmetatable refuses a metatable with __gc, and <close> variables are refused when the script loads.","- xpcall works, but its message handler runs after the error has unwound, not at the point of the error.","Each script has its own global variables. A global you set is seen by your script only.","Limits, so one script cannot freeze the game:","- Each call into a script (loading it, a trigger, alias, key, timer or event) may run 1 000 000 Lua instructions. Past that the call is stopped and the script is turned off.","- All scripts together may use 32 MB of memory. A script that runs out is turned off.","- A call that takes longer than one second turns the script off.","- 5 errors within 10 seconds turn the script off.","- string.find, match, gmatch and gsub refuse a pattern with two or more .* .+ or .- on a long string when it could take very long, with the error pattern too complex. Patterns such as (.-) tells you '(.-)' on a game line are fine. Use anchors and narrower classes such as %S+ or [^,]+.","- If the page is closed or reloaded while a script is running (it hung the page), that script is turned off at the next start, with a UI message.","A script that was turned off stays off until you turn it on again. Each time, a UI message says why."]},{"group":"guide","heading":"Errors and debugging","text":["Errors read <script>:<line>: <message>, for example autoeat:12: attempt to index a nil value (field 'Vitals').","- Syntax errors and header problems are marked in the editor while you type, before you save.","- A script that fails to load (a syntax error, a missing @api 1, an error in its top-level code) stays on but does not run. The Scripts page shows ! and the message in red under its row, the editor's status row shows it, and a UI message says it. It is tried again when you save a new version or type #script reload {name}.","- An error while the script runs (in a trigger, alias, timer …) goes to the UI messages and is the script's last error on the Scripts page. The editor marks the line. The script keeps running, unless it has 5 errors within 10 seconds.","Ways to find a bug:","- print(...) and echo show values in the game window; uiMessage keeps them in the UI messages pane, away from the game text.","- pcall(fn, …) runs a function and catches its error: local ok, err = pcall(fn).","- Save to apply a change; a script that is on is reloaded at once. #script reload {name} runs it again without a change.","- A nil error on gmcp usually means the message has not arrived yet: test gmcp.Char before gmcp.Char.Vitals."],"examples":[{"note":"Show what a trigger sees:","lang":"lua","code":"tempRegexTrigger(\"^(\\\\w+) tells you\", function()\n  print(\"line:\", line)\n  print(\"who:\", matches[2])\nend)"},{"note":"Catch an error and report it yourself:","lang":"lua","code":"local ok, err = pcall(function()\n  local v = gmcp.Char.Vitals\n  echo(\"HP \" .. v.hp)\nend)\nif not ok then uiMessage(\"debug\", tostring(err)) end"}]},{"group":"guide","heading":"Examples","text":["Complete small scripts. Make a new script, paste one over the template, save and turn it on. The bundled scripts are larger examples: open one and press DUPLICATE to change your own copy.","- coinlooter: triggers, an alias and a setting it saves itself.","- mercenaries: a status pane with gauges, links and tooltips, redrawn from triggers and GMCP.","- keymanager: temporary panes in a group, a pick list with a text field, copy2cecho, the store and map marks.","- readability: replaceLine and copy2cecho with adaptive colours, and lineTags to leave room descriptions and what players say alone.","- almanac: the game time API (gameTime, gameTimeFind, localTime, sysGameTimeEvent) behind a tabbed pane drawn as a grid of cells, with half-block pictures, pane:onWheel, text fields for a form, events as data and a small parser for conditions written as text.","- mapsearch: mapSearch and lasting mapMark with focus \"move\" behind a dialog pane with a text field, radio buttons and checkboxes, a list of clickable rows with tooltips, and redraws that keep the field."],"examples":[{"note":"Eat when hungry, drink when thirsty:","lang":"lua","code":"-- @name     autoeat\n-- @summary  Eats and drinks when you need it\n-- @api      1\n-- @setting  food  string bread \"What to eat\"\n-- @setting  drink string skin  \"What to drink from\"\n\ntempTrigger(\"You are hungry.\", function()\n  send(\"eat \" .. settings.food)\nend)\n\ntempTrigger(\"You are thirsty.\", function()\n  send(\"drink \" .. settings.drink)\nend)"},{"note":"Warn when hit points run low (GMCP):","lang":"lua","code":"-- @name     hpwarn\n-- @summary  Warns when your hit points run low\n-- @api      1\n-- @setting  percent number 30 \"Warn below this percentage\"\n\nlocal warned = false\n\nregisterAnonymousEventHandler(\"gmcp.Char.Vitals\", function()\n  local v = gmcp.Char.Vitals\n  if not v.hp or not v.maxhp or v.maxhp == 0 then return end\n  local low = v.hp * 100 / v.maxhp < settings.percent\n  if low and not warned then\n    cecho(\"<white:red> LOW HP <reset> \" .. v.hp .. \"/\" .. v.maxhp)\n    uiMessage(\"hp\", \"Hit points low: \" .. v.hp)\n  end\n  warned = low\nend)"},{"note":"Count kills, kept between sessions:","lang":"lua","code":"-- @name     kills\n-- @summary  Counts your kills\n-- @api      1\n-- @alias    kills        Show the count\n-- @alias    kills reset  Start again from 0\n\nlocal kills = store.get(\"kills\") or 0\n\ntempTrigger(\"You receive your share of experience.\", function()\n  kills = kills + 1\n  store.set(\"kills\", kills)\nend)\n\ntempAlias(\"^kills( reset)?$\", function()\n  if matches[2] == \" reset\" then\n    kills = 0\n    store.set(\"kills\", 0)\n  end\n  cecho(\"<cyan>Kills:<reset> \" .. kills)\nend)"},{"note":"A repeating timer with an on/off alias:","lang":"lua","code":"-- @name     xprate\n-- @summary  Shows the experience you gain each minute\n-- @api      1\n-- @alias    xpr  Turn the report on or off\n\nlocal timer = nil\nlocal last = nil\n\nlocal function report()\n  local v = gmcp.Char and gmcp.Char.Vitals\n  local xp = v and v.xp\n  if xp and last then\n    cecho(\"<cyan>XP this minute:<reset> \" .. (xp - last))\n  end\n  last = xp\nend\n\ntempAlias(\"^xpr$\", function()\n  if timer then\n    killTimer(timer)\n    timer = nil\n    echo(\"XP report off.\")\n  else\n    last = nil\n    report()\n    timer = tempTimer(60, report, true)\n    echo(\"XP report on.\")\n  end\nend)"},{"note":"Colour tells, and rewrite a line:","lang":"lua","code":"-- @name     tells\n-- @summary  Makes tells stand out\n-- @api      1\n\ntempRegexTrigger([[^(\\w+) tells you ']], function()\n  highlight(\"light yellow\")\n  highlight(\"bold white\", matches[2])\nend)\n\ntempTrigger(\"You feel less protected.\", function()\n  replaceLine(\"<white:red> ARMOUR IS GONE <reset>\")\nend)"},{"note":"A function the profile calls with #lua, and a key:","lang":"lua","code":"-- @name     healer\n-- @summary  Heals a group member by name\n-- @api      1\n-- @key      F6  Heal the last one\n-- @help     From the profile: #alias {h %1} {#lua {healer} {heal} {%1}}\n\nlocal last = nil\n\nlocal function heal(who)\n  last = who or last or \"me\"\n  send(\"cast 'cure light' \" .. last)\nend\n\nexport(\"heal\", heal)\n\ntempKey(\"F6\", function()\n  heal(nil)\nend)"}]},{"group":"reference","heading":"cecho","syntax":["cecho(text)"],"text":["Writes coloured text: <red>, <white:blue>, <#ff8000>, <~gold> (adaptive), <b>bold</b>, <reset> and tt++ <F88ff00> / <118> codes.","Anything in angle brackets that is not a colour tag is shown as text. Triggers do not see the output.","Parameters:","- text (string): Text with colour tags in angle brackets; see the Output section for the list."],"examples":[{"code":"cecho(\"<green>Ready.<reset> Type <yellow>cl<reset> to loot.\")","lang":"lua"}]},{"group":"reference","heading":"command","syntax":["command"],"text":["In an alias: the typed command."],"examples":[{"code":"tempAlias(\"^say \", function()\n  echo(\"You said: \" .. command)\n  return false -- send it too\nend)","lang":"lua"}]},{"group":"reference","heading":"copy2cecho","syntax":["copy2cecho() → string"],"text":["In a trigger: the current line as the game sent it, with its colours as cecho tags, so it can be shown elsewhere (a pane) in the same colours.","Like Mudlet's copy2decho, with cecho tags. The line is the original, before substitutes and replaceLine.","Returns: The line with <ansi_N>, <#rrggbb>, <fg:bg>, <b>, <i>, <u> and <reset> tags (an adaptive colour as <~#rrggbb>), or nil outside a trigger."],"examples":[{"code":"tempRegexTrigger(\"^\\\\[home\\\\] \", function()\n  tv:cecho(copy2cecho() .. \"\\n\")\n  deleteLine()\nend)","lang":"lua"}]},{"group":"reference","heading":"createPane","syntax":["createPane{id, title, short, dock, lane, rows, cols, border, cross, tooltip, outline, anchor, temporary, at, group, grid} → pane"],"text":["Makes the script's own pane and returns it. It docks, floats, toggles and is coloured like the built-in panes, and WebCockpit remembers where the player puts it.","dock, lane, border, rows and cols only place a new pane. After that the pane stays where the player docked, floated or resized it, also after a reload, a restart or Reset layout of the other panes; the Panes box lists it with its title and script, to switch it off, and its pane buttons colour it or drop its border.","The pane shows while the script runs. Turning the script off or saving it takes the pane away (it comes back where it was when the script creates it again). Calling createPane with an id the script already has returns the same pane.","Rows and columns count from 1. Text wider than the pane is cut. More lines than fit scroll (wheel, touchpad, touch), with one row telling how many are hidden: on top for anchor = \"bottom\", at the bottom for \"top\"; a click on it goes back. A pane keeps at most 500 lines.","A temporary pane ignores dock and never docks: it comes and goes, and docking it would move the other panes each time. The player can move and resize it; that place is kept on this device for the next time a pane of the same script and id opens (Reset layout in the Panes box forgets it). It is in runs like any pane. Its id is apart from the ordinary panes': a temporary and an ordinary pane may share an id. createPane with an id the script already has returns that pane, temporary or not.","Parameters:","- id (string): The pane's id within the script: 1 to 32 letters, digits, _ or -.","- title (string?): The frame title (default: the id). pane:setTitle changes it.","- short (string?): A short name of 1 to 8 characters for compact lists of panes (getPanes). Default: the first four letters and digits of the title, in capitals.","- dock (string?): Where it goes the first time: \"right\" (default), \"left\", \"top\", \"bottom\" or \"float\".","- lane (string?): \"own\": the first time, the pane gets a lane of its own at the screen edge of its dock (a row of the top or bottom dock, a column at the side), as high (or wide) as rows (cols) plus the frame. Not for a float or a temporary pane.","- rows (number?): Wanted height in rows (default 8): in a side dock and a float.","- cols (number?): Wanted width in columns (default 30): in the top or bottom dock and a float.","- border (boolean?): false: the first time, the pane has no frame (the player can turn it on with the pane's Border button). A borderless pane in the top or bottom dock can be a single row; drag it by its top row, past a few pixels (a click there is the pane's own). On hover the close cross shows over the last cells of its top row (one in from the right edge), framed or not.","- cross (boolean?): false: no close cross on hover, for a pane whose top row ends in buttons, such as a one-row bar. The player turns it off in the Panes box, your script with pane:hide(). Not for a temporary pane. Default true: the cross shows over the last cells of the top row while the pane is hovered, over whatever is there, so keep a link out of them (it cannot be clicked while the cross covers it).","- tooltip (boolean?): Accepted and ignored: it once showed the title in a small tag on hover (gone). Old scripts that pass it still run.","- outline (boolean?): false: while the pane has no frame, hovering it draws no outline around it, for a bar that should stay flat. Default true: a thin outline shows where the borderless pane ends.","- anchor (string?): Where the view sticks when the lines do not fit: \"bottom\" (default, a console: it follows new lines while scrolled to the end) or \"top\" (a list: it stays at the first line).","- temporary (boolean?): true for a short-lived pane, such as a choice: it floats over the game text at rows × cols, above the other panes, is never listed in Options, and its close cross closes it (pane:close).","- at (string?): A temporary pane's place until the player moves it: \"center\" (default), \"top\", \"bottom\" (just above the input line), \"left\", \"right\", or a corner: \"top-left\", \"top-right\", \"bottom-left\", \"bottom-right\". Corners let several panes open side by side.","- group (string?): Temporary panes only: panes of the script with the same group are tiled together from at's corner (top-left by default), in the order they opened, with no gaps; a closed one's place is taken by the ones after it. Dragging one moves the whole group, resizing one sets the size of all; both are kept on this device (Reset layout forgets them).","- grid (table?): A group's grid: {cols = 2} (default 2, at most 8). The panes go row by row; fewer columns when they do not fit the game text.","Returns: The pane, an object whose methods are called with a colon: pane:echo(\"text\")."],"examples":[{"code":"local pane = createPane{id = \"hp\", title = \"Health\", dock = \"right\", rows = 3}\npane:gauge(1, {value = 80, max = 120, color = \"green\", label = \"HP 80/120\"})","lang":"lua"}]},{"group":"reference","heading":"deleteLine","syntax":["deleteLine()"],"text":["In a trigger: hides the current line (a gag).","Outside a trigger (in a timer, key or alias) it does nothing. Other triggers still see the line."],"examples":[{"code":"tempTrigger(\"You can't find any coins\", function()\n  deleteLine()\nend)","lang":"lua"}]},{"group":"reference","heading":"echo","syntax":["echo(text)"],"text":["Writes plain text to the game output. Triggers do not see it.","Inside a trigger the text shows after the game line. Echoed lines are not recorded in runs.","Parameters:","- text (string): The text; each line break starts a new line."],"examples":[{"code":"echo(\"Looting is off.\")","lang":"lua"}]},{"group":"reference","heading":"expandAlias","syntax":["expandAlias(cmd)"],"text":["Runs cmd as if typed: profile and script aliases, ; and # commands.","Parameters:","- cmd (string): The text to run, like a line typed on the input line."],"examples":[{"code":"expandAlias(\"stand;flee\")","lang":"lua"}]},{"group":"reference","heading":"export","syntax":["export(name, fn)"],"text":["Makes fn callable from the profile: #lua {script} {name} {args}.","Parameters:","- name (string): The name #lua uses; no spaces. Exporting the same name again replaces it.","- fn (function): Called with the rest of the #lua line as one string, or with no argument when there is none."],"examples":[{"code":"export(\"heal\", function(who)\n  send(\"cast 'cure light' \" .. (who or \"me\"))\nend)\n-- In the profile: #lua {healer} {heal} {Rasta}","lang":"lua"}]},{"group":"reference","heading":"field:focus","syntax":["field:focus()"],"text":["Gives the keyboard to the text field (from pane:setInput), with the cursor after its text.","A field that is not on screen yet (a new pane) takes the keyboard once it is drawn.","Parameters:","- field (field): A field from pane:setInput."],"examples":[{"code":"name:focus()","lang":"lua"}]},{"group":"reference","heading":"field:remove","syntax":["field:remove()"],"text":["Takes the field away; the keyboard goes back to the input line if the field had it. Its methods then do nothing.","Parameters:","- field (field): A field from pane:setInput."],"examples":[{"code":"name:remove()","lang":"lua"}]},{"group":"reference","heading":"field:select","syntax":["field:select()"],"text":["Gives the keyboard to the text field with all its text selected, so typing replaces it.","Parameters:","- field (field): A field from pane:setInput."],"examples":[{"code":"name:select()","lang":"lua"}]},{"group":"reference","heading":"field:setValue","syntax":["field:setValue(text)"],"text":["Replaces the field's text (one line, cut to its maxLength). onChange is not called.","Parameters:","- field (field): A field from pane:setInput.","- text (string): The new text."],"examples":[{"code":"name:setValue(\"\")","lang":"lua"}]},{"group":"reference","heading":"field:value","syntax":["field:value() → string"],"text":["The field's text now; nil once the field is gone.","Parameters:","- field (field): A field from pane:setInput.","Returns: The text, or nil."],"examples":[{"code":"local text = name:value()","lang":"lua"}]},{"group":"reference","heading":"gameTime","syntax":["gameTime([epoch]) → table"],"text":["The game date, time, season, period of the day and moon now, or at any real time (seconds since 1970, past or future). nil while the clock does not know the day.","The clock syncs from what MUME tells (time, the sun, a room clock, MSSP). At day precision the hour is a guess; at hour precision the minute is.","Moon phases: new, waxing crescent, first quarter, waxing gibbous, full, waning gibbous, third quarter, waning crescent.","Parameters:","- epoch (number?): A real time, as getEpoch() gives; default now.","Returns: A table: year, month (1–12), monthName, sindarin, day (1–30), hour, minute, weekday, season (winter, spring, summer, autumn), period (dawn, day, dusk, night; the sun is up from the dawn hour through the dusk hour: only night is dark), dawn and dusk (the month's hours), precision (day, hour, minute), epoch, and moon = {phase, level (0 new … 12 full), waxing, visible, bright, position (east, southeast, south, southwest, west, below)}. nil while the clock is unset."],"examples":[{"code":"local g = gameTime()\nif g then\n  echo(g.hour .. \":\" .. string.format(\"%02d\", g.minute) .. \" \" .. g.monthName .. \", \" .. g.season .. \", \" .. g.moon.phase .. \" moon\")\nend","lang":"lua"}]},{"group":"reference","heading":"gameTimeFind","syntax":["gameTimeFind(cond[, from[, horizon]]) → start, end"],"text":["The next window of real time (seconds since 1970) in which every key of cond holds, or nil when none starts within the horizon or the clock is unset.","An unknown key or value is an error that names the allowed ones.","One game minute is one real second, a game hour a real minute, a game year six real days.","Parameters:","- cond (table): Any of: season or notSeason (\"winter\" or a list), month (1–12, a name or a list), hours = {from = 22, to = 2} (to not included), period (\"dawn\", \"day\", \"dusk\", \"night\" or a list), moon (a phase name or a list), moonVisible (true or false), at (\"dawn\", \"dusk\", \"midnight\", \"moonrise\", \"moonset\", \"seasonStart\").","- from (number?): Where to start looking, as getEpoch(); default now.","- horizon (number?): How far to look, in real seconds; default one game year (6 real days), at most 30 days.","Returns: start and end in seconds since 1970. When cond already holds at from, start is from. With at, the window is that moment (start equals end): the first such moment at which the other keys hold. nil when there is none."],"examples":[{"code":"local s = gameTimeFind({at = \"moonrise\", moon = {\"waxing gibbous\", \"full\"}})\nif s then\n  echo(\"Dead Knight moonrise in \" .. math.floor((s - getEpoch()) / 60) .. \" min\")\nend","lang":"lua"}]},{"group":"reference","heading":"getEpoch","syntax":["getEpoch() → seconds"],"text":["The time now, in seconds since 1970 (with milliseconds as the fraction), as Mudlet's getEpoch. Use it for times that must outlast a reload, kept with store.set.","Returns: Seconds since 1 January 1970 UTC, a number with a fraction."],"examples":[{"code":"local ends = getEpoch() + 25 * 60\nstore.set(\"ends\", ends)\nlocal left = math.floor(ends - getEpoch())","lang":"lua"}]},{"group":"reference","heading":"getPanes","syntax":["getPanes() → list"],"text":["Every pane in the Panes box's order: the built-in panes, then the panes of the scripts that run. Temporary panes are not listed.","The built-in panes' ids are character, timers, group, comm, ui, map and statistics, with the short names CHAR, TIME, GRP, COMM, UI, MAP and STAT; a script pane's id is script/id. The event sysPanesChanged tells when the list changes.","Returns: A list of tables {id, title, short, on, shown, dock, script, own}: on is the player's on/off, shown is true when it is on the screen now (on and room for it), dock is \"left\", \"right\", \"top\", \"bottom\" or \"float\", script names the script that owns it (nil for a built-in pane) and own is true for this script's own panes."],"examples":[{"code":"for _, p in ipairs(getPanes()) do\n  if not p.own then echo(p.short .. (p.on and \" on\" or \" off\") .. \"\\n\") end\nend","lang":"lua"}]},{"group":"reference","heading":"getVariable","syntax":["getVariable(name) → value"],"text":["Reads a tt++ variable of the profile ($name). nil when unset.","Parameters:","- name (string): The variable name without $.","Returns: The value as a string (use tonumber for numbers), or nil when the variable is not set."],"examples":[{"code":"local target = getVariable(\"target\")\nif target then send(\"kill \" .. target) end","lang":"lua"}]},{"group":"reference","heading":"gmcp","syntax":["gmcp.<Package>.<Message>"],"text":["The last GMCP data from MUME, as in Mudlet: gmcp.Char.Vitals.hp, gmcp.Room.Info.name … (read-only).","Char.Vitals and Char.StatusVars merge key by key into their last value, since MUME sends only what changed; a JSON null removes a key. Every other message replaces its last value (Group.Update is one member: read the group from state.group). A JSON null field is left out (nil); false is kept. Group.Remove and Room.Chars.Remove are bare numbers, an id. GMCP from before the first script loaded is there; the table is cleared when a new connection starts. Names with a dash need brackets: gmcp.Char.Vitals[\"hp-string\"].","A package that has not arrived is nil: test gmcp.Char before you read gmcp.Char.Vitals outside a GMCP handler."],"examples":[{"code":"local v = gmcp.Char and gmcp.Char.Vitals\nif v and v.hp then\n  echo(\"HP \" .. v.hp .. \"/\" .. (v.maxhp or \"?\"))\nend","lang":"lua"}]},{"group":"reference","heading":"highlight","syntax":["highlight(color[, text])"],"text":["In a trigger: colours the whole line, or each occurrence of text. color is a profile colour such as \"light red\" or \"bold yellow\", or a Mudlet name such as \"orange\".","An unknown colour is an error. Highlights from scripts apply after the profile's. Outside a trigger it does nothing.","Parameters:","- color (string): A profile colour (\"red\", \"light red\", \"bold yellow\", \"<F88ff00>\"), cecho tags (\"<b><orange>\"), a Mudlet name (\"orange\", \"white:red\"), \"r,g,b\" or \"#rrggbb\". A ~ before a name, \"#rrggbb\" or \"r,g,b\" makes it adaptive (\"~gold\"): it keeps its hue and is made lighter or darker to read on the current background.","- text (string?): Colour only this text, each time it occurs in the line. Without it the whole line."],"examples":[{"code":"tempRegexTrigger(\"^(\\\\w+) tells you\", function()\n  highlight(\"light yellow\")\n  highlight(\"bold white\", matches[2])\nend)","lang":"lua"}]},{"group":"reference","heading":"isPrompt","syntax":["isPrompt() → boolean"],"text":["In a trigger: true when the line is a prompt (MUME ended it with GA/EOR, or it is a <prompt> element in XML mode).","Returns: true or false; false outside a trigger."],"examples":[{"code":"tempRegexTrigger(\"^$\", function()\n  if isPrompt() then return end\nend)","lang":"lua"}]},{"group":"reference","heading":"killAlias","syntax":["killAlias(id)"],"text":["Removes an alias made with tempAlias.","Parameters:","- id (number): The id tempAlias returned.","Returns: true when it was removed, false when the id is not one of this script's (or it is already gone)."],"examples":[{"code":"local id = tempAlias(\"^hi$\", function()\n  send(\"say Hello!\")\nend)\ntempAlias(\"^nohi$\", function()\n  killAlias(id)\nend)","lang":"lua"}]},{"group":"reference","heading":"killAnonymousEventHandler","syntax":["killAnonymousEventHandler(id)"],"text":["Removes an event handler.","Parameters:","- id (number): The id registerAnonymousEventHandler returned.","Returns: true when it was removed, false when the id is not one of this script's (or it is already gone)."],"examples":[{"code":"local h\nh = registerAnonymousEventHandler(\"gmcp.Char.Name\", function()\n  echo(\"Welcome, \" .. gmcp.Char.Name.name)\n  killAnonymousEventHandler(h)\nend)","lang":"lua"}]},{"group":"reference","heading":"killKey","syntax":["killKey(id)"],"text":["Removes a key binding made with tempKey.","Parameters:","- id (number): The id tempKey returned.","Returns: true when it was removed, false when the id is not one of this script's (or it is already gone)."],"examples":[{"code":"local key = tempKey(\"Numpad5\", function()\n  send(\"look\")\nend)\nkillKey(key)","lang":"lua"}]},{"group":"reference","heading":"killTimer","syntax":["killTimer(id)"],"text":["Stops a timer made with tempTimer.","Parameters:","- id (number): The id tempTimer returned.","Returns: true when it was removed, false when the id is not one of this script's (or it is already gone). A one-shot timer that has fired is gone."],"examples":[{"code":"local t = tempTimer(60, function()\n  echo(\"Another minute.\")\nend, true)\ntempAlias(\"^stopclock$\", function()\n  killTimer(t)\nend)","lang":"lua"}]},{"group":"reference","heading":"killTrigger","syntax":["killTrigger(id)"],"text":["Removes a trigger made with tempTrigger or tempRegexTrigger.","Parameters:","- id (number): The id tempTrigger or tempRegexTrigger returned.","Returns: true when it was removed, false when the id is not one of this script's (or it is already gone)."],"examples":[{"code":"local id\nid = tempTrigger(\"You are hungry.\", function()\n  send(\"eat bread\")\n  killTrigger(id) -- only the first time\nend)","lang":"lua"}]},{"group":"reference","heading":"line","syntax":["line"],"text":["In a trigger: the game line. In an alias: the typed command."],"examples":[{"code":"tempTrigger(\"R.I.P.\", function()\n  uiMessage(\"death\", line)\nend)","lang":"lua"}]},{"group":"reference","heading":"lineTags","syntax":["lineTags() → table"],"text":["In a trigger: the MUME XML elements the line is in, such as room, description, exits, say or tell, each name once.","WebCockpit plays MUME in XML mode, which marks room names, descriptions, exits and what players say, tell and narrate. A trigger that should only act on room contents or movement can skip lines in a description or a say.","Returns: A list of element names, outermost first; empty without XML or outside a trigger."],"examples":[{"code":"tempRegexTrigger(\" leaves north\\\\.$\", function()\n  for _, t in ipairs(lineTags()) do\n    if t == \"description\" or t == \"say\" then return end\n  end\n  highlight(\"~gold\")\nend)","lang":"lua"}]},{"group":"reference","heading":"localTime","syntax":["localTime([epoch]) → table"],"text":["The browser's local date and time of a real time, like Lua's os.date(\"*t\"), which the sandbox does not have.","Parameters:","- epoch (number?): Seconds since 1970; default now.","Returns: A table: year, month (1–12), day, hour, min, sec, wday (1 = Sunday), yday (1 = 1 January)."],"examples":[{"code":"local s = gameTimeFind({season = \"winter\"})\nif s then\n  local t = localTime(s)\n  echo(string.format(\"Winter starts %d-%02d-%02d %02d:%02d\", t.year, t.month, t.day, t.hour, t.min))\nend","lang":"lua"}]},{"group":"reference","heading":"mapFind","syntax":["mapFind(query, fn)"],"text":["Finds map rooms by a room's text, nearest to you first, and calls fn(ids, total).","Parameters:","- query (table): {name, lines, exits, max}, as mapMark's query.","- fn (function): Called once with the room ids (a list) and how many matched.","Returns: true, or nil and why (\"map off\")."],"examples":[{"code":"mapFind({name = \"Bree Market Square\"}, function(ids, total)\n  echo(total .. \" rooms; marking the nearest\")\n  if ids[1] then mapMark({ids[1]}, {duration = 10}) end\nend)","lang":"lua"}]},{"group":"reference","heading":"mapMark","syntax":["mapMark(target, opts, fn) → handle"],"text":["Marks rooms on the Map pane for a while: they blink in a colour, with arrows when they are off the view. target is a list of room ids or a query by a room's text, {name = …, lines = {…}, exits = \"Exits: …\", max = 20}.","Room ids are map room numbers, valid for the map that is loaded now. A script has at most 8 marks at a time; its marks go when it stops. Marks are not in runs or replays.","Parameters:","- target (table): Room ids (from mapFind or mapSearch; at most 200), or {name, lines, exits, max}: the room's name as shown, the lines after it (they narrow by the description), its Exits: line, and the most rooms (default 20, at most 50; nearest to you first).","- opts (table?): color (a colour name, #rrggbb or r,g,b; default magenta), duration (seconds, default 30, at most 600; 0: until mapUnmark or the script stops, blinking all the while), fade (seconds of fading at the end, default 10), blink and arrows (default true), label (a short text at the first room), linger (seconds the mark then stays, steady and a little dimmer, with its arrows and label; default 0, at most 600), focus (true: zoom out to show you and the rooms; the view comes back when the duration is over (before any linger), unless you moved it. \"move\": zoom out once; at your first move to another room the zoom comes back and the map follows you, the mark stays).","- fn (function?): Called once with (count, total, ids): how many rooms were marked, how many matched, and their ids. count is 0 when nothing matched.","Returns: A handle for mapUnmark, or nil and why (\"map off\" when the Map pane is off or has no map)."],"examples":[{"code":"local h, why = mapMark({name = \"The Prancing Pony\"}, {color = \"orange\", duration = 15, focus = true},\n  function(count, total) echo(count .. \" of \" .. total .. \" marked\") end)\nif not h then echo(\"No mark: \" .. why) end","lang":"lua"}]},{"group":"reference","heading":"mapPath","syntax":["mapPath(id, fn)"],"text":["The shortest way from your room to a room: fn(dirs, steps), or fn(nil) when there is none (or your room is unknown).","Parameters:","- id (number): A room id (from mapSearch or mapFind).","- fn (function): Called once with the direction text (3e n 2u) and the number of moves.","Returns: true, or nil and why (\"map off\")."],"examples":[{"code":"mapPath(id, function(dirs, steps) echo(dirs and (steps .. \" moves: \" .. dirs) or \"No way there.\") end)","lang":"lua"}]},{"group":"reference","heading":"mapRoom","syntax":["mapRoom(id, fn)"],"text":["A map room's details: fn(room), or fn(nil) for no such room.","Parameters:","- id (number): A room id (from mapSearch or mapFind).","- fn (function): Called once with {id, name, area, desc, contents, note, terrain, x, y, z, exits, flags}: exits a list of {dir, to, door, flags} (door: the door's name, \"\" without one, nil for no door), flags the mob and load flags in words.","Returns: true, or nil and why (\"map off\")."],"examples":[{"code":"mapRoom(id, function(r) if r then echo(r.name .. \" (\" .. r.terrain .. \")\") end end)","lang":"lua"}]},{"group":"reference","heading":"mapSearch","syntax":["mapSearch(query, fn)"],"text":["Searches the map like MMapper's Find Rooms and calls fn(results, total, here): the matching rooms, nearest first by the shortest path from your room, with the way there as text.","dirs is the way in runs, such as 3e n 2u, and \"\" in your own room. Paths cost as in MMapper (terrain, doors, climbs, random exits, rooms you cannot ride in, death traps). Rooms without a path come after the others, nearest first.","Parameters:","- query (table): {text, field, case, regex, max}: text to find anywhere in the field; field \"name\" (default), \"desc\", \"contents\", \"note\", \"area\", \"exits\" (door names), \"flags\" (aggmob, herb, door, climb … or in words, aggressive mob) or \"all\"; case = true makes case count; regex = true takes text as a regular expression; max, the most results (default 200, at most 500).","- fn (function): Called once with results (a list of {id, name, area, note, steps, dirs}; steps and dirs nil without a path or when your room is unknown), total (every match) and here (your room's id, or nil).","Returns: true, or nil and why (\"map off\", or \"bad regex: …\" for a regular expression that does not compile)."],"examples":[{"code":"mapSearch({text = \"herb\", field = \"note\", max = 5}, function(results, total)\n  for _, r in ipairs(results) do echo(r.name .. \": \" .. (r.dirs or \"no path\") .. \"\\n\") end\nend)","lang":"lua"}]},{"group":"reference","heading":"mapUnmark","syntax":["mapUnmark(handle) → boolean"],"text":["Takes a mark from mapMark away before its time is up.","Parameters:","- handle (number): What mapMark returned.","Returns: true when the mark was still there."],"examples":[{"code":"mapUnmark(h)","lang":"lua"}]},{"group":"reference","heading":"matches","syntax":["matches[1], matches[2] …"],"text":["In a trigger or alias: the whole match, then each group.","An unmatched group is an empty string. matches is set again before each trigger or alias call."],"examples":[{"code":"tempRegexTrigger(\"^(\\\\w+) has arrived\", function()\n  echo(\"Hello, \" .. matches[2])\nend)","lang":"lua"}]},{"group":"reference","heading":"pane:cecho","syntax":["pane:cecho(text)"],"text":["Appends coloured text to the pane, with the colour tags of cecho. A \\n starts a new line.","Parameters:","- pane (pane): A pane from createPane.","- text (string): Text with colour tags such as <red>, <~gold>, <b> or <reset>, and the pane's shades such as <@dim> (see the Panes chapter)."],"examples":[{"code":"pane:cecho(\"<green>ready<reset>\\n\")","lang":"lua"}]},{"group":"reference","heading":"pane:cechoLink","syntax":["pane:cechoLink(text, fn, hint, opts)"],"text":["Appends coloured text that calls fn when it is clicked, with hint as its tooltip.","The pointer turns into a hand over a link and the link lights up (pane:setHover chooses how). Links do nothing in the log player and the HTML replay, but keep their tooltips and their hover look.","Parameters:","- pane (pane): A pane from createPane.","- text (string): Text with colour tags and the pane's shades; it goes on the end of the last line, as pane:cecho (a \\n becomes a space).","- fn (function): Called with no arguments on a click.","- hint (string?): The tooltip shown while the pointer is over the link; \\n breaks it into lines.","- opts (table?): {hover = \"band\" | \"lighten\" | \"none\"}: how this link looks under the pointer (default: the pane's, see pane:setHover)."],"examples":[{"code":"pane:cechoLink(\"<u>[pay]</u>\", function()\n  send(\"pay mercenary\")\nend, \"Pay the mercenary\")","lang":"lua"}]},{"group":"reference","heading":"pane:clear","syntax":["pane:clear()"],"text":["Empties the pane: every line and link goes.","Parameters:","- pane (pane): A pane from createPane."],"examples":[{"code":"pane:clear()\npane:echo(\"Nothing to show.\")","lang":"lua"}]},{"group":"reference","heading":"pane:close","syntax":["pane:close()"],"text":["Takes the pane away. Its methods then do nothing; createPane with the same id makes a new pane.","For an ordinary pane, close is not hide: the pane leaves the screen until the script calls createPane again, and keeps its place, colour and on/off for then. A temporary pane is gone.","pane:onClose is not called: it is for the player's close cross.","Parameters:","- pane (pane): A pane from createPane."],"examples":[{"code":"local pick = createPane{id = \"pick\", title = \"Pick\", temporary = true, rows = 2, cols = 24}\ntempTimer(5, function() pick:close() end)","lang":"lua"}]},{"group":"reference","heading":"pane:dock","syntax":["pane:dock() → string"],"text":["Where the pane is now: \"left\", \"right\", \"top\", \"bottom\" or \"float\" (a temporary pane is always \"float\").","The player can move the pane at any time; redraw from sysPanesChanged or pane:onResize to follow it.","Parameters:","- pane (pane): A pane from createPane.","Returns: The dock name or \"float\"; nil after pane:close()."],"examples":[{"code":"local side = pane:dock() == \"left\" or pane:dock() == \"right\"","lang":"lua"}]},{"group":"reference","heading":"pane:echo","syntax":["pane:echo(text)"],"text":["Appends plain text to the pane. A \\n starts a new line.","Text goes on the end of the last line, as Mudlet's echo: pane:echo(\"a\") then pane:echo(\"b\\n\") gives one line ab, and the next echo starts a new line. Use pane:setLine to replace a row instead.","Parameters:","- pane (pane): A pane from createPane.","- text (string): The text, as is (angle brackets are text)."],"examples":[{"code":"pane:echo(\"Kills: \" .. kills .. \"\\n\")","lang":"lua"}]},{"group":"reference","heading":"pane:fillColor","syntax":["pane:fillColor(color) → string"],"text":["The colour pane:gauge fills a bar with for color: as is on a dark pane, washed to a pastel on a light one. For drawing bars of your own with background tags.","Like the theme it changes with the pane's colour: redraw in pane:onTheme.","Parameters:","- pane (pane): A pane from createPane.","- color (string): A colour name, as pane:gauge's color: \"red\", \"ansi_red\", \"<#ff8800>\" or \"#ff8800\".","Returns: The colour as #rrggbb; nil once the pane is closed."],"examples":[{"code":"pane:setText(1, 1, \"<:\" .. pane:fillColor(\"#0000aa\") .. \">    \")","lang":"lua"}]},{"group":"reference","heading":"pane:gauge","syntax":["pane:gauge(row, {value, max, color, label, col, width, align, track})"],"text":["Draws a bar on one row, like the bars of the Group pane: value of max filled, label over it. Without col and width it fills the whole row; with them it covers part of the row, so one row can hold several bars and text.","The fill is in whole cells. Its colour is washed to a pastel on a light pane, as the Group bars; pane:fillColor gives that colour. The unfilled part takes the pane's track shade, so the bar follows the pane colour.","Without col and width the bar is the whole row: like setLine, it replaces the row, its links and its fields.","With col or width the bar goes under the row's text: the row keeps its text, links and fields, and a bar it overlaps goes. A text cell shows its character over the bar, on the bar's colour unless the text has a background of its own; a space without a background lets the bar and its label show through. pane:setText keeps the bars; pane:setLine and pane:clear remove them.","Parameters:","- pane (pane): A pane from createPane.","- row (number): The row, from 1.","- gauge (table): value and max (numbers; max defaults to 100), color (a colour name such as \"red\", \"<#ff8800>\" or \"orange\"; default green; not the pane's shades), label (text over the bar), col (the first column, from 1), width (cells; default to the pane's right edge), align (\"center\", the default, \"left\" or \"right\": where the label sits) and track (the colour of the unfilled part, or false for none)."],"examples":[{"code":"pane:gauge(2, {value = 30, max = 60, color = \"orange\", label = \"30 min left\"})\n-- Three bars on one row, the name over them.\npane:gauge(3, {col = 1, width = 10, value = hp, max = maxhp, color = \"#005a18\"})\npane:gauge(3, {col = 11, width = 10, value = mana, max = maxmana, color = \"#0000aa\"})\npane:gauge(3, {col = 21, value = mv, max = maxmv, color = \"#5a3c1e\"})\npane:setText(3, 1, \"<@text>Gimli\")","lang":"lua"}]},{"group":"reference","heading":"pane:hide","syntax":["pane:hide()"],"text":["Switches the pane off, as its close cross does. The script keeps writing to it.","Parameters:","- pane (pane): A pane from createPane."],"examples":[{"code":"pane:hide()","lang":"lua"}]},{"group":"reference","heading":"pane:onClose","syntax":["pane:onClose(fn)"],"text":["Calls fn() when the player closes a temporary pane with its close cross. nil removes the handler.","Only for a temporary pane: an ordinary pane's close cross hides it (as pane:hide()). Not called by pane:close() or when the script stops.","Parameters:","- pane (pane): A pane from createPane.","- fn (function?): Called with no arguments, after the pane is gone; nil removes it."],"examples":[{"code":"pick:onClose(function()\n  echo(\"No choice made.\")\nend)","lang":"lua"}]},{"group":"reference","heading":"pane:onResize","syntax":["pane:onResize(fn)"],"text":["Calls fn(rows, cols) when the pane's size changes, also when it is first shown. nil removes the handler.","It is not called while the pane is hidden; pane:size() then gives 0, 0.","Parameters:","- pane (pane): A pane from createPane.","- fn (function?): Called with the new rows and cols; nil removes it."],"examples":[{"code":"pane:onResize(function(rows, cols)\n  pane:setLine(1, string.rep(\"=\", cols))\nend)","lang":"lua"}]},{"group":"reference","heading":"pane:onTheme","syntax":["pane:onTheme(fn)"],"text":["Calls fn(theme) when the pane's colours change: another pane colour, terminal colour or theme in the settings. theme is what pane:theme() returns. nil removes the handler.","It is called once per change, also while the pane is hidden, and not when you set it: draw once yourself first.","Parameters:","- pane (pane): A pane from createPane.","- fn (function?): Called with the new theme; nil removes it."],"examples":[{"code":"-- A bar of your own, in the gauge colour for this pane.\nlocal function draw()\n  pane:setText(1, 1, \"<:\" .. pane:fillColor(\"#0000aa\") .. \">      \")\nend\ndraw()\npane:onTheme(draw)","lang":"lua"}]},{"group":"reference","heading":"pane:onWheel","syntax":["pane:onWheel(fn)"],"text":["Calls fn(dx, dy) when the wheel or the touchpad scrolls over the pane, in whole cells: dx sideways (positive = right), dy up and down (positive = down). Return true to take the scroll; nil removes the handler.","Small touchpad moves add up: fn is called once they make a whole cell. Shift with the mouse wheel scrolls sideways. Ctrl with the wheel (zoom) never reaches fn.","When fn returns true the pane does not scroll its own lines and the browser does nothing with the scroll (no going back a page on a sideways swipe). Return false or nothing to leave it to them.","Parameters:","- pane (pane): A pane from createPane.","- fn (function?): Called with the steps in cells; true from it takes the scroll. nil removes it.","Returns: Nothing. fn returns true to take the scroll, anything else leaves it to the pane."],"examples":[{"code":"local first = 1\npane:onWheel(function(dx, dy)\n  first = math.max(1, first + dx)\n  pane:setLine(1, \"from column \" .. first)\n  return true\nend)","lang":"lua"}]},{"group":"reference","heading":"pane:setCheckbox","syntax":["pane:setCheckbox(row, col, opts) → toggle"],"text":["Draws a checkbox, [ ] Label, from column col of a row and returns it. A click or a tap on it flips it ([x]) and calls opts.onChange(checked).","It is text under a link: setLine, gauge and clear on its row remove it, as they remove links. Runs show it as text.","Parameters:","- pane (pane): A pane from createPane.","- row (number): The row, from 1.","- col (number): The first column, from 1.","- opts (table?): label (colour tags allowed), checked (default false), hint (a tooltip) and onChange(checked).","Returns: A toggle: toggle:checked(), toggle:set(on), toggle:remove()."],"examples":[{"code":"local cs = pane:setCheckbox(2, 1, {label = \"Case sensitive\", onChange = function(on) caseSensitive = on end})","lang":"lua"}]},{"group":"reference","heading":"pane:setGrip","syntax":["pane:setGrip(row, col, len)"],"text":["Makes len cells of a row, from column col, a grip that drags the pane: the pointer turns into a grabbing hand there, and a press starts a move at once, as on the title row. For a pane without a frame, or any row of one.","One grip per pane: a new one replaces the old. It belongs to the pane, not to the row's text, so pane:setLine and pane:clear keep it; pane:setGrip(nil) removes it.","A press on the grip is never a click: put no link there. Draw something that says \"drag here\", such as a dim <@mid>∷. In the log player and the HTML replay the grip does nothing.","Parameters:","- pane (pane): A pane from createPane.","- row (number?): The row, from 1; nil removes the grip.","- col (number): The first column, from 1.","- len (number?): How many cells, at least 1 (default 1)."],"examples":[{"code":"pane:setLine(1, \"<@mid>∷<reset> [a] [b]\")\npane:setGrip(1, 1, 2)","lang":"lua"}]},{"group":"reference","heading":"pane:setHover","syntax":["pane:setHover(style)"],"text":["Chooses how the pane's links look under the pointer: \"band\" (the default) draws them in the pane's glow band, \"lighten\" makes their own text and background a step lighter, \"none\" leaves them as they are (the pointer and the tooltip still show).","It applies to every link of the pane that has no hover of its own, also the ones already there. A link chooses its own with the opts of pane:setLink or pane:cechoLink: {hover = \"none\"}.","\"lighten\" suits buttons drawn with their own background, such as <@bg:@glow> and <@mid:@track>: the band would hide their colours. The log player and the HTML replay show the same look.","Parameters:","- pane (pane): A pane from createPane.","- style (string?): \"band\", \"lighten\" or \"none\"; nil is \"band\"."],"examples":[{"code":"pane:setHover(\"lighten\")\npane:setLine(1, \"<@bg:@glow> ON <reset> <@mid:@track> OFF \")\npane:setLink(1, 1, 4, function() send(\"on\") end, \"On\")\npane:setLink(1, 6, 5, function() send(\"off\") end, \"Off\", {hover = \"none\"})","lang":"lua"}]},{"group":"reference","heading":"pane:setInput","syntax":["pane:setInput(row, col, len, opts) → field"],"text":["Puts an editable one-line text field on len cells of a row, from column col, and returns it. Enter, Esc and typing call the functions in opts.","The field is drawn opaque on a band in the pane's own shades; the row's text under it is hidden while it is there. A click on it, or field:focus(), takes the keyboard from the input line; Enter, Esc, a click elsewhere or the pane closing give it back. While the field has the keyboard, nothing typed reaches the game, macros or keys bound with tempKey.","pane:setLine, pane:gauge and pane:clear on its row remove the field, as they remove links: write the row's text first, then add the field, and redraw other rows around it. The log player and the HTML replay show the field's text, not editable.","Parameters:","- pane (pane): A pane from createPane.","- row (number): The row, from 1.","- col (number): The first column, from 1.","- len (number): How many cells wide, at least 1. Longer text scrolls inside the field.","- opts (table?): value (the text to start with), placeholder (grey text while it is empty), maxLength (most characters), onSubmit(text) (Enter), onCancel() (Esc), onChange(text) (each edit), onBlur(text) (the field lost the keyboard to a click elsewhere, not by Enter or Esc) and onKey(key) (Up, Down, PgUp, PgDn, Tab, Shift+Tab: ArrowUp, ArrowDown, PageUp, PageDown, Tab, Shift+Tab, and the keys of keys). keys: a list of more key names for onKey, as tempKey names them (e.g. {\"Ctrl+F\"}): macros and script keys do not run while the field has the keyboard, so a script's own toggle key can come here instead.","Returns: A field: field:focus(), field:select(), field:value(), field:setValue(text), field:remove()."],"examples":[{"code":"pane:setLine(1, \"Name: \")\nlocal name = pane:setInput(1, 7, 12, {\n  value = \"home\",\n  onSubmit = function(text) echo(\"You typed \" .. text) end,\n  onCancel = function() pane:close() end,\n})\nname:select()","lang":"lua"}]},{"group":"reference","heading":"pane:setLine","syntax":["pane:setLine(row, text)"],"text":["Replaces one row with coloured text (the cecho tags). Rows past the end are added as empty lines.","The row's links go with its old text: add them again with pane:setLink after redrawing the row.","Parameters:","- pane (pane): A pane from createPane.","- row (number): The row, from 1 (at most 500).","- text (string): Text with colour tags, the pane's shades (<@dim>) too; a \\n becomes a space."],"examples":[{"code":"pane:setLine(1, \"<b>Mercenaries</b>\")\npane:setLine(2, \"Bob  <yellow>waiting\")","lang":"lua"}]},{"group":"reference","heading":"pane:setLink","syntax":["pane:setLink(row, col, len, fn, hint, opts)"],"text":["Makes len cells of a row, from column col, call fn when clicked, with hint as their tooltip. Any span, down to one cell.","The cells need no text. A link replaces the links it overlaps on that row; pane:setLine, pane:gauge and pane:clear remove the row's links.","Hovering is steady: when the pane is redrawn, a link at the same row, column and length keeps its band and its open tooltip, whose text updates when the hint changed. So a countdown's hint can be set again every second.","Parameters:","- pane (pane): A pane from createPane.","- row (number): The row, from 1.","- col (number): The first column, from 1.","- len (number): How many cells, at least 1.","- fn (function?): Called with no arguments on a click; nil for a tooltip only (not clickable, no hover look).","- hint (string?): The tooltip.","- opts (table?): {hover = \"band\" | \"lighten\" | \"none\"}: how this link looks under the pointer (default: the pane's, see pane:setHover)."],"examples":[{"code":"pane:setLine(3, \"[x] Bob\")\npane:setLink(3, 2, 1, function()\n  send(\"order bob leave\")\nend, \"Send Bob away\")","lang":"lua"}]},{"group":"reference","heading":"pane:setRadio","syntax":["pane:setRadio(row, col, opts) → toggle"],"text":["Draws a radio button, ( ) Label, or (•) Label when chosen. Of the radio buttons of one group in the pane one is chosen at a time: a click chooses this one and calls opts.onChange(value).","Parameters:","- pane (pane): A pane from createPane.","- row (number): The row, from 1.","- col (number): The first column, from 1.","- opts (table): group (a name, required), value (what onChange gets; default the label), label (colour tags allowed), checked, hint (a tooltip) and onChange(value).","Returns: A toggle: toggle:checked(), toggle:set(on), toggle:remove()."],"examples":[{"code":"for i, f in ipairs({\"name\", \"desc\", \"note\"}) do\n  pane:setRadio(1, i * 8 - 7, {group = \"field\", value = f, label = f, checked = f == field,\n    onChange = function(v) field = v end})\nend","lang":"lua"}]},{"group":"reference","heading":"pane:setText","syntax":["pane:setText(row, col, text)"],"text":["Writes text over the cells of a row from column col, keeping the row's other cells, its links and its text fields. For a counter or a status cell that changes often.","Writing what is already there changes nothing, so it costs no redraw.","Parameters:","- pane (pane): A pane from createPane.","- row (number): The row, from 1 (a text row, not a full-row gauge; bars from pane:gauge with col stay under the text).","- col (number): The first column, from 1; a shorter row is padded with spaces.","- text (string): Text with colour tags and the pane's shades (<@dim>)."],"examples":[{"code":"pane:setLine(1, \" HP:      [rest]\")\npane:setLink(1, 11, 6, function() send(\"rest\") end, \"Rest\")\npane:setText(1, 6, \"<green>120\")","lang":"lua"}]},{"group":"reference","heading":"pane:setTitle","syntax":["pane:setTitle(text)"],"text":["Changes the title in the pane's frame and in the Panes box.","Parameters:","- pane (pane): A pane from createPane.","- text (string): The new title (at most 60 characters)."],"examples":[{"code":"pane:setTitle(\"Mercenaries (\" .. count .. \")\")","lang":"lua"}]},{"group":"reference","heading":"pane:show","syntax":["pane:show()"],"text":["Switches the pane on, as its switch in the Panes box does.","On and off are the player's setting, kept across sessions; the close cross switches a pane off too. A temporary pane's on and off are kept only while it is open.","Parameters:","- pane (pane): A pane from createPane."],"examples":[{"code":"tempAlias(\"^merc$\", function()\n  if pane:visible() then pane:hide() else pane:show() end\nend)","lang":"lua"}]},{"group":"reference","heading":"pane:size","syntax":["pane:size() → rows, cols"],"text":["The pane's content size in cells now: rows and columns. Both are 0 while the pane is not shown.","Parameters:","- pane (pane): A pane from createPane.","Returns: rows, cols (two numbers)."],"examples":[{"code":"local rows, cols = pane:size()\npane:setLine(1, string.rep(\"-\", cols))","lang":"lua"}]},{"group":"reference","heading":"pane:theme","syntax":["pane:theme() → table"],"text":["The pane's colours now, as #rrggbb: for drawing in the pane's own look, such as a bar's track or a text colour that suits a light pane.","The colours change when the player picks another pane colour or theme in Options; pane:onTheme tells you. Colour tags such as <@dim> follow by themselves, so most panes need no theme.","Parameters:","- pane (pane): A pane from createPane.","Returns: A table: light (true on a light, paper pane), bg (the pane's background), fg (the colour of text without a colour tag) and shades, a table of the pane's shades by their tag names: track, dim, mid, bg, text, label and glow, as <@track> … <@glow>. nil once the pane is closed."],"examples":[{"code":"local th = pane:theme()\nif th.light then\n  pane:setLine(1, \"<@text>paper\")\nend","lang":"lua"}]},{"group":"reference","heading":"pane:visible","syntax":["pane:visible() → boolean"],"text":["true when the pane is switched on (it may still lack room in a small window).","Parameters:","- pane (pane): A pane from createPane.","Returns: true or false."],"examples":[{"code":"if not pane:visible() then echo(\"The pane is off; pane:show() brings it back.\") end","lang":"lua"}]},{"group":"reference","heading":"pane:wantSize","syntax":["pane:wantSize(rows, cols) → boolean"],"text":["Asks for a content size for the pane where it is docked now: rows in a side dock; in the top or bottom dock rows set its lane's height when it is alone in the lane, and cols its width along the lane.","Asking again for the same size at the same place changes nothing, so a size the player dragged stays until the script asks for another. A float keeps the size the player gave it.","Parameters:","- pane (pane): A pane from createPane.","- rows (number): Wanted rows, from 1.","- cols (number?): Wanted columns (the top and bottom docks).","Returns: true when the request applies where the pane is, false for a float or a temporary pane."],"examples":[{"code":"pane:wantSize(#lines)","lang":"lua"}]},{"group":"reference","heading":"print","syntax":["print(...)"],"text":["Writes its arguments to the game output, separated by tabs.","Parameters:","- ... (any): Values to show. Strings and numbers as text, booleans as true/false, others by type name (nil, table)."],"examples":[{"code":"print(\"kills:\", store.get(\"kills\"))","lang":"lua"}]},{"group":"reference","heading":"registerAnonymousEventHandler","syntax":["registerAnonymousEventHandler(event, fn) → id"],"text":["Calls fn(event, …) for an event: \"gmcp.Char.Vitals\", \"sysLoadEvent\", \"sysSettingChanged\", \"sysConnectionEvent\", \"sysDisconnectionEvent\", \"sysPanesChanged\", \"sysGameTimeEvent\" or a #event name such as \"SESSION CONNECTED\".","sysSettingChanged fires for this script only when one of its @setting values changed (#script set, setSetting): fn(event, name, value). settings already holds the new value, so redraw from it.","As in Mudlet, a GMCP message also raises every level above it, the outer one first: Char.Vitals raises \"gmcp.Char\", then \"gmcp.Char.Vitals\". A GMCP handler gets its own event name, then the full one; read the data from the gmcp table.","Parameters:","- event (string): The event name; case does not matter. Any name is accepted, but only the events in the Events and GMCP section fire.","- fn (function): Called with the event name, then the event's arguments.","Returns: An id (a number) for the matching kill function."],"examples":[{"code":"registerAnonymousEventHandler(\"gmcp.Char.Vitals\", function(event)\n  local hp = gmcp.Char.Vitals.hp\n  if hp and hp < 50 then cecho(\"<red>Low HP!<reset>\") end\nend)","lang":"lua"}]},{"group":"reference","heading":"replaceLine","syntax":["replaceLine(text)"],"text":["In a trigger: shows text instead of the current line. cecho colour tags work.","Only the shown copy changes: other triggers and the run log see the line as the game sent it. The profile's substitutes, gags and highlights then apply to the new text.","Outside a trigger it does nothing.","Parameters:","- text (string): The new text; cecho colour tags work. A line break becomes a space."],"examples":[{"code":"tempTrigger(\"You are thirsty.\", function()\n  replaceLine(\"<yellow>*** THIRSTY ***<reset>\")\nend)","lang":"lua"}]},{"group":"reference","heading":"scriptName","syntax":["scriptName"],"text":["This script's name, as on the Scripts page (a Duplicate has its own)."],"examples":[{"code":"echo(\"Change it with #script set \" .. scriptName .. \" delay 1\")","lang":"lua"}]},{"group":"reference","heading":"send","syntax":["send(cmd)"],"text":["Sends cmd to the game as it is, without aliases.","Parameters:","- cmd (string): One command. ; and # are not special here."],"examples":[{"code":"send(\"kill orc\")","lang":"lua"}]},{"group":"reference","heading":"setPaneOn","syntax":["setPaneOn(id, on) → boolean"],"text":["Switches any pane on or off, as its close cross and the Panes box do.","Parameters:","- id (string): A pane id from getPanes (\"comm\", \"merc/main\").","- on (boolean): true to show it, false to hide it.","Returns: true, or false when there is no such pane now (an unknown id, a temporary pane, or a pane of a script that is not running)."],"examples":[{"code":"setPaneOn(\"map\", false)","lang":"lua"}]},{"group":"reference","heading":"setSetting","syntax":["setSetting(name, value)"],"text":["Saves one of this script's own @setting values, as #script set does. settings.<name> shows it once saved.","The save takes a moment: settings.<name> still has the old value right after the call. A value that does not convert gives a UI message.","Parameters:","- name (string): A setting the header declares with @setting; another name is an error.","- value (any): A string, number or boolean, converted to the setting's type. A number must be inside the setting's range, a choice one of its options."],"examples":[{"code":"tempAlias(\"^autoloot (on|off)$\", function()\n  setSetting(\"auto\", matches[2] == \"on\")\nend)","lang":"lua"}]},{"group":"reference","heading":"settings","syntax":["settings.<name>"],"text":["The values of the header's @setting lines (read-only). The player changes one on the Scripts page or with #script set {script} {setting} {value}.","An unset setting has its default. When a setting changes, settings shows the new value at once, without a reload, so read settings.<name> when you need it instead of copying it once at load. The event sysSettingChanged (name, value) tells the script when one changed, for example to redraw a pane."],"examples":[{"code":"-- @setting  auto  boolean true \"Loot after kills\"\nif settings.auto then send(\"get coins all.corpse\") end","lang":"lua"}]},{"group":"reference","heading":"setVariable","syntax":["setVariable(name, value)"],"text":["Sets a tt++ variable of the profile, as #variable does.","As in an action: the profile text is updated only for a variable the profile declares with #variable; any other lasts for the session.","Parameters:","- name (string): The variable name without $. Not empty.","- value (any): A string, number or boolean; stored as text."],"examples":[{"code":"tempAlias(\"^t (\\\\w+)$\", function()\n  setVariable(\"target\", matches[2])\nend)","lang":"lua"}]},{"group":"reference","heading":"state","syntax":["state.char / state.group / state.room"],"text":["Read-only view of the character (name, vitals, status), the group members and the room.","state.char has name, fullname, vitals (the Char.Vitals fields) and status (the Char.StatusVars fields). state.group is a list of your group members (players wherever they are, NPCs only in your room), each with id, type, name, label and hp, mana, mp as { value, max, word }, plus position, ride, room, mapid, away (a player not in your room) and flags (sanctuary, poison, slept, blind, bashed, snared, wound, hungry, thirsty, waiting as true or false). state.room is the last Room.Info."],"examples":[{"code":"for _, m in ipairs(state.group) do\n  echo(m.name .. \": \" .. (m.hp.word or \"?\"))\nend","lang":"lua"}]},{"group":"reference","heading":"store","syntax":["store"],"text":["Data this script keeps between sessions: store.get(key) and store.set(key, value).","Each script has its own store. It is kept in the browser and survives reloads and new releases; deleting the script deletes it. A Duplicate starts with an empty store."],"examples":[{"code":"local n = (store.get(\"deaths\") or 0) + 1\nstore.set(\"deaths\", n)","lang":"lua"}]},{"group":"reference","heading":"store.get","syntax":["store.get(key) → value"],"text":["A value saved with store.set, or nil.","Parameters:","- key (string): The key it was saved under.","Returns: A copy of the saved value, or nil. Changing a table you got does not change the store until you store.set it again."],"examples":[{"code":"local kills = store.get(\"kills\") or 0","lang":"lua"}]},{"group":"reference","heading":"store.set","syntax":["store.set(key, value)"],"text":["Saves a string, number, boolean or table under key. nil removes it.","The value is in memory at once and written to the browser's storage about a second later, and when the page is hidden.","Parameters:","- key (string): The key.","- value (any): A string, number, boolean or a table of them (copied); nil removes the key. Functions are not kept."],"examples":[{"code":"store.set(\"kills\", 12)\nstore.set(\"friends\", { \"Rasta\", \"Ithilwen\" })","lang":"lua"}]},{"group":"reference","heading":"tempAlias","syntax":["tempAlias(regex, fn) → id"],"text":["Calls fn for a typed command the regular expression matches (not anchored: use ^ and $). The command is consumed unless fn returns false.","Only one alias takes a command. A profile alias of the same priority wins over a script alias.","When fn returns false, the next alias may take the command; if none does, it is sent to the game as typed.","Parameters:","- regex (string): A JavaScript regular expression matched against the typed command.","- fn (function): Called with no arguments; read matches and command. Return false to let the command go on.","Returns: An id (a number) for the matching kill function."],"examples":[{"code":"tempAlias(\"^k (\\\\w+)$\", function()\n  send(\"kill \" .. matches[2])\nend)","lang":"lua"}]},{"group":"reference","heading":"tempKey","syntax":["tempKey(name, fn) → id"],"text":["Calls fn when the key is pressed. Names as in the profile: \"F5\", \"Alt+a\", \"Numpad0\".","Keys that type text (a letter, digit or punctuation key alone or with Shift), ESC, Enter and the keys the browser keeps (Ctrl+W, Ctrl+T, Ctrl+N, Ctrl+Tab …) cannot be bound: tempKey raises an error.","A profile macro on the same key wins over the script. When two scripts bind a key, the newest binding wins.","Parameters:","- name (string): A key name as in the profile's #macro: \"F5\", \"Numpad 0\", \"Alt+a\", \"Ctrl+Shift+F1\".","- fn (function): Called with no arguments when the key is pressed.","Returns: An id (a number) for the matching kill function."],"examples":[{"code":"tempKey(\"F5\", function()\n  send(\"flee\")\nend)","lang":"lua"}]},{"group":"reference","heading":"tempRegexTrigger","syntax":["tempRegexTrigger(regex, fn) → id"],"text":["Calls fn for every game line the regular expression (JavaScript syntax) matches. matches[1] is the whole match, matches[2] … the groups.","The expression is JavaScript's, not Mudlet's PCRE; the common parts (\\w, \\d, \\s, groups, ?:, classes, anchors) are the same.","A backslash must be doubled inside a Lua string (\"\\\\.\"), or write the expression as a long string: [[^You receive (\\d+) coins\\.$]].","A group that did not take part in the match gives an empty string.","Parameters:","- regex (string): A JavaScript regular expression, case-sensitive. Use ^ and $ to match the whole line.","- fn (function): Called with no arguments for each matching line; read line and matches.","Returns: An id (a number) for the matching kill function."],"examples":[{"code":"tempRegexTrigger(\"^(\\\\w+) tells you '(.*)'$\", function()\n  uiMessage(\"tell\", matches[2] .. \": \" .. matches[3])\nend)","lang":"lua"}]},{"group":"reference","heading":"tempTimer","syntax":["tempTimer(seconds, fn[, repeat]) → id"],"text":["Calls fn after seconds; again every seconds when repeat is true (50 ms at least).","Parameters:","- seconds (number): Seconds to wait, 0 or more; fractions work (0.5).","- fn (function): Called with no arguments when the time is up.","- repeat (boolean?): true: call fn again every seconds (at least 0.05) until killTimer. Default: once.","Returns: An id (a number) for the matching kill function."],"examples":[{"code":"tempTimer(2.5, function()\n  send(\"stand\")\nend)","lang":"lua"}]},{"group":"reference","heading":"tempTrigger","syntax":["tempTrigger(substring, fn) → id"],"text":["Calls fn for every game line that contains substring. In fn, line is the line and matches[1] the match.","Every trigger that matches a line runs, the profile's actions too: one match does not stop the others.","The trigger lives until killTrigger(id) or until the script stops; you never need to clean up.","Parameters:","- substring (string): Text to look for anywhere in the line, literally and case-sensitively. Not empty.","- fn (function): Called with no arguments for each matching line; read line and matches.","Returns: An id (a number) for the matching kill function."],"examples":[{"code":"tempTrigger(\"You are hungry.\", function()\n  send(\"eat bread\")\nend)","lang":"lua"}]},{"group":"reference","heading":"toggle:checked","syntax":["toggle:checked() → boolean"],"text":["Whether the checkbox or radio button is checked; nil once it is gone.","Parameters:","- toggle (toggle): A toggle from pane:setCheckbox or pane:setRadio.","Returns: true, false, or nil."],"examples":[{"code":"if cs:checked() then echo(\"case counts\") end","lang":"lua"}]},{"group":"reference","heading":"toggle:remove","syntax":["toggle:remove()"],"text":["Takes the checkbox or radio button away and blanks its cells. Its methods then do nothing.","Parameters:","- toggle (toggle): A toggle from pane:setCheckbox or pane:setRadio."],"examples":[{"code":"cs:remove()","lang":"lua"}]},{"group":"reference","heading":"toggle:set","syntax":["toggle:set(on)"],"text":["Checks or unchecks it and redraws it; onChange is not called. A radio button set on unchooses the others of its group.","Parameters:","- toggle (toggle): A toggle from pane:setCheckbox or pane:setRadio.","- on (boolean): Checked or not."],"examples":[{"code":"cs:set(false)","lang":"lua"}]},{"group":"reference","heading":"uiMessage","syntax":["uiMessage(source, text)"],"text":["Writes a line to the UI messages pane: ▶ SOURCE: text.","Parameters:","- source (string): A short label, shown in capitals (at most 20 characters; empty gives SCRIPT).","- text (string): The message."],"examples":[{"code":"uiMessage(\"loot\", \"Picked up the coins.\")","lang":"lua"}]},{"group":"reference","heading":"wrapText","syntax":["wrapText(text, width, indent) → table"],"text":["Word-wraps text to width cells, for a pane: returns the lines as a list, each ready for pane:setLine. Colour tags work and take no cells.","Lines break at spaces, and the spaces at a break go; a word wider than the line is cut. A line that starts in a colour (or background) opens it again, so each line looks right on its own row.","Parameters:","- text (string): The text; colour tags (and pane shades such as <@dim>) work. A \\n always starts a new line.","- width (number): The most cells per line, usually cols from pane:size() or onResize. Under 1 or nil: the text is only split at \\n.","- indent (number?): Spaces before every line after the first of a paragraph (a hanging indent); they count toward width. Default 0.","Returns: A list of strings, from 1."],"examples":[{"code":"pane:onResize(function(rows, cols)\n  pane:clear()\n  for i, l in ipairs(wrapText(msg, cols, 2)) do pane:setLine(i, l) end\nend)","lang":"lua"}]},{"group":"lua","heading":"Lua library","text":["The plain Lua a script can use: the base functions and the string, table, math, utf8 and coroutine libraries. Each name below has its own entry after this index (click it, or pick it in the menu). The keywords and the basics are in Lua basics; patterns in Lua patterns.","Base functions (print is in the API reference):","- assert: Stops with an error when v is false or nil; otherwise returns all its arguments.","- error: Stops the running function with an error.","- getmetatable: The metatable of v, or nil.","- ipairs: Walks a list in order: t[1], t[2], … until the first nil.","- next: The key after key in t, and its value (the first ones when key is nil); nil at the end.","- pairs: Walks every key and value of a table, in no particular order.","- pcall: Calls f with the other arguments and catches any error, so your script goes on.","- rawequal: Whether a and b are the same value, ignoring a __eq metamethod.","- rawget: t[key] without the __index metamethod: only what the table itself holds.","- rawlen: The length of a table or string, ignoring a __len metamethod.","- rawset: Sets t[key] = value without the __newindex metamethod.","- select: With a number n, the arguments from the n-th on; with \"#\", how many arguments there are.","- setmetatable: Gives table t the metatable mt (nil removes it).","- tonumber: Turns text such as \"42\", \"3.5\" or \"0x1F\" into a number; nil when it is not one.","- tostring: Any value as text: numbers, true/false, nil, and tables or functions by their address (or their __tostring).","- type: The type of v as a word: \"nil\", \"boolean\", \"number\", \"string\", \"table\", \"function\" or \"thread\".","- xpcall: Like pcall, but on an error calls handler(message) and returns false and what the handler returns.","- _VERSION: The Lua version as text: \"Lua 5.4\".","string: Text functions. Each also works as a method on a string: line:upper(), name:sub(1, 3), line:match(\"%d+\"). Lua patterns (match, find, gmatch, gsub) are not regular expressions; see Lua patterns in the manual.","- string.byte: The byte codes of the characters from i to j (i defaults to 1, j to i).","- string.char: A string made from byte codes: string.char(72, 105) is \"Hi\".","- string.find: Looks for pattern in s.","- string.format: Builds a string from a template: each % item takes the next argument.","- string.gmatch: Walks every match of pattern in s.","- string.gsub: Replaces the matches of pattern in s.","- string.len: The length of s in bytes, the same as #s.","- string.lower: s in lower case (ASCII letters).","- string.match: The captures of the first match of pattern in s (or the whole match when there are none), or nil.","- string.pack: Packs values into a binary string by a format (see string.unpack).","- string.packsize: The size in bytes of a string.pack format.","- string.rep: s repeated n times, with sep between the copies.","- string.reverse: s backwards (byte by byte).","- string.sub: The part of s from position i to j, both included.","- string.unpack: Reads values from a binary string made by string.pack.","- string.upper: s in upper case (ASCII letters).","table: Functions for lists: tables with keys 1, 2, 3 …","- table.concat: Joins the strings and numbers of a list into one string, with sep between them.","- table.insert: Adds value at the end of a list, or at position pos, moving the later items up.","- table.move: Copies a1[f] … a1[e] into a2 starting at index t (a2 defaults to a1).","- table.pack: A new list of all its arguments, with the field n set to how many there were (nils included).","- table.remove: Removes the item at pos (default: the last) from a list and returns it; later items move down.","- table.sort: Sorts a list in place, smallest first, or by comp(a, b), which returns true when a goes before b.","- table.unpack: The items of a list as separate values: t[1], t[2], ….","math: Numbers: rounding, limits, random numbers and the usual functions.","- math.abs: x without its sign: math.abs(-5) is 5.","- math.acos: The arc cosine of x, in radians.","- math.asin: The arc sine of x, in radians.","- math.atan: The arc tangent of y/x, in radians, using both signs to find the quadrant.","- math.ceil: x rounded up to a whole number: math.ceil(2.1) is 3.","- math.cos: The cosine of an angle in radians.","- math.deg: Radians to degrees.","- math.exp: e to the power x.","- math.floor: x rounded down to a whole number: math.floor(2.9) is 2.","- math.fmod: The remainder of x / y, with the sign of x (the % operator takes the sign of y).","- math.huge: A number larger than any other (infinity).","- math.log: The logarithm of x (natural, or in the given base).","- math.max: The largest of its arguments.","- math.maxinteger: The largest whole number Lua can hold.","- math.min: The smallest of its arguments.","- math.mininteger: The smallest (most negative) whole number Lua can hold.","- math.modf: Splits x into its whole part and its fraction: math.modf(3.7) gives 3.0 and 0.7.","- math.pi: The number π (3.14159…).","- math.rad: Degrees to radians.","- math.random: A random number: math.random() a fraction from 0 up to 1, math.random(n) a whole number 1 … n, math.random(m, n) a whole number m … n.","- math.randomseed: Starts the random numbers from a seed, so a sequence can be repeated.","- math.sin: The sine of an angle in radians.","- math.sqrt: The square root of x.","- math.tan: The tangent of an angle in radians.","- math.tointeger: x as a whole number when it is one (3.0 → 3); nil otherwise.","- math.type: \"integer\" for a whole number, \"float\" for a number with a fraction, nil for anything else.","- math.ult: Whether m < n when both are read as unsigned integers.","utf8: Characters rather than bytes: å or ö take two bytes in a string, but one character.","- utf8.char: A string from character codes (code points).","- utf8.charpattern: A pattern that matches one UTF-8 character; use it with gmatch to walk the characters of a string.","- utf8.codepoint: The code points of the characters that start between byte positions i and j.","- utf8.codes: Walks the characters of s: each step gives the byte position and the code point.","- utf8.len: The number of characters in s (from byte i to j); nil and a position when s is not valid UTF-8.","- utf8.offset: The byte position where the n-th character starts (counting from byte i).","coroutine: Functions that pause and resume. Rarely needed in scripts: timers and triggers usually do the job.","- coroutine.close: Ends a suspended or dead coroutine.","- coroutine.create: Makes a coroutine from a function; it starts when you first resume it.","- coroutine.isyieldable: Whether the running code may call coroutine.yield.","- coroutine.resume: Starts or continues a coroutine; the arguments go to its function or come back from its yield.","- coroutine.running: The running coroutine, and true when it is the main one.","- coroutine.status: The state of a coroutine: \"running\", \"suspended\", \"normal\" or \"dead\".","- coroutine.wrap: Makes a coroutine and returns a function that resumes it; errors pass through.","- coroutine.yield: Pauses the running coroutine; its values go to the resume that started it."]},{"group":"lua","heading":"assert","syntax":["assert(v, message) → v, …"],"text":["Stops with an error when v is false or nil; otherwise returns all its arguments.","Parameters:","- v (any): The value to test.","- message (string?): The error message (default: \"assertion failed!\").","Returns: All its arguments, when v is neither false nor nil."],"examples":[{"code":"local hp = assert(tonumber(\"42\"), \"not a number\")","lang":"lua"}]},{"group":"lua","heading":"error","syntax":["error(message, level)"],"text":["Stops the running function with an error. The script reports it, or a surrounding pcall catches it.","Parameters:","- message (any): The error, usually a string.","- level (number?): 1 (default) adds the line of the error call, 2 the line of its caller, 0 no line."],"examples":[{"code":"local function heal(who)\n  if not who then error(\"heal: no target\", 2) end\n  send(\"cast 'cure light' \" .. who)\nend","lang":"lua"}]},{"group":"lua","heading":"getmetatable","syntax":["getmetatable(v) → table"],"text":["The metatable of v, or nil. In scripts a string's metatable is hidden: getmetatable(\"\") gives false.","Parameters:","- v (any): Any value.","Returns: The metatable (or its __metatable field), or nil."],"examples":[{"code":"local mt = getmetatable(obj)","lang":"lua"}]},{"group":"lua","heading":"ipairs","syntax":["ipairs(t) → iterator"],"text":["Walks a list in order: t[1], t[2], … until the first nil. Use it in a for loop.","Parameters:","- t (table): A table used as a list (keys 1, 2, 3 …).","Returns: An iterator for a generic for: each step gives the index and the value."],"examples":[{"code":"local mobs = { \"orc\", \"troll\", \"wolf\" }\nfor i, mob in ipairs(mobs) do\n  echo(i .. \". \" .. mob)\nend","lang":"lua"}]},{"group":"lua","heading":"next","syntax":["next(t, key) → key, value"],"text":["The key after key in t, and its value (the first ones when key is nil); nil at the end.","next(t) == nil is the way to test whether a table is empty (#t only counts a list).","Parameters:","- t (table): Any table.","- key (any?): The key to continue from; nil for the first.","Returns: The next key and its value, or nil when there is none."],"examples":[{"code":"if next(targets) == nil then echo(\"No targets.\") end","lang":"lua"}]},{"group":"lua","heading":"pairs","syntax":["pairs(t) → iterator"],"text":["Walks every key and value of a table, in no particular order. Use it in a for loop.","Changing or clearing a value during the walk is fine; adding new keys is not.","Parameters:","- t (table): Any table, also gmcp, state and settings.","Returns: An iterator for a generic for: each step gives a key and its value."],"examples":[{"code":"for key, value in pairs(gmcp.Char.Vitals) do\n  print(key, value)\nend","lang":"lua"}]},{"group":"lua","heading":"pcall","syntax":["pcall(f, ...) → ok, …"],"text":["Calls f with the other arguments and catches any error, so your script goes on.","Parameters:","- f (function): The function to call.","- ... (any): Arguments for f.","Returns: true and f's results, or false and the error message."],"examples":[{"code":"local ok, err = pcall(function()\n  send(\"say \" .. gmcp.Char.Name.name)\nend)\nif not ok then echo(\"No name yet: \" .. tostring(err)) end","lang":"lua"}]},{"group":"lua","heading":"rawequal","syntax":["rawequal(a, b) → boolean"],"text":["Whether a and b are the same value, ignoring a __eq metamethod.","Parameters:","- a (any): A value.","- b (any): Another value.","Returns: true or false."],"examples":[{"code":"local same = rawequal(a, b)","lang":"lua"}]},{"group":"lua","heading":"rawget","syntax":["rawget(t, key) → value"],"text":["t[key] without the __index metamethod: only what the table itself holds.","Parameters:","- t (table): A table.","- key (any): The key.","Returns: The value, or nil."],"examples":[{"code":"local own = rawget(opts, \"food\")","lang":"lua"}]},{"group":"lua","heading":"rawlen","syntax":["rawlen(v) → number"],"text":["The length of a table or string, ignoring a __len metamethod.","Parameters:","- v (table|string): A table or a string.","Returns: The length."],"examples":[{"code":"local n = rawlen(list)","lang":"lua"}]},{"group":"lua","heading":"rawset","syntax":["rawset(t, key, value) → t"],"text":["Sets t[key] = value without the __newindex metamethod.","Refused on the read-only tables: gmcp, state, settings and the libraries.","Parameters:","- t (table): A table of your own.","- key (any): The key (not nil).","- value (any): The value.","Returns: The table t."],"examples":[{"code":"rawset(cache, \"hp\", 100)","lang":"lua"}]},{"group":"lua","heading":"select","syntax":["select(n, ...) → …"],"text":["With a number n, the arguments from the n-th on; with \"#\", how many arguments there are.","Parameters:","- n (number|string): A position (negative counts from the end), or \"#\".","- ... (any): The arguments.","Returns: The arguments from position n, or their count."],"examples":[{"code":"local function count(...)\n  return select(\"#\", ...)\nend\necho(count(\"a\", nil, \"c\")) -- 3","lang":"lua"}]},{"group":"lua","heading":"setmetatable","syntax":["setmetatable(t, mt) → t"],"text":["Gives table t the metatable mt (nil removes it). A metatable adds behaviour, such as default values through __index.","Useful fields: __index (defaults or methods), __newindex, __tostring, __eq, __lt, __le, __len, __call, __concat and the arithmetic ones (__add …).","In scripts a metatable with __gc is refused.","Parameters:","- t (table): The table.","- mt (table?): The metatable, or nil.","Returns: The table t."],"examples":[{"code":"local defaults = { food = \"bread\" }\nlocal opts = setmetatable({}, { __index = defaults })\necho(opts.food) -- bread","lang":"lua"}]},{"group":"lua","heading":"tonumber","syntax":["tonumber(v, base) → number"],"text":["Turns text such as \"42\", \"3.5\" or \"0x1F\" into a number; nil when it is not one.","Parameters:","- v (any): Usually a string, such as a match from a trigger.","- base (number?): The base (2 to 36) for whole numbers, such as 16 for hex.","Returns: The number, or nil."],"examples":[{"code":"local gold = tonumber(matches[2]) or 0","lang":"lua"}]},{"group":"lua","heading":"tostring","syntax":["tostring(v) → string"],"text":["Any value as text: numbers, true/false, nil, and tables or functions by their address (or their __tostring).","Parameters:","- v (any): Any value.","Returns: The text."],"examples":[{"code":"echo(\"Ready: \" .. tostring(ready))","lang":"lua"}]},{"group":"lua","heading":"type","syntax":["type(v) → string"],"text":["The type of v as a word: \"nil\", \"boolean\", \"number\", \"string\", \"table\", \"function\" or \"thread\".","Parameters:","- v (any): Any value.","Returns: The type name."],"examples":[{"code":"if type(gmcp.Char) == \"table\" then echo(\"GMCP is here.\") end","lang":"lua"}]},{"group":"lua","heading":"xpcall","syntax":["xpcall(f, handler, ...) → ok, …"],"text":["Like pcall, but on an error calls handler(message) and returns false and what the handler returns.","In scripts the handler runs after the error has unwound, not at the point of the error.","Parameters:","- f (function): The function to call.","- handler (function): Called with the error message.","- ... (any): Arguments for f.","Returns: true and f's results, or false and the handler's result."],"examples":[{"code":"local ok, msg = xpcall(risky, function(err)\n  return \"risky failed: \" .. tostring(err)\nend)","lang":"lua"}]},{"group":"lua","heading":"_VERSION","syntax":["_VERSION"],"text":["The Lua version as text: \"Lua 5.4\"."],"examples":[{"code":"echo(_VERSION)","lang":"lua"}]},{"group":"lua","heading":"string.byte","syntax":["string.byte(s, i, j) → codes…"],"text":["The byte codes of the characters from i to j (i defaults to 1, j to i).","Parameters:","- s (string): The text to work on. As a method, s is what comes before the colon: line:upper() is string.upper(line).","- i (number?): The first position (default 1).","- j (number?): The last position (default i).","Returns: One number per byte."],"examples":[{"code":"local code = (\"A\"):byte() -- 65","lang":"lua"}]},{"group":"lua","heading":"string.char","syntax":["string.char(...) → string"],"text":["A string made from byte codes: string.char(72, 105) is \"Hi\".","Parameters:","- ... (number): Byte codes, 0 to 255.","Returns: The string."],"examples":[{"code":"local bell = string.char(7)","lang":"lua"}]},{"group":"lua","heading":"string.find","syntax":["string.find(s, pattern, init, plain) → start, end, …"],"text":["Looks for pattern in s. Gives where the first match starts and ends (and its captures), or nil.","A pattern with two or more .- .* or .+ may be refused on a long line as too complex (see Sandbox and limits); anchor it and use narrower classes such as %S+ or [^,]+.","Parameters:","- s (string): The text to work on. As a method, s is what comes before the colon: line:upper() is string.upper(line).","- pattern (string): A Lua pattern, not a regular expression: %a letter, %d digit, %s space, %w letter or digit, . any character, * + - ? repeat, ^ and $ anchor, ( ) capture, %. a literal dot. See Lua patterns in the manual.","- init (number?): Where to start looking (1 = the first character; negative counts from the end).","- plain (boolean?): true: pattern is plain text, no special characters (fast, never refused).","Returns: The start and end positions and any captures, or nil when there is no match."],"examples":[{"code":"if line:find(\"orc\", 1, true) then\n  send(\"kill orc\")\nend","lang":"lua"}]},{"group":"lua","heading":"string.format","syntax":["string.format(fmt, ...) → string"],"text":["Builds a string from a template: each % item takes the next argument.","Parameters:","- fmt (string): The template: %d whole number, %s any value as text, %.1f number with one decimal, %5d or %-10s padded, %x hex, %q quoted, %% a percent sign.","- ... (any): One value per % item, in order.","Returns: The finished string."],"examples":[{"code":"echo(string.format(\"HP %d/%d (%.0f%%)\", 80, 120, 80 * 100 / 120))","lang":"lua"}]},{"group":"lua","heading":"string.gmatch","syntax":["string.gmatch(s, pattern, init) → iterator"],"text":["Walks every match of pattern in s. Each step gives the captures, or the whole match when there are none.","A pattern with two or more .- .* or .+ may be refused on a long line as too complex (see Sandbox and limits); anchor it and use narrower classes such as %S+ or [^,]+.","Parameters:","- s (string): The text to work on. As a method, s is what comes before the colon: line:upper() is string.upper(line).","- pattern (string): A Lua pattern, not a regular expression: %a letter, %d digit, %s space, %w letter or digit, . any character, * + - ? repeat, ^ and $ anchor, ( ) capture, %. a literal dot. See Lua patterns in the manual.","- init (number?): Where to start looking (1 = the first character; negative counts from the end).","Returns: An iterator for a generic for."],"examples":[{"code":"for n in line:gmatch(\"%d+\") do\n  print(tonumber(n))\nend","lang":"lua"}]},{"group":"lua","heading":"string.gsub","syntax":["string.gsub(s, pattern, repl, n) → string, count"],"text":["Replaces the matches of pattern in s. repl is a string (%1 is the first capture), a table (looked up with the match) or a function (called with the captures).","A pattern with two or more .- .* or .+ may be refused on a long line as too complex (see Sandbox and limits); anchor it and use narrower classes such as %S+ or [^,]+.","Put the call in parentheses to keep only the string: echo((s:gsub(\"x\", \"y\"))).","Parameters:","- s (string): The text to work on. As a method, s is what comes before the colon: line:upper() is string.upper(line).","- pattern (string): A Lua pattern, not a regular expression: %a letter, %d digit, %s space, %w letter or digit, . any character, * + - ? repeat, ^ and $ anchor, ( ) capture, %. a literal dot. See Lua patterns in the manual.","- repl (string|table|function): What to put instead: text with %0 (whole match) and %1 … (captures), a table, or a function whose result replaces the match (false or nil keeps it).","- n (number?): Replace at most this many matches.","Returns: The new string, and how many matches were replaced."],"examples":[{"code":"local short = line:gsub(\"%s+\", \" \")\nlocal masked = (\"pw 1234\"):gsub(\"%d\", \"*\")","lang":"lua"}]},{"group":"lua","heading":"string.len","syntax":["string.len(s) → number"],"text":["The length of s in bytes, the same as #s. Letters such as å take two bytes; utf8.len counts characters.","Parameters:","- s (string): The text to work on. As a method, s is what comes before the colon: line:upper() is string.upper(line).","Returns: The number of bytes."],"examples":[{"code":"if line:len() > 80 then echo(\"A long line.\") end","lang":"lua"}]},{"group":"lua","heading":"string.lower","syntax":["string.lower(s) → string"],"text":["s in lower case (ASCII letters).","Parameters:","- s (string): The text to work on. As a method, s is what comes before the colon: line:upper() is string.upper(line).","Returns: The new string."],"examples":[{"code":"if command:lower() == \"flee\" then echo(\"Run!\") end","lang":"lua"}]},{"group":"lua","heading":"string.match","syntax":["string.match(s, pattern, init) → captures…"],"text":["The captures of the first match of pattern in s (or the whole match when there are none), or nil.","A pattern with two or more .- .* or .+ may be refused on a long line as too complex (see Sandbox and limits); anchor it and use narrower classes such as %S+ or [^,]+.","Parameters:","- s (string): The text to work on. As a method, s is what comes before the colon: line:upper() is string.upper(line).","- pattern (string): A Lua pattern, not a regular expression: %a letter, %d digit, %s space, %w letter or digit, . any character, * + - ? repeat, ^ and $ anchor, ( ) capture, %. a literal dot. See Lua patterns in the manual.","- init (number?): Where to start looking (1 = the first character; negative counts from the end).","Returns: One string per capture, the whole match, or nil when there is no match."],"examples":[{"code":"local who, msg = line:match(\"^(%a+) tells you '(.*)'$\")\nif who then uiMessage(\"tell\", who .. \": \" .. msg) end","lang":"lua"}]},{"group":"lua","heading":"string.pack","syntax":["string.pack(fmt, ...) → string"],"text":["Packs values into a binary string by a format (see string.unpack). Rarely needed in scripts.","Parameters:","- fmt (string): The format, such as \"i4\" for a 4-byte integer.","- ... (any): The values.","Returns: The binary string."],"examples":[{"code":"local bin = string.pack(\"i2\", 1000)","lang":"lua"}]},{"group":"lua","heading":"string.packsize","syntax":["string.packsize(fmt) → number"],"text":["The size in bytes of a string.pack format.","Parameters:","- fmt (string): A pack format with fixed sizes only.","Returns: The size in bytes."],"examples":[{"code":"local size = string.packsize(\"i4i4\")","lang":"lua"}]},{"group":"lua","heading":"string.rep","syntax":["string.rep(s, n, sep) → string"],"text":["s repeated n times, with sep between the copies.","Parameters:","- s (string): The text to work on. As a method, s is what comes before the colon: line:upper() is string.upper(line).","- n (number): How many copies.","- sep (string?): Text between the copies (default none).","Returns: The new string."],"examples":[{"code":"echo(string.rep(\"-\", 30))","lang":"lua"}]},{"group":"lua","heading":"string.reverse","syntax":["string.reverse(s) → string"],"text":["s backwards (byte by byte).","Parameters:","- s (string): The text to work on. As a method, s is what comes before the colon: line:upper() is string.upper(line).","Returns: The new string."],"examples":[{"code":"local back = (\"north\"):reverse()","lang":"lua"}]},{"group":"lua","heading":"string.sub","syntax":["string.sub(s, i, j) → string"],"text":["The part of s from position i to j, both included. Negative positions count from the end: -1 is the last character.","Parameters:","- s (string): The text to work on. As a method, s is what comes before the colon: line:upper() is string.upper(line).","- i (number): The first position (1 = the first character).","- j (number?): The last position (default -1, the end).","Returns: The part, or \"\" when it is empty."],"examples":[{"code":"local first = name:sub(1, 1)\nlocal last3 = name:sub(-3)","lang":"lua"}]},{"group":"lua","heading":"string.unpack","syntax":["string.unpack(fmt, s, pos) → values…, next"],"text":["Reads values from a binary string made by string.pack. Rarely needed in scripts.","Parameters:","- fmt (string): The format.","- s (string): The binary string.","- pos (number?): Where to start (default 1).","Returns: The values, then the position after them."],"examples":[{"code":"local n = string.unpack(\"i2\", bin)","lang":"lua"}]},{"group":"lua","heading":"string.upper","syntax":["string.upper(s) → string"],"text":["s in upper case (ASCII letters).","Parameters:","- s (string): The text to work on. As a method, s is what comes before the colon: line:upper() is string.upper(line).","Returns: The new string."],"examples":[{"code":"cecho(\"<red>\" .. matches[2]:upper() .. \"<reset>\")","lang":"lua"}]},{"group":"lua","heading":"table.concat","syntax":["table.concat(t, sep, i, j) → string"],"text":["Joins the strings and numbers of a list into one string, with sep between them.","Parameters:","- t (table): A table used as a list (keys 1, 2, 3 …).","- sep (string?): Text between the items (default none).","- i (number?): The first index (default 1).","- j (number?): The last index (default #t).","Returns: The joined string."],"examples":[{"code":"local group = { \"Gandalf\", \"Frodo\", \"Sam\" }\necho(\"Group: \" .. table.concat(group, \", \"))","lang":"lua"}]},{"group":"lua","heading":"table.insert","syntax":["table.insert(t, [pos,] value)"],"text":["Adds value at the end of a list, or at position pos, moving the later items up.","Parameters:","- t (table): A table used as a list (keys 1, 2, 3 …).","- pos (number?): Where to insert. With only two arguments the second is the value and goes at the end.","- value (any): The item to add."],"examples":[{"code":"local seen = {}\ntable.insert(seen, \"orc\")       -- at the end\ntable.insert(seen, 1, \"troll\")  -- first","lang":"lua"}]},{"group":"lua","heading":"table.move","syntax":["table.move(a1, f, e, t, a2) → a2"],"text":["Copies a1[f] … a1[e] into a2 starting at index t (a2 defaults to a1).","Parameters:","- a1 (table): The list to copy from.","- f (number): The first index to copy.","- e (number): The last index to copy.","- t (number): Where the copy starts in a2.","- a2 (table?): The list to copy into (default a1).","Returns: The table a2."],"examples":[{"code":"local copy = table.move(list, 1, #list, 1, {})","lang":"lua"}]},{"group":"lua","heading":"table.pack","syntax":["table.pack(...) → table"],"text":["A new list of all its arguments, with the field n set to how many there were (nils included).","Parameters:","- ... (any): The values.","Returns: The table."],"examples":[{"code":"local args = table.pack(1, nil, 3)\necho(args.n) -- 3","lang":"lua"}]},{"group":"lua","heading":"table.remove","syntax":["table.remove(t, pos) → value"],"text":["Removes the item at pos (default: the last) from a list and returns it; later items move down.","Parameters:","- t (table): A table used as a list (keys 1, 2, 3 …).","- pos (number?): The index to remove (default #t).","Returns: The removed item."],"examples":[{"code":"local queue = { \"n\", \"e\", \"s\" }\nlocal step = table.remove(queue, 1) -- \"n\"\nsend(step)","lang":"lua"}]},{"group":"lua","heading":"table.sort","syntax":["table.sort(t, comp)"],"text":["Sorts a list in place, smallest first, or by comp(a, b), which returns true when a goes before b.","Parameters:","- t (table): A table used as a list (keys 1, 2, 3 …).","- comp (function?): Compares two items; true when the first goes before the second."],"examples":[{"code":"local group = { { name = \"Sam\", hp = 40 }, { name = \"Frodo\", hp = 75 } }\ntable.sort(group, function(a, b) return a.hp < b.hp end)\necho(group[1].name .. \" is hurt the most\")","lang":"lua"}]},{"group":"lua","heading":"table.unpack","syntax":["table.unpack(t, i, j) → values…"],"text":["The items of a list as separate values: t[1], t[2], …. In Lua 5.4 there is no plain unpack; use table.unpack.","Parameters:","- t (table): A table used as a list (keys 1, 2, 3 …).","- i (number?): The first index (default 1).","- j (number?): The last index (default #t).","Returns: The items, one value each."],"examples":[{"code":"local dirs = { \"north\", \"east\" }\nprint(table.unpack(dirs))","lang":"lua"}]},{"group":"lua","heading":"math.abs","syntax":["math.abs(x) → number"],"text":["x without its sign: math.abs(-5) is 5.","Parameters:","- x (number): A number.","Returns: The absolute value."],"examples":[{"code":"local diff = math.abs(hp - lastHp)","lang":"lua"}]},{"group":"lua","heading":"math.acos","syntax":["math.acos(x) → number"],"text":["The arc cosine of x, in radians.","Parameters:","- x (number): A number.","Returns: An angle in radians."],"examples":[{"code":"local a = math.acos(0.5)","lang":"lua"}]},{"group":"lua","heading":"math.asin","syntax":["math.asin(x) → number"],"text":["The arc sine of x, in radians.","Parameters:","- x (number): A number.","Returns: An angle in radians."],"examples":[{"code":"local a = math.asin(0.5)","lang":"lua"}]},{"group":"lua","heading":"math.atan","syntax":["math.atan(y, x) → number"],"text":["The arc tangent of y/x, in radians, using both signs to find the quadrant.","Parameters:","- y (number): The y value.","- x (number?): The x value (default 1).","Returns: An angle in radians."],"examples":[{"code":"local angle = math.atan(dy, dx)","lang":"lua"}]},{"group":"lua","heading":"math.ceil","syntax":["math.ceil(x) → integer"],"text":["x rounded up to a whole number: math.ceil(2.1) is 3.","Parameters:","- x (number): A number.","Returns: The whole number."],"examples":[{"code":"local rounds = math.ceil(hp / 25)","lang":"lua"}]},{"group":"lua","heading":"math.cos","syntax":["math.cos(x) → number"],"text":["The cosine of an angle in radians.","Parameters:","- x (number): An angle in radians.","Returns: The cosine."],"examples":[{"code":"local c = math.cos(math.pi)","lang":"lua"}]},{"group":"lua","heading":"math.deg","syntax":["math.deg(x) → number"],"text":["Radians to degrees.","Parameters:","- x (number): An angle in radians.","Returns: The angle in degrees."],"examples":[{"code":"local d = math.deg(math.pi) -- 180.0","lang":"lua"}]},{"group":"lua","heading":"math.exp","syntax":["math.exp(x) → number"],"text":["e to the power x.","Parameters:","- x (number): A number.","Returns: The result."],"examples":[{"code":"local e = math.exp(1)","lang":"lua"}]},{"group":"lua","heading":"math.floor","syntax":["math.floor(x) → integer"],"text":["x rounded down to a whole number: math.floor(2.9) is 2. math.floor(x + 0.5) rounds to the nearest.","Parameters:","- x (number): A number.","Returns: The whole number."],"examples":[{"code":"local pct = math.floor(hp * 100 / maxhp)","lang":"lua"}]},{"group":"lua","heading":"math.fmod","syntax":["math.fmod(x, y) → number"],"text":["The remainder of x / y, with the sign of x (the % operator takes the sign of y).","Parameters:","- x (number): The dividend.","- y (number): The divisor.","Returns: The remainder."],"examples":[{"code":"local r = math.fmod(-7, 3) -- -1","lang":"lua"}]},{"group":"lua","heading":"math.huge","syntax":["math.huge"],"text":["A number larger than any other (infinity). Handy as a start value when you look for a minimum."],"examples":[{"code":"local lowest = math.huge\nfor _, hp in ipairs({ 40, 75 }) do lowest = math.min(lowest, hp) end","lang":"lua"}]},{"group":"lua","heading":"math.log","syntax":["math.log(x, base) → number"],"text":["The logarithm of x (natural, or in the given base).","Parameters:","- x (number): A number.","- base (number?): The base, such as 10 or 2 (default e).","Returns: The logarithm."],"examples":[{"code":"local digits = math.floor(math.log(12345, 10)) + 1","lang":"lua"}]},{"group":"lua","heading":"math.max","syntax":["math.max(x, ...) → number"],"text":["The largest of its arguments.","Parameters:","- x (number): A number.","- ... (number): More numbers.","Returns: The largest."],"examples":[{"code":"local best = math.max(10, 42, 7) -- 42","lang":"lua"}]},{"group":"lua","heading":"math.maxinteger","syntax":["math.maxinteger"],"text":["The largest whole number Lua can hold."],"examples":[{"code":"local big = math.maxinteger","lang":"lua"}]},{"group":"lua","heading":"math.min","syntax":["math.min(x, ...) → number"],"text":["The smallest of its arguments.","Parameters:","- x (number): A number.","- ... (number): More numbers.","Returns: The smallest."],"examples":[{"code":"local wait = math.min(delay, 5)","lang":"lua"}]},{"group":"lua","heading":"math.mininteger","syntax":["math.mininteger"],"text":["The smallest (most negative) whole number Lua can hold."],"examples":[{"code":"local small = math.mininteger","lang":"lua"}]},{"group":"lua","heading":"math.modf","syntax":["math.modf(x) → integer part, fraction"],"text":["Splits x into its whole part and its fraction: math.modf(3.7) gives 3.0 and 0.7.","Parameters:","- x (number): A number.","Returns: The whole part (a float) and the fraction."],"examples":[{"code":"local whole, frac = math.modf(3.7)","lang":"lua"}]},{"group":"lua","heading":"math.pi","syntax":["math.pi"],"text":["The number π (3.14159…)."],"examples":[{"code":"local circle = 2 * math.pi * r","lang":"lua"}]},{"group":"lua","heading":"math.rad","syntax":["math.rad(x) → number"],"text":["Degrees to radians.","Parameters:","- x (number): An angle in degrees.","Returns: The angle in radians."],"examples":[{"code":"local r = math.rad(90)","lang":"lua"}]},{"group":"lua","heading":"math.random","syntax":["math.random(m, n) → number"],"text":["A random number: math.random() a fraction from 0 up to 1, math.random(n) a whole number 1 … n, math.random(m, n) a whole number m … n.","Parameters:","- m (number?): The lowest whole number, or the highest when it is the only argument.","- n (number?): The highest whole number.","Returns: The random number."],"examples":[{"code":"local socials = { \"smile\", \"nod\", \"wave\" }\nsend(socials[math.random(#socials)])","lang":"lua"}]},{"group":"lua","heading":"math.randomseed","syntax":["math.randomseed(x, y)"],"text":["Starts the random numbers from a seed, so a sequence can be repeated. Without arguments it picks a random seed (already done at start).","Parameters:","- x (number?): The seed.","- y (number?): A second part of the seed."],"examples":[{"code":"math.randomseed(42)","lang":"lua"}]},{"group":"lua","heading":"math.sin","syntax":["math.sin(x) → number"],"text":["The sine of an angle in radians.","Parameters:","- x (number): An angle in radians.","Returns: The sine."],"examples":[{"code":"local s = math.sin(math.pi / 2)","lang":"lua"}]},{"group":"lua","heading":"math.sqrt","syntax":["math.sqrt(x) → number"],"text":["The square root of x.","Parameters:","- x (number): A number.","Returns: The square root."],"examples":[{"code":"local dist = math.sqrt(dx * dx + dy * dy)","lang":"lua"}]},{"group":"lua","heading":"math.tan","syntax":["math.tan(x) → number"],"text":["The tangent of an angle in radians.","Parameters:","- x (number): An angle in radians.","Returns: The tangent."],"examples":[{"code":"local t = math.tan(math.pi / 4)","lang":"lua"}]},{"group":"lua","heading":"math.tointeger","syntax":["math.tointeger(x) → integer"],"text":["x as a whole number when it is one (3.0 → 3); nil otherwise.","Parameters:","- x (any): A number, or a string that holds one.","Returns: The integer, or nil."],"examples":[{"code":"local n = math.tointeger(3.0) -- 3","lang":"lua"}]},{"group":"lua","heading":"math.type","syntax":["math.type(x) → string"],"text":["\"integer\" for a whole number, \"float\" for a number with a fraction, nil for anything else.","Parameters:","- x (any): Any value.","Returns: \"integer\", \"float\" or nil."],"examples":[{"code":"if math.type(n) == \"integer\" then echo(\"whole\") end","lang":"lua"}]},{"group":"lua","heading":"math.ult","syntax":["math.ult(m, n) → boolean"],"text":["Whether m < n when both are read as unsigned integers. Rarely needed.","Parameters:","- m (number): An integer.","- n (number): An integer.","Returns: true or false."],"examples":[{"code":"local less = math.ult(1, -1) -- true","lang":"lua"}]},{"group":"lua","heading":"utf8.char","syntax":["utf8.char(...) → string"],"text":["A string from character codes (code points).","Parameters:","- ... (number): Code points, such as 229 for å.","Returns: The UTF-8 string."],"examples":[{"code":"local heart = utf8.char(9829) -- ♥","lang":"lua"}]},{"group":"lua","heading":"utf8.charpattern","syntax":["utf8.charpattern"],"text":["A pattern that matches one UTF-8 character; use it with gmatch to walk the characters of a string."],"examples":[{"code":"for ch in (\"Hjälp\"):gmatch(utf8.charpattern) do\n  print(ch)\nend","lang":"lua"}]},{"group":"lua","heading":"utf8.codepoint","syntax":["utf8.codepoint(s, i, j) → codes…"],"text":["The code points of the characters that start between byte positions i and j.","Parameters:","- s (string): Text in UTF-8, as the game sends it.","- i (number?): The first byte position (default 1).","- j (number?): The last byte position (default i).","Returns: One number per character."],"examples":[{"code":"local code = utf8.codepoint(\"å\") -- 229","lang":"lua"}]},{"group":"lua","heading":"utf8.codes","syntax":["utf8.codes(s) → iterator"],"text":["Walks the characters of s: each step gives the byte position and the code point.","Parameters:","- s (string): Text in UTF-8, as the game sends it.","Returns: An iterator for a generic for."],"examples":[{"code":"for pos, code in utf8.codes(\"Hjälp\") do\n  print(pos, utf8.char(code))\nend","lang":"lua"}]},{"group":"lua","heading":"utf8.len","syntax":["utf8.len(s, i, j) → number"],"text":["The number of characters in s (from byte i to j); nil and a position when s is not valid UTF-8.","Parameters:","- s (string): Text in UTF-8, as the game sends it.","- i (number?): The first byte position (default 1).","- j (number?): The last byte position (default -1).","Returns: The number of characters, or nil and the position of the first bad byte."],"examples":[{"code":"local width = utf8.len(name) or #name","lang":"lua"}]},{"group":"lua","heading":"utf8.offset","syntax":["utf8.offset(s, n, i) → number"],"text":["The byte position where the n-th character starts (counting from byte i).","Parameters:","- s (string): Text in UTF-8, as the game sends it.","- n (number): Which character (negative counts from the end).","- i (number?): Where to count from.","Returns: The byte position, or nil."],"examples":[{"code":"local cut = utf8.offset(name, 4)\nlocal first3 = cut and name:sub(1, cut - 1) or name","lang":"lua"}]},{"group":"lua","heading":"coroutine.close","syntax":["coroutine.close(co) → ok, err"],"text":["Ends a suspended or dead coroutine.","Parameters:","- co (thread): A coroutine, from coroutine.create.","Returns: true, or false and the error the coroutine died with."],"examples":[{"code":"coroutine.close(co)","lang":"lua"}]},{"group":"lua","heading":"coroutine.create","syntax":["coroutine.create(f) → co"],"text":["Makes a coroutine from a function; it starts when you first resume it.","Parameters:","- f (function): The body of the coroutine.","Returns: The coroutine."],"examples":[{"code":"local co = coroutine.create(function(a)\n  local b = coroutine.yield(a + 1)\n  return b * 2\nend)","lang":"lua"}]},{"group":"lua","heading":"coroutine.isyieldable","syntax":["coroutine.isyieldable() → boolean"],"text":["Whether the running code may call coroutine.yield.","Returns: true inside a coroutine."],"examples":[{"code":"if coroutine.isyieldable() then coroutine.yield() end","lang":"lua"}]},{"group":"lua","heading":"coroutine.resume","syntax":["coroutine.resume(co, ...) → ok, …"],"text":["Starts or continues a coroutine; the arguments go to its function or come back from its yield.","Parameters:","- co (thread): A coroutine, from coroutine.create.","- ... (any): Values passed in.","Returns: true and the values it yielded or returned, or false and an error."],"examples":[{"code":"local ok, v = coroutine.resume(co, 1)","lang":"lua"}]},{"group":"lua","heading":"coroutine.running","syntax":["coroutine.running() → co, ismain"],"text":["The running coroutine, and true when it is the main one.","Returns: The coroutine and a boolean."],"examples":[{"code":"local co, main = coroutine.running()","lang":"lua"}]},{"group":"lua","heading":"coroutine.status","syntax":["coroutine.status(co) → string"],"text":["The state of a coroutine: \"running\", \"suspended\", \"normal\" or \"dead\".","Parameters:","- co (thread): A coroutine, from coroutine.create.","Returns: The state."],"examples":[{"code":"if coroutine.status(co) == \"dead\" then co = nil end","lang":"lua"}]},{"group":"lua","heading":"coroutine.wrap","syntax":["coroutine.wrap(f) → function"],"text":["Makes a coroutine and returns a function that resumes it; errors pass through.","Parameters:","- f (function): The body of the coroutine.","Returns: A function that resumes it."],"examples":[{"code":"local nextDir = coroutine.wrap(function()\n  for _, d in ipairs({ \"n\", \"e\", \"s\", \"w\" }) do coroutine.yield(d) end\nend)\nsend(nextDir())","lang":"lua"}]},{"group":"lua","heading":"coroutine.yield","syntax":["coroutine.yield(...) → …"],"text":["Pauses the running coroutine; its values go to the resume that started it.","Parameters:","- ... (any): Values passed out.","Returns: The values passed to the next resume."],"examples":[{"code":"coroutine.yield(step)","lang":"lua"}]}],"menu":[{"kind":"group","label":"Guide","section":-1},{"kind":"entry","label":"Getting started","section":0},{"kind":"entry","label":"Lua basics","section":1},{"kind":"entry","label":"Lua patterns","section":2},{"kind":"entry","label":"The header","section":3},{"kind":"entry","label":"Triggers","section":4},{"kind":"entry","label":"Aliases","section":5},{"kind":"entry","label":"Keys","section":6},{"kind":"entry","label":"Timers","section":7},{"kind":"entry","label":"Game time","section":8},{"kind":"entry","label":"Events and GMCP","section":9},{"kind":"entry","label":"Output","section":10},{"kind":"entry","label":"Panes","section":11},{"kind":"entry","label":"Map marks","section":12},{"kind":"entry","label":"Settings and store","section":13},{"kind":"entry","label":"Profile bridge","section":14},{"kind":"entry","label":"In-game commands","section":15},{"kind":"entry","label":"Sandbox and limits","section":16},{"kind":"entry","label":"Errors and debugging","section":17},{"kind":"entry","label":"Examples","section":18},{"kind":"blank","label":"","section":-1},{"kind":"group","label":"API reference","section":-1},{"kind":"entry","label":"cecho","section":19},{"kind":"entry","label":"command","section":20},{"kind":"entry","label":"copy2cecho","section":21},{"kind":"entry","label":"createPane","section":22},{"kind":"entry","label":"deleteLine","section":23},{"kind":"entry","label":"echo","section":24},{"kind":"entry","label":"expandAlias","section":25},{"kind":"entry","label":"export","section":26},{"kind":"entry","label":"field:focus","section":27},{"kind":"entry","label":"field:remove","section":28},{"kind":"entry","label":"field:select","section":29},{"kind":"entry","label":"field:setValue","section":30},{"kind":"entry","label":"field:value","section":31},{"kind":"entry","label":"gameTime","section":32},{"kind":"entry","label":"gameTimeFind","section":33},{"kind":"entry","label":"getEpoch","section":34},{"kind":"entry","label":"getPanes","section":35},{"kind":"entry","label":"getVariable","section":36},{"kind":"entry","label":"gmcp","section":37},{"kind":"entry","label":"highlight","section":38},{"kind":"entry","label":"isPrompt","section":39},{"kind":"entry","label":"killAlias","section":40},{"kind":"entry","label":"killAnonymousEventHandler","section":41},{"kind":"entry","label":"killKey","section":42},{"kind":"entry","label":"killTimer","section":43},{"kind":"entry","label":"killTrigger","section":44},{"kind":"entry","label":"line","section":45},{"kind":"entry","label":"lineTags","section":46},{"kind":"entry","label":"localTime","section":47},{"kind":"entry","label":"mapFind","section":48},{"kind":"entry","label":"mapMark","section":49},{"kind":"entry","label":"mapPath","section":50},{"kind":"entry","label":"mapRoom","section":51},{"kind":"entry","label":"mapSearch","section":52},{"kind":"entry","label":"mapUnmark","section":53},{"kind":"entry","label":"matches","section":54},{"kind":"entry","label":"pane:cecho","section":55},{"kind":"entry","label":"pane:cechoLink","section":56},{"kind":"entry","label":"pane:clear","section":57},{"kind":"entry","label":"pane:close","section":58},{"kind":"entry","label":"pane:dock","section":59},{"kind":"entry","label":"pane:echo","section":60},{"kind":"entry","label":"pane:fillColor","section":61},{"kind":"entry","label":"pane:gauge","section":62},{"kind":"entry","label":"pane:hide","section":63},{"kind":"entry","label":"pane:onClose","section":64},{"kind":"entry","label":"pane:onResize","section":65},{"kind":"entry","label":"pane:onTheme","section":66},{"kind":"entry","label":"pane:onWheel","section":67},{"kind":"entry","label":"pane:setCheckbox","section":68},{"kind":"entry","label":"pane:setGrip","section":69},{"kind":"entry","label":"pane:setHover","section":70},{"kind":"entry","label":"pane:setInput","section":71},{"kind":"entry","label":"pane:setLine","section":72},{"kind":"entry","label":"pane:setLink","section":73},{"kind":"entry","label":"pane:setRadio","section":74},{"kind":"entry","label":"pane:setText","section":75},{"kind":"entry","label":"pane:setTitle","section":76},{"kind":"entry","label":"pane:show","section":77},{"kind":"entry","label":"pane:size","section":78},{"kind":"entry","label":"pane:theme","section":79},{"kind":"entry","label":"pane:visible","section":80},{"kind":"entry","label":"pane:wantSize","section":81},{"kind":"entry","label":"print","section":82},{"kind":"entry","label":"registerAnonymousEventHandler","section":83},{"kind":"entry","label":"replaceLine","section":84},{"kind":"entry","label":"scriptName","section":85},{"kind":"entry","label":"send","section":86},{"kind":"entry","label":"setPaneOn","section":87},{"kind":"entry","label":"setSetting","section":88},{"kind":"entry","label":"settings","section":89},{"kind":"entry","label":"setVariable","section":90},{"kind":"entry","label":"state","section":91},{"kind":"entry","label":"store","section":92},{"kind":"entry","label":"store.get","section":93},{"kind":"entry","label":"store.set","section":94},{"kind":"entry","label":"tempAlias","section":95},{"kind":"entry","label":"tempKey","section":96},{"kind":"entry","label":"tempRegexTrigger","section":97},{"kind":"entry","label":"tempTimer","section":98},{"kind":"entry","label":"tempTrigger","section":99},{"kind":"entry","label":"toggle:checked","section":100},{"kind":"entry","label":"toggle:remove","section":101},{"kind":"entry","label":"toggle:set","section":102},{"kind":"entry","label":"uiMessage","section":103},{"kind":"entry","label":"wrapText","section":104},{"kind":"blank","label":"","section":-1},{"kind":"group","label":"Lua reference","section":-1},{"kind":"entry","label":"Lua library","section":105},{"kind":"entry","label":"assert","section":106},{"kind":"entry","label":"error","section":107},{"kind":"entry","label":"getmetatable","section":108},{"kind":"entry","label":"ipairs","section":109},{"kind":"entry","label":"next","section":110},{"kind":"entry","label":"pairs","section":111},{"kind":"entry","label":"pcall","section":112},{"kind":"entry","label":"rawequal","section":113},{"kind":"entry","label":"rawget","section":114},{"kind":"entry","label":"rawlen","section":115},{"kind":"entry","label":"rawset","section":116},{"kind":"entry","label":"select","section":117},{"kind":"entry","label":"setmetatable","section":118},{"kind":"entry","label":"tonumber","section":119},{"kind":"entry","label":"tostring","section":120},{"kind":"entry","label":"type","section":121},{"kind":"entry","label":"xpcall","section":122},{"kind":"entry","label":"_VERSION","section":123},{"kind":"entry","label":"string.byte","section":124},{"kind":"entry","label":"string.char","section":125},{"kind":"entry","label":"string.find","section":126},{"kind":"entry","label":"string.format","section":127},{"kind":"entry","label":"string.gmatch","section":128},{"kind":"entry","label":"string.gsub","section":129},{"kind":"entry","label":"string.len","section":130},{"kind":"entry","label":"string.lower","section":131},{"kind":"entry","label":"string.match","section":132},{"kind":"entry","label":"string.pack","section":133},{"kind":"entry","label":"string.packsize","section":134},{"kind":"entry","label":"string.rep","section":135},{"kind":"entry","label":"string.reverse","section":136},{"kind":"entry","label":"string.sub","section":137},{"kind":"entry","label":"string.unpack","section":138},{"kind":"entry","label":"string.upper","section":139},{"kind":"entry","label":"table.concat","section":140},{"kind":"entry","label":"table.insert","section":141},{"kind":"entry","label":"table.move","section":142},{"kind":"entry","label":"table.pack","section":143},{"kind":"entry","label":"table.remove","section":144},{"kind":"entry","label":"table.sort","section":145},{"kind":"entry","label":"table.unpack","section":146},{"kind":"entry","label":"math.abs","section":147},{"kind":"entry","label":"math.acos","section":148},{"kind":"entry","label":"math.asin","section":149},{"kind":"entry","label":"math.atan","section":150},{"kind":"entry","label":"math.ceil","section":151},{"kind":"entry","label":"math.cos","section":152},{"kind":"entry","label":"math.deg","section":153},{"kind":"entry","label":"math.exp","section":154},{"kind":"entry","label":"math.floor","section":155},{"kind":"entry","label":"math.fmod","section":156},{"kind":"entry","label":"math.huge","section":157},{"kind":"entry","label":"math.log","section":158},{"kind":"entry","label":"math.max","section":159},{"kind":"entry","label":"math.maxinteger","section":160},{"kind":"entry","label":"math.min","section":161},{"kind":"entry","label":"math.mininteger","section":162},{"kind":"entry","label":"math.modf","section":163},{"kind":"entry","label":"math.pi","section":164},{"kind":"entry","label":"math.rad","section":165},{"kind":"entry","label":"math.random","section":166},{"kind":"entry","label":"math.randomseed","section":167},{"kind":"entry","label":"math.sin","section":168},{"kind":"entry","label":"math.sqrt","section":169},{"kind":"entry","label":"math.tan","section":170},{"kind":"entry","label":"math.tointeger","section":171},{"kind":"entry","label":"math.type","section":172},{"kind":"entry","label":"math.ult","section":173},{"kind":"entry","label":"utf8.char","section":174},{"kind":"entry","label":"utf8.charpattern","section":175},{"kind":"entry","label":"utf8.codepoint","section":176},{"kind":"entry","label":"utf8.codes","section":177},{"kind":"entry","label":"utf8.len","section":178},{"kind":"entry","label":"utf8.offset","section":179},{"kind":"entry","label":"coroutine.close","section":180},{"kind":"entry","label":"coroutine.create","section":181},{"kind":"entry","label":"coroutine.isyieldable","section":182},{"kind":"entry","label":"coroutine.resume","section":183},{"kind":"entry","label":"coroutine.running","section":184},{"kind":"entry","label":"coroutine.status","section":185},{"kind":"entry","label":"coroutine.wrap","section":186},{"kind":"entry","label":"coroutine.yield","section":187}],"api":{"tempTrigger":{"kind":"function","sig":"tempTrigger(substring, fn) → id","doc":"Calls fn for every game line that contains substring. In fn, line is the line and matches[1] the match.","params":[{"name":"substring","type":"string","doc":"Text to look for anywhere in the line, literally and case-sensitively. Not empty."},{"name":"fn","type":"function","doc":"Called with no arguments for each matching line; read line and matches."}],"returns":"An id (a number) for the matching kill function.","example":"tempTrigger(\"You are hungry.\", function()\n  send(\"eat bread\")\nend)"},"tempRegexTrigger":{"kind":"function","sig":"tempRegexTrigger(regex, fn) → id","doc":"Calls fn for every game line the regular expression (JavaScript syntax) matches. matches[1] is the whole match, matches[2] … the groups.","params":[{"name":"regex","type":"string","doc":"A JavaScript regular expression, case-sensitive. Use ^ and $ to match the whole line."},{"name":"fn","type":"function","doc":"Called with no arguments for each matching line; read line and matches."}],"returns":"An id (a number) for the matching kill function.","example":"tempRegexTrigger(\"^(\\\\w+) tells you '(.*)'$\", function()\n  uiMessage(\"tell\", matches[2] .. \": \" .. matches[3])\nend)"},"tempAlias":{"kind":"function","sig":"tempAlias(regex, fn) → id","doc":"Calls fn for a typed command the regular expression matches (not anchored: use ^ and $). The command is consumed unless fn returns false.","params":[{"name":"regex","type":"string","doc":"A JavaScript regular expression matched against the typed command."},{"name":"fn","type":"function","doc":"Called with no arguments; read matches and command. Return false to let the command go on."}],"returns":"An id (a number) for the matching kill function.","example":"tempAlias(\"^k (\\\\w+)$\", function()\n  send(\"kill \" .. matches[2])\nend)"},"killTrigger":{"kind":"function","sig":"killTrigger(id)","doc":"Removes a trigger made with tempTrigger or tempRegexTrigger.","params":[{"name":"id","type":"number","doc":"The id tempTrigger or tempRegexTrigger returned."}],"returns":"true when it was removed, false when the id is not one of this script's (or it is already gone).","example":"local id\nid = tempTrigger(\"You are hungry.\", function()\n  send(\"eat bread\")\n  killTrigger(id) -- only the first time\nend)"},"killAlias":{"kind":"function","sig":"killAlias(id)","doc":"Removes an alias made with tempAlias.","params":[{"name":"id","type":"number","doc":"The id tempAlias returned."}],"returns":"true when it was removed, false when the id is not one of this script's (or it is already gone).","example":"local id = tempAlias(\"^hi$\", function()\n  send(\"say Hello!\")\nend)\ntempAlias(\"^nohi$\", function()\n  killAlias(id)\nend)"},"deleteLine":{"kind":"function","sig":"deleteLine()","doc":"In a trigger: hides the current line (a gag).","params":[],"example":"tempTrigger(\"You can't find any coins\", function()\n  deleteLine()\nend)"},"isPrompt":{"kind":"function","sig":"isPrompt() → boolean","doc":"In a trigger: true when the line is a prompt (MUME ended it with GA/EOR, or it is a <prompt> element in XML mode).","params":[],"returns":"true or false; false outside a trigger.","example":"tempRegexTrigger(\"^$\", function()\n  if isPrompt() then return end\nend)"},"lineTags":{"kind":"function","sig":"lineTags() → table","doc":"In a trigger: the MUME XML elements the line is in, such as room, description, exits, say or tell, each name once.","params":[],"returns":"A list of element names, outermost first; empty without XML or outside a trigger.","example":"tempRegexTrigger(\" leaves north\\\\.$\", function()\n  for _, t in ipairs(lineTags()) do\n    if t == \"description\" or t == \"say\" then return end\n  end\n  highlight(\"~gold\")\nend)"},"copy2cecho":{"kind":"function","sig":"copy2cecho() → string","doc":"In a trigger: the current line as the game sent it, with its colours as cecho tags, so it can be shown elsewhere (a pane) in the same colours.","params":[],"returns":"The line with <ansi_N>, <#rrggbb>, <fg:bg>, <b>, <i>, <u> and <reset> tags (an adaptive colour as <~#rrggbb>), or nil outside a trigger.","example":"tempRegexTrigger(\"^\\\\[home\\\\] \", function()\n  tv:cecho(copy2cecho() .. \"\\n\")\n  deleteLine()\nend)"},"replaceLine":{"kind":"function","sig":"replaceLine(text)","doc":"In a trigger: shows text instead of the current line. cecho colour tags work.","params":[{"name":"text","type":"string","doc":"The new text; cecho colour tags work. A line break becomes a space."}],"example":"tempTrigger(\"You are thirsty.\", function()\n  replaceLine(\"<yellow>*** THIRSTY ***<reset>\")\nend)"},"highlight":{"kind":"function","sig":"highlight(color[, text])","doc":"In a trigger: colours the whole line, or each occurrence of text. color is a profile colour such as \"light red\" or \"bold yellow\", or a Mudlet name such as \"orange\".","params":[{"name":"color","type":"string","doc":"A profile colour (\"red\", \"light red\", \"bold yellow\", \"<F88ff00>\"), cecho tags (\"<b><orange>\"), a Mudlet name (\"orange\", \"white:red\"), \"r,g,b\" or \"#rrggbb\". A ~ before a name, \"#rrggbb\" or \"r,g,b\" makes it adaptive (\"~gold\"): it keeps its hue and is made lighter or darker to read on the current background."},{"name":"text","type":"string?","doc":"Colour only this text, each time it occurs in the line. Without it the whole line."}],"example":"tempRegexTrigger(\"^(\\\\w+) tells you\", function()\n  highlight(\"light yellow\")\n  highlight(\"bold white\", matches[2])\nend)"},"tempKey":{"kind":"function","sig":"tempKey(name, fn) → id","doc":"Calls fn when the key is pressed. Names as in the profile: \"F5\", \"Alt+a\", \"Numpad0\".","params":[{"name":"name","type":"string","doc":"A key name as in the profile's #macro: \"F5\", \"Numpad 0\", \"Alt+a\", \"Ctrl+Shift+F1\"."},{"name":"fn","type":"function","doc":"Called with no arguments when the key is pressed."}],"returns":"An id (a number) for the matching kill function.","example":"tempKey(\"F5\", function()\n  send(\"flee\")\nend)"},"killKey":{"kind":"function","sig":"killKey(id)","doc":"Removes a key binding made with tempKey.","params":[{"name":"id","type":"number","doc":"The id tempKey returned."}],"returns":"true when it was removed, false when the id is not one of this script's (or it is already gone).","example":"local key = tempKey(\"Numpad5\", function()\n  send(\"look\")\nend)\nkillKey(key)"},"tempTimer":{"kind":"function","sig":"tempTimer(seconds, fn[, repeat]) → id","doc":"Calls fn after seconds; again every seconds when repeat is true (50 ms at least).","params":[{"name":"seconds","type":"number","doc":"Seconds to wait, 0 or more; fractions work (0.5)."},{"name":"fn","type":"function","doc":"Called with no arguments when the time is up."},{"name":"repeat","type":"boolean?","doc":"true: call fn again every seconds (at least 0.05) until killTimer. Default: once."}],"returns":"An id (a number) for the matching kill function.","example":"tempTimer(2.5, function()\n  send(\"stand\")\nend)"},"killTimer":{"kind":"function","sig":"killTimer(id)","doc":"Stops a timer made with tempTimer.","params":[{"name":"id","type":"number","doc":"The id tempTimer returned."}],"returns":"true when it was removed, false when the id is not one of this script's (or it is already gone). A one-shot timer that has fired is gone.","example":"local t = tempTimer(60, function()\n  echo(\"Another minute.\")\nend, true)\ntempAlias(\"^stopclock$\", function()\n  killTimer(t)\nend)"},"getEpoch":{"kind":"function","sig":"getEpoch() → seconds","doc":"The time now, in seconds since 1970 (with milliseconds as the fraction), as Mudlet's getEpoch. Use it for times that must outlast a reload, kept with store.set.","params":[],"returns":"Seconds since 1 January 1970 UTC, a number with a fraction.","example":"local ends = getEpoch() + 25 * 60\nstore.set(\"ends\", ends)\nlocal left = math.floor(ends - getEpoch())"},"gameTime":{"kind":"function","sig":"gameTime([epoch]) → table","doc":"The game date, time, season, period of the day and moon now, or at any real time (seconds since 1970, past or future). nil while the clock does not know the day.","params":[{"name":"epoch","type":"number?","doc":"A real time, as getEpoch() gives; default now."}],"returns":"A table: year, month (1–12), monthName, sindarin, day (1–30), hour, minute, weekday, season (winter, spring, summer, autumn), period (dawn, day, dusk, night; the sun is up from the dawn hour through the dusk hour: only night is dark), dawn and dusk (the month's hours), precision (day, hour, minute), epoch, and moon = {phase, level (0 new … 12 full), waxing, visible, bright, position (east, southeast, south, southwest, west, below)}. nil while the clock is unset.","example":"local g = gameTime()\nif g then\n  echo(g.hour .. \":\" .. string.format(\"%02d\", g.minute) .. \" \" .. g.monthName .. \", \" .. g.season .. \", \" .. g.moon.phase .. \" moon\")\nend"},"gameTimeFind":{"kind":"function","sig":"gameTimeFind(cond[, from[, horizon]]) → start, end","doc":"The next window of real time (seconds since 1970) in which every key of cond holds, or nil when none starts within the horizon or the clock is unset.","params":[{"name":"cond","type":"table","doc":"Any of: season or notSeason (\"winter\" or a list), month (1–12, a name or a list), hours = {from = 22, to = 2} (to not included), period (\"dawn\", \"day\", \"dusk\", \"night\" or a list), moon (a phase name or a list), moonVisible (true or false), at (\"dawn\", \"dusk\", \"midnight\", \"moonrise\", \"moonset\", \"seasonStart\")."},{"name":"from","type":"number?","doc":"Where to start looking, as getEpoch(); default now."},{"name":"horizon","type":"number?","doc":"How far to look, in real seconds; default one game year (6 real days), at most 30 days."}],"returns":"start and end in seconds since 1970. When cond already holds at from, start is from. With at, the window is that moment (start equals end): the first such moment at which the other keys hold. nil when there is none.","example":"local s = gameTimeFind({at = \"moonrise\", moon = {\"waxing gibbous\", \"full\"}})\nif s then\n  echo(\"Dead Knight moonrise in \" .. math.floor((s - getEpoch()) / 60) .. \" min\")\nend"},"localTime":{"kind":"function","sig":"localTime([epoch]) → table","doc":"The browser's local date and time of a real time, like Lua's os.date(\"*t\"), which the sandbox does not have.","params":[{"name":"epoch","type":"number?","doc":"Seconds since 1970; default now."}],"returns":"A table: year, month (1–12), day, hour, min, sec, wday (1 = Sunday), yday (1 = 1 January).","example":"local s = gameTimeFind({season = \"winter\"})\nif s then\n  local t = localTime(s)\n  echo(string.format(\"Winter starts %d-%02d-%02d %02d:%02d\", t.year, t.month, t.day, t.hour, t.min))\nend"},"registerAnonymousEventHandler":{"kind":"function","sig":"registerAnonymousEventHandler(event, fn) → id","doc":"Calls fn(event, …) for an event: \"gmcp.Char.Vitals\", \"sysLoadEvent\", \"sysSettingChanged\", \"sysConnectionEvent\", \"sysDisconnectionEvent\", \"sysPanesChanged\", \"sysGameTimeEvent\" or a #event name such as \"SESSION CONNECTED\".","params":[{"name":"event","type":"string","doc":"The event name; case does not matter. Any name is accepted, but only the events in the Events and GMCP section fire."},{"name":"fn","type":"function","doc":"Called with the event name, then the event's arguments."}],"returns":"An id (a number) for the matching kill function.","example":"registerAnonymousEventHandler(\"gmcp.Char.Vitals\", function(event)\n  local hp = gmcp.Char.Vitals.hp\n  if hp and hp < 50 then cecho(\"<red>Low HP!<reset>\") end\nend)"},"killAnonymousEventHandler":{"kind":"function","sig":"killAnonymousEventHandler(id)","doc":"Removes an event handler.","params":[{"name":"id","type":"number","doc":"The id registerAnonymousEventHandler returned."}],"returns":"true when it was removed, false when the id is not one of this script's (or it is already gone).","example":"local h\nh = registerAnonymousEventHandler(\"gmcp.Char.Name\", function()\n  echo(\"Welcome, \" .. gmcp.Char.Name.name)\n  killAnonymousEventHandler(h)\nend)"},"send":{"kind":"function","sig":"send(cmd)","doc":"Sends cmd to the game as it is, without aliases.","params":[{"name":"cmd","type":"string","doc":"One command. ; and # are not special here."}],"example":"send(\"kill orc\")"},"expandAlias":{"kind":"function","sig":"expandAlias(cmd)","doc":"Runs cmd as if typed: profile and script aliases, ; and # commands.","params":[{"name":"cmd","type":"string","doc":"The text to run, like a line typed on the input line."}],"example":"expandAlias(\"stand;flee\")"},"echo":{"kind":"function","sig":"echo(text)","doc":"Writes plain text to the game output. Triggers do not see it.","params":[{"name":"text","type":"string","doc":"The text; each line break starts a new line."}],"example":"echo(\"Looting is off.\")"},"cecho":{"kind":"function","sig":"cecho(text)","doc":"Writes coloured text: <red>, <white:blue>, <#ff8000>, <~gold> (adaptive), <b>bold</b>, <reset> and tt++ <F88ff00> / <118> codes.","params":[{"name":"text","type":"string","doc":"Text with colour tags in angle brackets; see the Output section for the list."}],"example":"cecho(\"<green>Ready.<reset> Type <yellow>cl<reset> to loot.\")"},"print":{"kind":"function","sig":"print(...)","doc":"Writes its arguments to the game output, separated by tabs.","params":[{"name":"...","type":"any","doc":"Values to show. Strings and numbers as text, booleans as true/false, others by type name (nil, table)."}],"example":"print(\"kills:\", store.get(\"kills\"))"},"uiMessage":{"kind":"function","sig":"uiMessage(source, text)","doc":"Writes a line to the UI messages pane: ▶ SOURCE: text.","params":[{"name":"source","type":"string","doc":"A short label, shown in capitals (at most 20 characters; empty gives SCRIPT)."},{"name":"text","type":"string","doc":"The message."}],"example":"uiMessage(\"loot\", \"Picked up the coins.\")"},"getVariable":{"kind":"function","sig":"getVariable(name) → value","doc":"Reads a tt++ variable of the profile ($name). nil when unset.","params":[{"name":"name","type":"string","doc":"The variable name without $."}],"returns":"The value as a string (use tonumber for numbers), or nil when the variable is not set.","example":"local target = getVariable(\"target\")\nif target then send(\"kill \" .. target) end"},"setVariable":{"kind":"function","sig":"setVariable(name, value)","doc":"Sets a tt++ variable of the profile, as #variable does.","params":[{"name":"name","type":"string","doc":"The variable name without $. Not empty."},{"name":"value","type":"any","doc":"A string, number or boolean; stored as text."}],"example":"tempAlias(\"^t (\\\\w+)$\", function()\n  setVariable(\"target\", matches[2])\nend)"},"export":{"kind":"function","sig":"export(name, fn)","doc":"Makes fn callable from the profile: #lua {script} {name} {args}.","params":[{"name":"name","type":"string","doc":"The name #lua uses; no spaces. Exporting the same name again replaces it."},{"name":"fn","type":"function","doc":"Called with the rest of the #lua line as one string, or with no argument when there is none."}],"example":"export(\"heal\", function(who)\n  send(\"cast 'cure light' \" .. (who or \"me\"))\nend)\n-- In the profile: #lua {healer} {heal} {Rasta}"},"store":{"kind":"table","sig":"store","doc":"Data this script keeps between sessions: store.get(key) and store.set(key, value).","example":"local n = (store.get(\"deaths\") or 0) + 1\nstore.set(\"deaths\", n)"},"store.get":{"kind":"function","sig":"store.get(key) → value","doc":"A value saved with store.set, or nil.","params":[{"name":"key","type":"string","doc":"The key it was saved under."}],"returns":"A copy of the saved value, or nil. Changing a table you got does not change the store until you store.set it again.","example":"local kills = store.get(\"kills\") or 0"},"store.set":{"kind":"function","sig":"store.set(key, value)","doc":"Saves a string, number, boolean or table under key. nil removes it.","params":[{"name":"key","type":"string","doc":"The key."},{"name":"value","type":"any","doc":"A string, number, boolean or a table of them (copied); nil removes the key. Functions are not kept."}],"example":"store.set(\"kills\", 12)\nstore.set(\"friends\", { \"Rasta\", \"Ithilwen\" })"},"mapMark":{"kind":"function","sig":"mapMark(target, opts, fn) → handle","doc":"Marks rooms on the Map pane for a while: they blink in a colour, with arrows when they are off the view. target is a list of room ids or a query by a room's text, {name = …, lines = {…}, exits = \"Exits: …\", max = 20}.","params":[{"name":"target","type":"table","doc":"Room ids (from mapFind or mapSearch; at most 200), or {name, lines, exits, max}: the room's name as shown, the lines after it (they narrow by the description), its Exits: line, and the most rooms (default 20, at most 50; nearest to you first)."},{"name":"opts","type":"table?","doc":"color (a colour name, #rrggbb or r,g,b; default magenta), duration (seconds, default 30, at most 600; 0: until mapUnmark or the script stops, blinking all the while), fade (seconds of fading at the end, default 10), blink and arrows (default true), label (a short text at the first room), linger (seconds the mark then stays, steady and a little dimmer, with its arrows and label; default 0, at most 600), focus (true: zoom out to show you and the rooms; the view comes back when the duration is over (before any linger), unless you moved it. \"move\": zoom out once; at your first move to another room the zoom comes back and the map follows you, the mark stays)."},{"name":"fn","type":"function?","doc":"Called once with (count, total, ids): how many rooms were marked, how many matched, and their ids. count is 0 when nothing matched."}],"returns":"A handle for mapUnmark, or nil and why (\"map off\" when the Map pane is off or has no map).","example":"local h, why = mapMark({name = \"The Prancing Pony\"}, {color = \"orange\", duration = 15, focus = true},\n  function(count, total) echo(count .. \" of \" .. total .. \" marked\") end)\nif not h then echo(\"No mark: \" .. why) end"},"mapUnmark":{"kind":"function","sig":"mapUnmark(handle) → boolean","doc":"Takes a mark from mapMark away before its time is up.","params":[{"name":"handle","type":"number","doc":"What mapMark returned."}],"returns":"true when the mark was still there.","example":"mapUnmark(h)"},"mapFind":{"kind":"function","sig":"mapFind(query, fn)","doc":"Finds map rooms by a room's text, nearest to you first, and calls fn(ids, total).","params":[{"name":"query","type":"table","doc":"{name, lines, exits, max}, as mapMark's query."},{"name":"fn","type":"function","doc":"Called once with the room ids (a list) and how many matched."}],"returns":"true, or nil and why (\"map off\").","example":"mapFind({name = \"Bree Market Square\"}, function(ids, total)\n  echo(total .. \" rooms; marking the nearest\")\n  if ids[1] then mapMark({ids[1]}, {duration = 10}) end\nend)"},"mapSearch":{"kind":"function","sig":"mapSearch(query, fn)","doc":"Searches the map like MMapper's Find Rooms and calls fn(results, total, here): the matching rooms, nearest first by the shortest path from your room, with the way there as text.","params":[{"name":"query","type":"table","doc":"{text, field, case, regex, max}: text to find anywhere in the field; field \"name\" (default), \"desc\", \"contents\", \"note\", \"area\", \"exits\" (door names), \"flags\" (aggmob, herb, door, climb … or in words, aggressive mob) or \"all\"; case = true makes case count; regex = true takes text as a regular expression; max, the most results (default 200, at most 500)."},{"name":"fn","type":"function","doc":"Called once with results (a list of {id, name, area, note, steps, dirs}; steps and dirs nil without a path or when your room is unknown), total (every match) and here (your room's id, or nil)."}],"returns":"true, or nil and why (\"map off\", or \"bad regex: …\" for a regular expression that does not compile).","example":"mapSearch({text = \"herb\", field = \"note\", max = 5}, function(results, total)\n  for _, r in ipairs(results) do echo(r.name .. \": \" .. (r.dirs or \"no path\") .. \"\\n\") end\nend)"},"mapPath":{"kind":"function","sig":"mapPath(id, fn)","doc":"The shortest way from your room to a room: fn(dirs, steps), or fn(nil) when there is none (or your room is unknown).","params":[{"name":"id","type":"number","doc":"A room id (from mapSearch or mapFind)."},{"name":"fn","type":"function","doc":"Called once with the direction text (3e n 2u) and the number of moves."}],"returns":"true, or nil and why (\"map off\").","example":"mapPath(id, function(dirs, steps) echo(dirs and (steps .. \" moves: \" .. dirs) or \"No way there.\") end)"},"mapRoom":{"kind":"function","sig":"mapRoom(id, fn)","doc":"A map room's details: fn(room), or fn(nil) for no such room.","params":[{"name":"id","type":"number","doc":"A room id (from mapSearch or mapFind)."},{"name":"fn","type":"function","doc":"Called once with {id, name, area, desc, contents, note, terrain, x, y, z, exits, flags}: exits a list of {dir, to, door, flags} (door: the door's name, \"\" without one, nil for no door), flags the mob and load flags in words."}],"returns":"true, or nil and why (\"map off\").","example":"mapRoom(id, function(r) if r then echo(r.name .. \" (\" .. r.terrain .. \")\") end end)"},"createPane":{"kind":"function","sig":"createPane{id, title, short, dock, lane, rows, cols, border, cross, tooltip, outline, anchor, temporary, at, group, grid} → pane","doc":"Makes the script's own pane and returns it. It docks, floats, toggles and is coloured like the built-in panes, and WebCockpit remembers where the player puts it.","params":[{"name":"id","type":"string","doc":"The pane's id within the script: 1 to 32 letters, digits, _ or -."},{"name":"title","type":"string?","doc":"The frame title (default: the id). pane:setTitle changes it."},{"name":"short","type":"string?","doc":"A short name of 1 to 8 characters for compact lists of panes (getPanes). Default: the first four letters and digits of the title, in capitals."},{"name":"dock","type":"string?","doc":"Where it goes the first time: \"right\" (default), \"left\", \"top\", \"bottom\" or \"float\"."},{"name":"lane","type":"string?","doc":"\"own\": the first time, the pane gets a lane of its own at the screen edge of its dock (a row of the top or bottom dock, a column at the side), as high (or wide) as rows (cols) plus the frame. Not for a float or a temporary pane."},{"name":"rows","type":"number?","doc":"Wanted height in rows (default 8): in a side dock and a float."},{"name":"cols","type":"number?","doc":"Wanted width in columns (default 30): in the top or bottom dock and a float."},{"name":"border","type":"boolean?","doc":"false: the first time, the pane has no frame (the player can turn it on with the pane's Border button). A borderless pane in the top or bottom dock can be a single row; drag it by its top row, past a few pixels (a click there is the pane's own). On hover the close cross shows over the last cells of its top row (one in from the right edge), framed or not."},{"name":"cross","type":"boolean?","doc":"false: no close cross on hover, for a pane whose top row ends in buttons, such as a one-row bar. The player turns it off in the Panes box, your script with pane:hide(). Not for a temporary pane. Default true: the cross shows over the last cells of the top row while the pane is hovered, over whatever is there, so keep a link out of them (it cannot be clicked while the cross covers it)."},{"name":"tooltip","type":"boolean?","doc":"Accepted and ignored: it once showed the title in a small tag on hover (gone). Old scripts that pass it still run."},{"name":"outline","type":"boolean?","doc":"false: while the pane has no frame, hovering it draws no outline around it, for a bar that should stay flat. Default true: a thin outline shows where the borderless pane ends."},{"name":"anchor","type":"string?","doc":"Where the view sticks when the lines do not fit: \"bottom\" (default, a console: it follows new lines while scrolled to the end) or \"top\" (a list: it stays at the first line)."},{"name":"temporary","type":"boolean?","doc":"true for a short-lived pane, such as a choice: it floats over the game text at rows × cols, above the other panes, is never listed in Options, and its close cross closes it (pane:close)."},{"name":"at","type":"string?","doc":"A temporary pane's place until the player moves it: \"center\" (default), \"top\", \"bottom\" (just above the input line), \"left\", \"right\", or a corner: \"top-left\", \"top-right\", \"bottom-left\", \"bottom-right\". Corners let several panes open side by side."},{"name":"group","type":"string?","doc":"Temporary panes only: panes of the script with the same group are tiled together from at's corner (top-left by default), in the order they opened, with no gaps; a closed one's place is taken by the ones after it. Dragging one moves the whole group, resizing one sets the size of all; both are kept on this device (Reset layout forgets them)."},{"name":"grid","type":"table?","doc":"A group's grid: {cols = 2} (default 2, at most 8). The panes go row by row; fewer columns when they do not fit the game text."}],"returns":"The pane, an object whose methods are called with a colon: pane:echo(\"text\").","example":"local pane = createPane{id = \"hp\", title = \"Health\", dock = \"right\", rows = 3}\npane:gauge(1, {value = 80, max = 120, color = \"green\", label = \"HP 80/120\"})"},"pane:clear":{"kind":"function","sig":"pane:clear()","doc":"Empties the pane: every line and link goes.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."}],"example":"pane:clear()\npane:echo(\"Nothing to show.\")"},"pane:echo":{"kind":"function","sig":"pane:echo(text)","doc":"Appends plain text to the pane. A \\n starts a new line.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"text","type":"string","doc":"The text, as is (angle brackets are text)."}],"example":"pane:echo(\"Kills: \" .. kills .. \"\\n\")"},"pane:cecho":{"kind":"function","sig":"pane:cecho(text)","doc":"Appends coloured text to the pane, with the colour tags of cecho. A \\n starts a new line.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"text","type":"string","doc":"Text with colour tags such as <red>, <~gold>, <b> or <reset>, and the pane's shades such as <@dim> (see the Panes chapter)."}],"example":"pane:cecho(\"<green>ready<reset>\\n\")"},"pane:setLine":{"kind":"function","sig":"pane:setLine(row, text)","doc":"Replaces one row with coloured text (the cecho tags). Rows past the end are added as empty lines.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"row","type":"number","doc":"The row, from 1 (at most 500)."},{"name":"text","type":"string","doc":"Text with colour tags, the pane's shades (<@dim>) too; a \\n becomes a space."}],"example":"pane:setLine(1, \"<b>Mercenaries</b>\")\npane:setLine(2, \"Bob  <yellow>waiting\")"},"pane:gauge":{"kind":"function","sig":"pane:gauge(row, {value, max, color, label, col, width, align, track})","doc":"Draws a bar on one row, like the bars of the Group pane: value of max filled, label over it. Without col and width it fills the whole row; with them it covers part of the row, so one row can hold several bars and text.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"row","type":"number","doc":"The row, from 1."},{"name":"gauge","type":"table","doc":"value and max (numbers; max defaults to 100), color (a colour name such as \"red\", \"<#ff8800>\" or \"orange\"; default green; not the pane's shades), label (text over the bar), col (the first column, from 1), width (cells; default to the pane's right edge), align (\"center\", the default, \"left\" or \"right\": where the label sits) and track (the colour of the unfilled part, or false for none)."}],"example":"pane:gauge(2, {value = 30, max = 60, color = \"orange\", label = \"30 min left\"})\n-- Three bars on one row, the name over them.\npane:gauge(3, {col = 1, width = 10, value = hp, max = maxhp, color = \"#005a18\"})\npane:gauge(3, {col = 11, width = 10, value = mana, max = maxmana, color = \"#0000aa\"})\npane:gauge(3, {col = 21, value = mv, max = maxmv, color = \"#5a3c1e\"})\npane:setText(3, 1, \"<@text>Gimli\")"},"pane:cechoLink":{"kind":"function","sig":"pane:cechoLink(text, fn, hint, opts)","doc":"Appends coloured text that calls fn when it is clicked, with hint as its tooltip.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"text","type":"string","doc":"Text with colour tags and the pane's shades; it goes on the end of the last line, as pane:cecho (a \\n becomes a space)."},{"name":"fn","type":"function","doc":"Called with no arguments on a click."},{"name":"hint","type":"string?","doc":"The tooltip shown while the pointer is over the link; \\n breaks it into lines."},{"name":"opts","type":"table?","doc":"{hover = \"band\" | \"lighten\" | \"none\"}: how this link looks under the pointer (default: the pane's, see pane:setHover)."}],"example":"pane:cechoLink(\"<u>[pay]</u>\", function()\n  send(\"pay mercenary\")\nend, \"Pay the mercenary\")"},"pane:setLink":{"kind":"function","sig":"pane:setLink(row, col, len, fn, hint, opts)","doc":"Makes len cells of a row, from column col, call fn when clicked, with hint as their tooltip. Any span, down to one cell.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"row","type":"number","doc":"The row, from 1."},{"name":"col","type":"number","doc":"The first column, from 1."},{"name":"len","type":"number","doc":"How many cells, at least 1."},{"name":"fn","type":"function?","doc":"Called with no arguments on a click; nil for a tooltip only (not clickable, no hover look)."},{"name":"hint","type":"string?","doc":"The tooltip."},{"name":"opts","type":"table?","doc":"{hover = \"band\" | \"lighten\" | \"none\"}: how this link looks under the pointer (default: the pane's, see pane:setHover)."}],"example":"pane:setLine(3, \"[x] Bob\")\npane:setLink(3, 2, 1, function()\n  send(\"order bob leave\")\nend, \"Send Bob away\")"},"pane:setHover":{"kind":"function","sig":"pane:setHover(style)","doc":"Chooses how the pane's links look under the pointer: \"band\" (the default) draws them in the pane's glow band, \"lighten\" makes their own text and background a step lighter, \"none\" leaves them as they are (the pointer and the tooltip still show).","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"style","type":"string?","doc":"\"band\", \"lighten\" or \"none\"; nil is \"band\"."}],"example":"pane:setHover(\"lighten\")\npane:setLine(1, \"<@bg:@glow> ON <reset> <@mid:@track> OFF \")\npane:setLink(1, 1, 4, function() send(\"on\") end, \"On\")\npane:setLink(1, 6, 5, function() send(\"off\") end, \"Off\", {hover = \"none\"})"},"pane:setText":{"kind":"function","sig":"pane:setText(row, col, text)","doc":"Writes text over the cells of a row from column col, keeping the row's other cells, its links and its text fields. For a counter or a status cell that changes often.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"row","type":"number","doc":"The row, from 1 (a text row, not a full-row gauge; bars from pane:gauge with col stay under the text)."},{"name":"col","type":"number","doc":"The first column, from 1; a shorter row is padded with spaces."},{"name":"text","type":"string","doc":"Text with colour tags and the pane's shades (<@dim>)."}],"example":"pane:setLine(1, \" HP:      [rest]\")\npane:setLink(1, 11, 6, function() send(\"rest\") end, \"Rest\")\npane:setText(1, 6, \"<green>120\")"},"pane:setInput":{"kind":"function","sig":"pane:setInput(row, col, len, opts) → field","doc":"Puts an editable one-line text field on len cells of a row, from column col, and returns it. Enter, Esc and typing call the functions in opts.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"row","type":"number","doc":"The row, from 1."},{"name":"col","type":"number","doc":"The first column, from 1."},{"name":"len","type":"number","doc":"How many cells wide, at least 1. Longer text scrolls inside the field."},{"name":"opts","type":"table?","doc":"value (the text to start with), placeholder (grey text while it is empty), maxLength (most characters), onSubmit(text) (Enter), onCancel() (Esc), onChange(text) (each edit), onBlur(text) (the field lost the keyboard to a click elsewhere, not by Enter or Esc) and onKey(key) (Up, Down, PgUp, PgDn, Tab, Shift+Tab: ArrowUp, ArrowDown, PageUp, PageDown, Tab, Shift+Tab, and the keys of keys). keys: a list of more key names for onKey, as tempKey names them (e.g. {\"Ctrl+F\"}): macros and script keys do not run while the field has the keyboard, so a script's own toggle key can come here instead."}],"returns":"A field: field:focus(), field:select(), field:value(), field:setValue(text), field:remove().","example":"pane:setLine(1, \"Name: \")\nlocal name = pane:setInput(1, 7, 12, {\n  value = \"home\",\n  onSubmit = function(text) echo(\"You typed \" .. text) end,\n  onCancel = function() pane:close() end,\n})\nname:select()"},"field:focus":{"kind":"function","sig":"field:focus()","doc":"Gives the keyboard to the text field (from pane:setInput), with the cursor after its text.","params":[{"name":"field","type":"field","doc":"A field from pane:setInput."}],"example":"name:focus()"},"field:select":{"kind":"function","sig":"field:select()","doc":"Gives the keyboard to the text field with all its text selected, so typing replaces it.","params":[{"name":"field","type":"field","doc":"A field from pane:setInput."}],"example":"name:select()"},"field:value":{"kind":"function","sig":"field:value() → string","doc":"The field's text now; nil once the field is gone.","params":[{"name":"field","type":"field","doc":"A field from pane:setInput."}],"returns":"The text, or nil.","example":"local text = name:value()"},"field:setValue":{"kind":"function","sig":"field:setValue(text)","doc":"Replaces the field's text (one line, cut to its maxLength). onChange is not called.","params":[{"name":"field","type":"field","doc":"A field from pane:setInput."},{"name":"text","type":"string","doc":"The new text."}],"example":"name:setValue(\"\")"},"field:remove":{"kind":"function","sig":"field:remove()","doc":"Takes the field away; the keyboard goes back to the input line if the field had it. Its methods then do nothing.","params":[{"name":"field","type":"field","doc":"A field from pane:setInput."}],"example":"name:remove()"},"pane:setCheckbox":{"kind":"function","sig":"pane:setCheckbox(row, col, opts) → toggle","doc":"Draws a checkbox, [ ] Label, from column col of a row and returns it. A click or a tap on it flips it ([x]) and calls opts.onChange(checked).","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"row","type":"number","doc":"The row, from 1."},{"name":"col","type":"number","doc":"The first column, from 1."},{"name":"opts","type":"table?","doc":"label (colour tags allowed), checked (default false), hint (a tooltip) and onChange(checked)."}],"returns":"A toggle: toggle:checked(), toggle:set(on), toggle:remove().","example":"local cs = pane:setCheckbox(2, 1, {label = \"Case sensitive\", onChange = function(on) caseSensitive = on end})"},"pane:setRadio":{"kind":"function","sig":"pane:setRadio(row, col, opts) → toggle","doc":"Draws a radio button, ( ) Label, or (•) Label when chosen. Of the radio buttons of one group in the pane one is chosen at a time: a click chooses this one and calls opts.onChange(value).","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"row","type":"number","doc":"The row, from 1."},{"name":"col","type":"number","doc":"The first column, from 1."},{"name":"opts","type":"table","doc":"group (a name, required), value (what onChange gets; default the label), label (colour tags allowed), checked, hint (a tooltip) and onChange(value)."}],"returns":"A toggle: toggle:checked(), toggle:set(on), toggle:remove().","example":"for i, f in ipairs({\"name\", \"desc\", \"note\"}) do\n  pane:setRadio(1, i * 8 - 7, {group = \"field\", value = f, label = f, checked = f == field,\n    onChange = function(v) field = v end})\nend"},"toggle:checked":{"kind":"function","sig":"toggle:checked() → boolean","doc":"Whether the checkbox or radio button is checked; nil once it is gone.","params":[{"name":"toggle","type":"toggle","doc":"A toggle from pane:setCheckbox or pane:setRadio."}],"returns":"true, false, or nil.","example":"if cs:checked() then echo(\"case counts\") end"},"toggle:set":{"kind":"function","sig":"toggle:set(on)","doc":"Checks or unchecks it and redraws it; onChange is not called. A radio button set on unchooses the others of its group.","params":[{"name":"toggle","type":"toggle","doc":"A toggle from pane:setCheckbox or pane:setRadio."},{"name":"on","type":"boolean","doc":"Checked or not."}],"example":"cs:set(false)"},"toggle:remove":{"kind":"function","sig":"toggle:remove()","doc":"Takes the checkbox or radio button away and blanks its cells. Its methods then do nothing.","params":[{"name":"toggle","type":"toggle","doc":"A toggle from pane:setCheckbox or pane:setRadio."}],"example":"cs:remove()"},"pane:size":{"kind":"function","sig":"pane:size() → rows, cols","doc":"The pane's content size in cells now: rows and columns. Both are 0 while the pane is not shown.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."}],"returns":"rows, cols (two numbers).","example":"local rows, cols = pane:size()\npane:setLine(1, string.rep(\"-\", cols))"},"pane:onResize":{"kind":"function","sig":"pane:onResize(fn)","doc":"Calls fn(rows, cols) when the pane's size changes, also when it is first shown. nil removes the handler.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"fn","type":"function?","doc":"Called with the new rows and cols; nil removes it."}],"example":"pane:onResize(function(rows, cols)\n  pane:setLine(1, string.rep(\"=\", cols))\nend)"},"pane:theme":{"kind":"function","sig":"pane:theme() → table","doc":"The pane's colours now, as #rrggbb: for drawing in the pane's own look, such as a bar's track or a text colour that suits a light pane.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."}],"returns":"A table: light (true on a light, paper pane), bg (the pane's background), fg (the colour of text without a colour tag) and shades, a table of the pane's shades by their tag names: track, dim, mid, bg, text, label and glow, as <@track> … <@glow>. nil once the pane is closed.","example":"local th = pane:theme()\nif th.light then\n  pane:setLine(1, \"<@text>paper\")\nend"},"pane:fillColor":{"kind":"function","sig":"pane:fillColor(color) → string","doc":"The colour pane:gauge fills a bar with for color: as is on a dark pane, washed to a pastel on a light one. For drawing bars of your own with background tags.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"color","type":"string","doc":"A colour name, as pane:gauge's color: \"red\", \"ansi_red\", \"<#ff8800>\" or \"#ff8800\"."}],"returns":"The colour as #rrggbb; nil once the pane is closed.","example":"pane:setText(1, 1, \"<:\" .. pane:fillColor(\"#0000aa\") .. \">    \")"},"pane:onTheme":{"kind":"function","sig":"pane:onTheme(fn)","doc":"Calls fn(theme) when the pane's colours change: another pane colour, terminal colour or theme in the settings. theme is what pane:theme() returns. nil removes the handler.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"fn","type":"function?","doc":"Called with the new theme; nil removes it."}],"example":"-- A bar of your own, in the gauge colour for this pane.\nlocal function draw()\n  pane:setText(1, 1, \"<:\" .. pane:fillColor(\"#0000aa\") .. \">      \")\nend\ndraw()\npane:onTheme(draw)"},"wrapText":{"kind":"function","sig":"wrapText(text, width, indent) → table","doc":"Word-wraps text to width cells, for a pane: returns the lines as a list, each ready for pane:setLine. Colour tags work and take no cells.","params":[{"name":"text","type":"string","doc":"The text; colour tags (and pane shades such as <@dim>) work. A \\n always starts a new line."},{"name":"width","type":"number","doc":"The most cells per line, usually cols from pane:size() or onResize. Under 1 or nil: the text is only split at \\n."},{"name":"indent","type":"number?","doc":"Spaces before every line after the first of a paragraph (a hanging indent); they count toward width. Default 0."}],"returns":"A list of strings, from 1.","example":"pane:onResize(function(rows, cols)\n  pane:clear()\n  for i, l in ipairs(wrapText(msg, cols, 2)) do pane:setLine(i, l) end\nend)"},"pane:onWheel":{"kind":"function","sig":"pane:onWheel(fn)","doc":"Calls fn(dx, dy) when the wheel or the touchpad scrolls over the pane, in whole cells: dx sideways (positive = right), dy up and down (positive = down). Return true to take the scroll; nil removes the handler.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"fn","type":"function?","doc":"Called with the steps in cells; true from it takes the scroll. nil removes it."}],"returns":"Nothing. fn returns true to take the scroll, anything else leaves it to the pane.","example":"local first = 1\npane:onWheel(function(dx, dy)\n  first = math.max(1, first + dx)\n  pane:setLine(1, \"from column \" .. first)\n  return true\nend)"},"pane:show":{"kind":"function","sig":"pane:show()","doc":"Switches the pane on, as its switch in the Panes box does.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."}],"example":"tempAlias(\"^merc$\", function()\n  if pane:visible() then pane:hide() else pane:show() end\nend)"},"pane:hide":{"kind":"function","sig":"pane:hide()","doc":"Switches the pane off, as its close cross does. The script keeps writing to it.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."}],"example":"pane:hide()"},"pane:visible":{"kind":"function","sig":"pane:visible() → boolean","doc":"true when the pane is switched on (it may still lack room in a small window).","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."}],"returns":"true or false.","example":"if not pane:visible() then echo(\"The pane is off; pane:show() brings it back.\") end"},"pane:setTitle":{"kind":"function","sig":"pane:setTitle(text)","doc":"Changes the title in the pane's frame and in the Panes box.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"text","type":"string","doc":"The new title (at most 60 characters)."}],"example":"pane:setTitle(\"Mercenaries (\" .. count .. \")\")"},"pane:close":{"kind":"function","sig":"pane:close()","doc":"Takes the pane away. Its methods then do nothing; createPane with the same id makes a new pane.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."}],"example":"local pick = createPane{id = \"pick\", title = \"Pick\", temporary = true, rows = 2, cols = 24}\ntempTimer(5, function() pick:close() end)"},"pane:onClose":{"kind":"function","sig":"pane:onClose(fn)","doc":"Calls fn() when the player closes a temporary pane with its close cross. nil removes the handler.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"fn","type":"function?","doc":"Called with no arguments, after the pane is gone; nil removes it."}],"example":"pick:onClose(function()\n  echo(\"No choice made.\")\nend)"},"pane:dock":{"kind":"function","sig":"pane:dock() → string","doc":"Where the pane is now: \"left\", \"right\", \"top\", \"bottom\" or \"float\" (a temporary pane is always \"float\").","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."}],"returns":"The dock name or \"float\"; nil after pane:close().","example":"local side = pane:dock() == \"left\" or pane:dock() == \"right\""},"pane:wantSize":{"kind":"function","sig":"pane:wantSize(rows, cols) → boolean","doc":"Asks for a content size for the pane where it is docked now: rows in a side dock; in the top or bottom dock rows set its lane's height when it is alone in the lane, and cols its width along the lane.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"rows","type":"number","doc":"Wanted rows, from 1."},{"name":"cols","type":"number?","doc":"Wanted columns (the top and bottom docks)."}],"returns":"true when the request applies where the pane is, false for a float or a temporary pane.","example":"pane:wantSize(#lines)"},"pane:setGrip":{"kind":"function","sig":"pane:setGrip(row, col, len)","doc":"Makes len cells of a row, from column col, a grip that drags the pane: the pointer turns into a grabbing hand there, and a press starts a move at once, as on the title row. For a pane without a frame, or any row of one.","params":[{"name":"pane","type":"pane","doc":"A pane from createPane."},{"name":"row","type":"number?","doc":"The row, from 1; nil removes the grip."},{"name":"col","type":"number","doc":"The first column, from 1."},{"name":"len","type":"number?","doc":"How many cells, at least 1 (default 1)."}],"example":"pane:setLine(1, \"<@mid>∷<reset> [a] [b]\")\npane:setGrip(1, 1, 2)"},"getPanes":{"kind":"function","sig":"getPanes() → list","doc":"Every pane in the Panes box's order: the built-in panes, then the panes of the scripts that run. Temporary panes are not listed.","params":[],"returns":"A list of tables {id, title, short, on, shown, dock, script, own}: on is the player's on/off, shown is true when it is on the screen now (on and room for it), dock is \"left\", \"right\", \"top\", \"bottom\" or \"float\", script names the script that owns it (nil for a built-in pane) and own is true for this script's own panes.","example":"for _, p in ipairs(getPanes()) do\n  if not p.own then echo(p.short .. (p.on and \" on\" or \" off\") .. \"\\n\") end\nend"},"setPaneOn":{"kind":"function","sig":"setPaneOn(id, on) → boolean","doc":"Switches any pane on or off, as its close cross and the Panes box do.","params":[{"name":"id","type":"string","doc":"A pane id from getPanes (\"comm\", \"merc/main\")."},{"name":"on","type":"boolean","doc":"true to show it, false to hide it."}],"returns":"true, or false when there is no such pane now (an unknown id, a temporary pane, or a pane of a script that is not running).","example":"setPaneOn(\"map\", false)"},"settings":{"kind":"variable","sig":"settings.<name>","doc":"The values of the header's @setting lines (read-only). The player changes one on the Scripts page or with #script set {script} {setting} {value}.","example":"-- @setting  auto  boolean true \"Loot after kills\"\nif settings.auto then send(\"get coins all.corpse\") end"},"setSetting":{"kind":"function","sig":"setSetting(name, value)","doc":"Saves one of this script's own @setting values, as #script set does. settings.<name> shows it once saved.","params":[{"name":"name","type":"string","doc":"A setting the header declares with @setting; another name is an error."},{"name":"value","type":"any","doc":"A string, number or boolean, converted to the setting's type. A number must be inside the setting's range, a choice one of its options."}],"example":"tempAlias(\"^autoloot (on|off)$\", function()\n  setSetting(\"auto\", matches[2] == \"on\")\nend)"},"scriptName":{"kind":"variable","sig":"scriptName","doc":"This script's name, as on the Scripts page (a Duplicate has its own).","example":"echo(\"Change it with #script set \" .. scriptName .. \" delay 1\")"},"gmcp":{"kind":"variable","sig":"gmcp.<Package>.<Message>","doc":"The last GMCP data from MUME, as in Mudlet: gmcp.Char.Vitals.hp, gmcp.Room.Info.name … (read-only).","example":"local v = gmcp.Char and gmcp.Char.Vitals\nif v and v.hp then\n  echo(\"HP \" .. v.hp .. \"/\" .. (v.maxhp or \"?\"))\nend"},"state":{"kind":"variable","sig":"state.char / state.group / state.room","doc":"Read-only view of the character (name, vitals, status), the group members and the room.","example":"for _, m in ipairs(state.group) do\n  echo(m.name .. \": \" .. (m.hp.word or \"?\"))\nend"},"matches":{"kind":"variable","sig":"matches[1], matches[2] …","doc":"In a trigger or alias: the whole match, then each group.","example":"tempRegexTrigger(\"^(\\\\w+) has arrived\", function()\n  echo(\"Hello, \" .. matches[2])\nend)"},"line":{"kind":"variable","sig":"line","doc":"In a trigger: the game line. In an alias: the typed command.","example":"tempTrigger(\"R.I.P.\", function()\n  uiMessage(\"death\", line)\nend)"},"command":{"kind":"variable","sig":"command","doc":"In an alias: the typed command.","example":"tempAlias(\"^say \", function()\n  echo(\"You said: \" .. command)\n  return false -- send it too\nend)"}}};
